/* ─── Preset option preview thumbnails ─────────────────────────────────────
   Each preview is a framed mini canvas (`.pv`) depicting what the option does.
   Shared building blocks (pv-line / pv-chip / pv-card …) keep the set coherent.
   See src/components/PresetOptionPreview.tsx. */

.pv {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 4px;
  width: 100%;
  min-height: 62px;
  padding: 12px;
  border: 1px solid #eef0f4;
  border-radius: var(--fn-r-sm);
  background: #ffffff;
  overflow: hidden;
  color: var(--accent);
  transition: border-color var(--motion-fast) var(--ease-out),
    background var(--motion-fast) var(--ease-out);
}

.preset-option[data-active="true"] .pv,
.preset-option:hover .pv {
  border-color: #eef0f4;
  background: var(--surface-panel);
}

/* Generic line primitive ---------------------------------------------------- */
/* Cards that show the control itself — an icon and its words — rather than an
   abstraction of it.

   Two to a row like every other card, and only as tall as they need. At that
   width the box has to give up padding to the content: the default 12px of cell,
   12px of card and 12px of tile leave 33px of usable width, and an icon with
   four characters needs about 55px, so 新建对话 broke onto two lines. Trimming
   all three paddings and dropping the label a point buys the room.

   Scoped with `:has()` rather than by group name, so it follows the cards. */
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option-cell:has(.pv[data-kind="control"]),
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option-cell:has(.pv[data-kind="thinking"]),
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option-cell:has(.pv[data-kind="done-body"]),
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option-cell:has(.pv[data-kind="reasoning-done"]) {
  padding: 8px;
}

/* Specificity matched to the rule that makes every option card square, which
   carries the same three `:not([...])` clauses — a shorter selector lost
   silently and the cards stayed 165px tall for a 38px control. */
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="control"]),
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="thinking"]),
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="done-body"]),
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="reasoning-done"]) {
  aspect-ratio: auto;
  height: auto;
  min-height: 0;
  padding: 6px;
}

/* One height for the whole set. The contents are different shapes — a lone
   magnifier, two stacked date headings — and side by side, tiles that differ by
   a few pixels read as a mistake rather than as content. 42px is the tallest of
   them (two 14px date headings, the 4px gap, padding and border), so nothing is
   squeezed. */
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="control"]) .pv,
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="thinking"]) .pv,
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="done-body"]) .pv,
.preset-panel:not([data-preset-group="conversation"]):not([data-preset-group="provider"]):not([data-preset-group="git"])
  .preset-option:has(.pv[data-kind="reasoning-done"]) .pv {
  min-height: 42px;
}

/* Fixed, not just floored, for the two settled-block kinds.
   `min-height` leaves the frame free to stretch, and the grid equalises row
   heights: "Segment count" wraps to two lines, its row grows, and the extra
   went into the *neighbour's* frame — the Conclusion tile measured 49px against
   42px for the rest, from a label it does not contain. Pinning the frame sends
   the slack to the label area, where it is invisible. */
.preset-panel
  .preset-option:has(.pv[data-kind="done-body"]) .pv,
.preset-panel
  .preset-option:has(.pv[data-kind="reasoning-done"]) .pv {
  height: 42px;
  flex: none;
}

.pv[data-kind="control"],
.pv[data-kind="thinking"],
.pv[data-kind="reasoning-done"] {
  display: flex;
  align-items: center;
  padding: 4px;
}

/* The transcript's reasoning row, at card scale: the indicator and the word it
   sits next to. The indicator is scaled rather than re-sized — it is the real
   component, and its inner geometry (the lattice, the orbit) is built in px. */
.pv-thinking {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  width: 100%;
  min-width: 0;
}

/* `zoom`, not `transform: scale` — the transform shrank the picture and left
   the layout box its full size, so the widest indicator (波形条, 28px against
   the others' 19px) pushed 思考中 out of a 54px card and the words were clipped
   to 思考屮. Zoom scales the box too, which is the whole point here. */
.pv-thinking .reasoning-indicator-slot {
  flex: none;
  zoom: 0.72;
}

.pv-thinking-label {
  min-width: 0;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  line-height: 13px;
  white-space: nowrap;
}

.pv[data-kind="control"] .pv-control {
  gap: 2px;
  justify-content: center;
}

/* Wraps rather than clips: if a locale's wording outgrows the card, two short
   lines still say what it is, where a cut-off first line does not. */
.pv-control-label {
  font-size: 10px;
  white-space: normal;
}
.pv-control {
  display: flex;
  gap: 6px;
  align-items: center;
  width: 100%;
  color: var(--text-primary);
}

.pv-control[data-align="center"] {
  justify-content: center;
}

.pv-control-label {
  font-weight: 600;
  line-height: 13px;
  text-align: center;
}

/* ---- The sidebar's eight cards: a miniature column, one part in ink ------
   `MiniSidebar` in PresetOptionPreview. Everything out of focus is a skeleton
   bar in the muted tone; the focused part is drawn at full ink with the real
   words and icons. One frame for all eight — the same 42px `.pv` the other
   control cards use — so the grid stays even. */
/* Pinned, with the specificity of the panel's own height rule, so a card's
   content can never grow its frame: the grid reads even only if it is. */
/* `.pv` repeated for weight: the panel's sizing rules carry three `:not()`
   clauses, and this has to outrank them without `!important`. */
.preset-panel .preset-option .pv.pv.pv.pv[data-kind="control"]:has(.msb) {
  align-items: stretch;
  height: 42px;
  min-height: 0;
  padding: 4px 6px;
  flex: none;
  overflow: hidden;
}

.msb {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 2px;
  width: 100%;
  min-width: 0;
  color: var(--text-muted);
}

.msb svg {
  display: block;
}

.msb-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 3px;
  height: 9px;
  margin-bottom: 1px;
}

.msb-head[hidden] {
  display: none;
}

.msb-skel {
  display: block;
  flex: none;
  height: 3px;
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--text-muted) 24%, transparent);
}

.msb-skel-title {
  width: 22px;
  height: 4px;
}

.msb-tools {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.msb-dot {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 2px;
  background: color-mix(in srgb, var(--text-muted) 20%, transparent);
}

.msb [data-on="true"] {
  color: var(--text-primary);
}

.msb-tools [data-on="true"] {
  display: inline-grid;
  place-items: center;
}

.msb-title {
  overflow: hidden;
  max-width: 44px;
  font-size: 7.5px;
  font-weight: 760;
  line-height: 9px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.msb-new {
  display: flex;
  align-items: center;
  gap: 2px;
  font-size: 7.5px;
  font-weight: 650;
  line-height: 8px;
  white-space: nowrap;
}

.msb-row {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 7px;
  padding: 0 2px;
  border-radius: 2px;
}

.msb-row[data-active="true"] {
  background: color-mix(in srgb, var(--text-primary) 8%, transparent);
}

.msb-row svg {
  flex: none;
}

.msb-text {
  overflow: hidden;
  min-width: 0;
  font-size: 7px;
  line-height: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.msb-group {
  font-size: 6.5px;
  font-weight: 650;
  line-height: 7px;
}

.msb-version {
  margin-top: auto;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 7px;
  line-height: 8px;
}

/* The brand line, at the card's scale: the weight is what makes it read as a
   title rather than as a label. */
.pv-brand {
  font-size: 10px;
  font-weight: 760;
  line-height: 13px;
  color: var(--text-primary);
}

/* Two conversation rows, the first one open — the list as the column draws it.
   Ellipsized rather than wrapped: a 55px card cannot hold a whole prompt, and
   a truncated row is what the real column shows too. */
.pv-sessions {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 100%;
  min-width: 0;
}

.pv-session {
  border-radius: 3px;
  padding: 1px 3px;
  color: var(--text-muted);
  font-size: 9px;
  line-height: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pv-session[data-active="true"] {
  background: color-mix(in srgb, var(--text-primary) 8%, transparent);
  color: var(--text-primary);
}

/* The reasoning-done card joined the `thinking` cards' rules above rather than
   carrying its own copies of them: cell padding, aspect ratio, min height and
   tile padding all come from one place now, so the two cannot drift apart.
   It used to span both columns, on the grounds that 已思考（用时 11 秒）had no
   half-panel to fit in. The phrase is 已思考 15 秒 now, which does. */

/* One line, centred. The glyph and the chevron it used to sit beside are gone
   from the card — neither is something this option changes. */
.pv-reasoning-done {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-width: 0;
}

/* Wraps rather than truncating. 已思考 15 秒 is longer than the motion labels
   beside it, and at this tile width `nowrap` + ellipsis rendered it as
   "已思…" — a card whose whole content is one phrase cannot afford to clip it. */
.pv-reasoning-done-title {
  min-width: 0;
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 600;
  line-height: 13px;
  text-align: center;
  text-wrap: balance;
}

/* The *Conclusion* card is the one whose title is a sentence, not a label, so
   it is the one that has to clip. Two lines then a fade: the reader needs to
   see that the title becomes prose — the words themselves are a sample — and a
   hard ellipsis at 10px reads as a rendering fault rather than as continuation.

   Capped by `max-height`, not by `-webkit-line-clamp`, because the height is
   what has to be guaranteed: three clamped lines measured 39px and grew the
   card to 67px against the other seven at 56px, and a grid of cards that
   differ by 11px reads as a bug rather than as content. 26px is two 13px
   lines, which clears the 42px the tile reserves.

   `text-wrap` back to `pretty`: `balance` on clipped text spends its work
   evening out lines the reader never sees the end of. */
.pv-reasoning-done-title[data-sample="conclusion"] {
  overflow: hidden;
  max-height: 26px;
  font-weight: 500;
  text-align: left;
  text-wrap: pretty;
  mask-image: linear-gradient(to bottom, #000 0%, #000 55%, transparent 100%);
}

/* ---- Thinking · settled body -------------------------------------------- */

/* The body axis changes a shape, so its four cards are shapes: a title bar with
   or without its chevron, and however much body survives underneath. Top-
   aligned, unlike the title cards — these read downward, and centring a
   one-element card ("title only") against a three-element one would make the
   title bars sit at different heights across the four. */
.pv[data-kind="done-body"] {
  display: flex;
  align-items: flex-start;
  padding: 5px;
}

.pv-done-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  min-width: 0;
}

.pv-done-body-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

/* The disclosure control, as a glyph-free wedge: a 4px square rotated and
   half-bordered. Drawing it in CSS rather than importing the chevron keeps the
   card from claiming a specific icon — the icon is whatever the style maps. */
.pv-done-chevron {
  width: 4px;
  height: 4px;
  border-right: 1.5px solid var(--text-muted);
  border-bottom: 1.5px solid var(--text-muted);
  border-radius: 1px;
  transform: rotate(45deg);
  transform-origin: center;
}

/* One line, faded out — the same gesture the canvas makes, at card scale. */
.pv-done-body-peek {
  display: flex;
  mask-image: linear-gradient(to right, #000 0%, #000 45%, transparent 100%);
}

/* Ruled off down the left edge. The rule is the card's whole content, so it
   takes `--text-muted` — the chevron's colour — rather than a border token:
   at `--border-subtle` it came out fainter than the body lines beside it, which
   made the one mark the card is about the least visible thing on it. */
.pv-done-body-quoted {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-left: 5px;
  border-left: 1.5px solid var(--text-muted);
}

/* The date headings, stacked, which is what the grouping is. */
.pv-eyebrow {
  color: var(--text-muted);
  font-size: 10px;
  line-height: 14px;
}

.pv-version {
  color: var(--text-muted);
  font-size: 10px;
  line-height: 14px;
}

.pv-line {
  display: block;
  height: 3px;
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--text-muted) 38%, var(--surface-inset));
}
.pv-line[data-tone="accent"] {
  background: color-mix(in srgb, var(--accent) 70%, transparent);
}
.pv-line[data-tone="muted"] {
  background: color-mix(in srgb, var(--text-muted) 26%, transparent);
}
.pv-line[data-tone="add"] {
  background: color-mix(in srgb, var(--success) 65%, transparent);
}
.pv-line[data-tone="del"] {
  background: color-mix(in srgb, var(--danger) 60%, transparent);
}

/* Kinds that center their content ------------------------------------------ */
.pv[data-kind="motion"],
.pv[data-kind="icon"],
.pv[data-kind="visual"],
.pv[data-kind="media-image"],
.pv[data-kind="media-image-grid"],
.pv[data-kind="media-image-dot-flicker"],
.pv[data-kind="media-image-blur-flow"],
.pv[data-kind="media-image-pixel-grid"],
.pv[data-kind="media-audio-skeleton"],
.pv[data-kind="media-audio-wave"],
.pv[data-kind="media-audio"],
.pv[data-kind="media-video"],
.pv[data-kind="shimmer"] {
  align-items: center;
  justify-content: center;
}

.pv[data-kind="media-image-grid"] {
  padding: 0;
  border: 0;
  background: transparent;
}

.pv[data-kind="media-image-dot-flicker"],
.pv[data-kind="media-image-blur-flow"],
.pv[data-kind="media-image-pixel-grid"],
.pv[data-kind="media-audio-skeleton"],
.pv[data-kind="media-audio-wave"] {
  padding: 0;
  border: 0;
  background: #f6f6f6;
}

.pv[data-kind="lines"],
.pv[data-kind="card"],
.pv[data-kind="bubble"],
.pv[data-kind="code"],
.pv[data-kind="diff"],
.pv[data-kind="terminal"] {
  justify-content: center;
}

.pv-media-frame,
.pv-media-audio-card,
.pv-media-video-frame {
  position: relative;
  display: grid;
  overflow: hidden;
  width: 48px;
  height: 34px;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border-subtle));
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 9%, var(--surface-inset));
}

.pv-media-frame::after,
.pv-media-video-frame::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg, transparent, color-mix(in srgb, white 64%, transparent), transparent);
  transform: translateX(-120%);
  animation: media-skeleton-sweep 1.7s var(--ease-in-out) infinite;
}

.pv-media-grid {
  position: absolute;
  inset: 5px;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 3px;
}

.pv-media-grid i,
.pv-media-video-strip i,
.pv-media-layers i {
  border-radius: 4px;
  background: color-mix(in srgb, var(--accent) 28%, var(--surface-panel));
}

.pv-media-layers {
  display: none;
}

.pv-media-caption {
  position: absolute;
  right: 6px;
  bottom: 5px;
  left: 6px;
  z-index: 1;
  height: 4px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 22%, transparent);
}

.pv-media-frame[data-media-style="blur"] .pv-media-grid i {
  filter: blur(1.4px);
  border-radius: 999px;
}

.pv-media-frame[data-media-style="palette"] .pv-media-grid {
  grid-template-columns: 1.4fr 0.8fr;
}

.pv-media-frame[data-media-style="palette"] .pv-media-grid i:nth-child(2n) {
  background: color-mix(in srgb, var(--accent-hover) 32%, var(--surface-panel));
}

.pv-media-frame[data-media-style="layers"] .pv-media-grid {
  display: none;
}

.pv-media-frame[data-media-style="layers"] .pv-media-layers {
  position: absolute;
  inset: 7px 9px;
  z-index: 1;
  display: grid;
}

.pv-media-frame[data-media-style="layers"] .pv-media-layers i {
  grid-area: 1 / 1;
  transform: translate(calc(var(--layer-index, 0) * 4px), calc(var(--layer-index, 0) * 3px));
}

.pv-media-frame[data-media-style="layers"] .pv-media-layers i:nth-child(2) { --layer-index: 1; opacity: 0.72; }
.pv-media-frame[data-media-style="layers"] .pv-media-layers i:nth-child(3) { --layer-index: 2; opacity: 0.48; }

.pv-media-audio-card {
  grid-template-columns: 12px 1fr;
  gap: 5px;
  align-items: center;
  padding: 5px;
}

.pv-media-audio-cover {
  width: 12px;
  height: 12px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--accent) 38%, var(--surface-panel));
}

.pv-media-wave {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 18px;
}

.pv-media-wave i {
  width: 2px;
  height: 40%;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 52%, var(--surface-panel));
  animation: media-wave-bounce 1.2s var(--ease-in-out) infinite;
}

.pv-media-wave i:nth-child(2n) { height: 72%; animation-delay: 90ms; }
.pv-media-wave i:nth-child(3n) { height: 54%; animation-delay: 160ms; }

.pv-media-audio-card[data-media-style="player"] .pv-media-wave {
  height: 4px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 18%, transparent);
}

.pv-media-audio-card[data-media-style="player"] .pv-media-wave i {
  display: none;
}

.pv-media-audio-card[data-media-style="spectrum"] .pv-media-wave i {
  width: 3px;
  border-radius: 2px;
}

.pv-media-audio-card[data-media-style="transcript"] .pv-media-wave {
  align-content: center;
  flex-wrap: wrap;
  gap: 3px;
}

.pv-media-audio-card[data-media-style="transcript"] .pv-media-wave i {
  width: 12px;
  height: 3px;
}

.pv-media-video-frame {
  place-items: center;
}

.pv-media-play {
  position: relative;
  z-index: 1;
  width: 13px;
  height: 13px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-panel) 82%, transparent);
}

.pv-media-video-strip {
  position: absolute;
  right: 6px;
  bottom: 5px;
  left: 6px;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
  height: 5px;
}

.pv-media-video-frame[data-media-style="cinema"] {
  height: 28px;
  border-radius: 5px;
}

.pv-media-video-frame[data-media-style="timeline"] .pv-media-video-strip {
  height: 3px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 18%, transparent);
}

.pv-media-video-frame[data-media-style="timeline"] .pv-media-video-strip i {
  border-radius: 999px;
}

.pv-media-video-frame[data-media-style="frames"] .pv-media-play {
  display: none;
}

.pv-media-video-frame[data-media-style="frames"] .pv-media-video-strip {
  inset: 6px;
  height: auto;
  grid-template-columns: repeat(2, 1fr);
}

/* Typewriter --------------------------------------------------------------- */
.pv-typing {
  display: flex;
  align-items: center;
  gap: 3px;
}
.pv-caret {
  display: inline-block;
  width: 2px;
  height: 9px;
  border-radius: 1px;
  background: var(--accent);
  animation: pv-blink 1s steps(1, end) infinite;
}
.pv-caret[data-solid="true"] {
  width: 6px;
  height: 9px;
  border-radius: 1px;
}
@keyframes pv-blink {
  0%, 50% { opacity: 1; }
  50.01%, 100% { opacity: 0; }
}

/* Chunked ------------------------------------------------------------------ */
.pv[data-kind="chunks"] {
  gap: 5px;
}
.pv-chunk {
  display: flex;
  gap: 4px;
}

/* Speaker labels ----------------------------------------------------------- */
.pv[data-kind="speaker"] {
  gap: 6px;
  justify-content: center;
}
.pv-turn {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pv-avatar {
  width: 9px;
  height: 9px;
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--accent) 55%, transparent);
  flex-shrink: 0;
}
.pv-avatar[data-role="agent"] {
  background: color-mix(in srgb, var(--text-muted) 45%, transparent);
}

/* Message bubble + actions ------------------------------------------------- */
.pv[data-kind="bubble"] {
  padding: 6px 7px;
}
.pv-actions {
  display: flex;
  gap: 4px;
  margin-top: 2px;
  color: var(--text-muted);
}
.pv-actions svg {
  display: block;
}
.pv-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  flex: none;
  border-radius: var(--radius-full);
  background: var(--text-muted);
}

/* Motion: dots ------------------------------------------------------------- */
.pv-dots {
  display: flex;
  gap: 4px;
}
.pv-dots i {
  width: 5px;
  height: 5px;
  border-radius: var(--radius-full);
  background: currentColor;
  animation: pv-dot-bounce 1.1s var(--ease-in-out) infinite;
}
.pv-dots i:nth-child(2) { animation-delay: 0.15s; }
.pv-dots i:nth-child(3) { animation-delay: 0.3s; }
@keyframes pv-dot-bounce {
  0%, 100% { opacity: 0.35; transform: translateY(1px); }
  50% { opacity: 1; transform: translateY(-1px); }
}

/* Motion: pulse ------------------------------------------------------------ */
.pv-pulse {
  width: 13px;
  height: 13px;
  border-radius: var(--radius-full);
  background: currentColor;
  animation: pv-pulse 1.4s var(--ease-in-out) infinite;
}
@keyframes pv-pulse {
  0%, 100% { transform: scale(0.7); opacity: 0.45; box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 30%, transparent); }
  50% { transform: scale(1); opacity: 1; box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 0%, transparent); }
}

/* Motion: terminal cursor -------------------------------------------------- */
.pv-term-line {
  display: flex;
  align-items: center;
  gap: 4px;
}
.pv-prompt {
  color: var(--accent);
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 1;
}

/* Motion: minimal ---------------------------------------------------------- */
.pv-minimal {
  width: 18px;
  height: 18px;
  border-radius: var(--radius-full);
  border: 2px solid color-mix(in srgb, var(--accent) 25%, transparent);
  border-top-color: var(--accent);
  animation: pv-spin 0.9s linear infinite;
}
@keyframes pv-spin {
  to { transform: rotate(360deg); }
}

/* Motion: shimmer text ----------------------------------------------------- */
.pv-shimmer-text {
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}
/* One span per character: each glyph runs the same shimmer, offset by its index
   so the light travels across the word without vertical bobbing. */
.pv-shimmer-text > span {
  display: inline-block;
  background: linear-gradient(
    100deg,
    var(--text-muted) 0%,
    var(--text-muted) 42%,
    color-mix(in srgb, var(--accent) 35%, #ffffff) 50%,
    var(--text-muted) 58%,
    var(--text-muted) 100%
  );
  background-size: 220% 100%;
  background-position: 120% 0;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: pv-shimmer 1.6s linear infinite;
  animation-delay: calc(var(--char-index, 0) * 0.12s);
}
@keyframes pv-shimmer {
  from { background-position: 120% 0; }
  to { background-position: -120% 0; }
}

/* Motion: bars (equalizer) ------------------------------------------------- */
.pv-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 16px;
}
.pv-bars i {
  width: 3px;
  border-radius: var(--radius-full);
  background: currentColor;
  animation: pv-bar 0.9s var(--ease-in-out) infinite;
}
.pv-bars i:nth-child(1) { height: 60%; animation-delay: 0s; }
.pv-bars i:nth-child(2) { height: 100%; animation-delay: 0.1s; }
.pv-bars i:nth-child(3) { height: 45%; animation-delay: 0.2s; }
.pv-bars i:nth-child(4) { height: 80%; animation-delay: 0.3s; }
@keyframes pv-bar {
  0%, 100% { transform: scaleY(0.4); opacity: 0.55; }
  50% { transform: scaleY(1); opacity: 1; }
}

/* Motion: orbit ------------------------------------------------------------ */
.pv-orbit {
  position: relative;
  width: 16px;
  height: 16px;
  border-radius: var(--radius-full);
  border: 1.5px solid color-mix(in srgb, var(--accent) 22%, transparent);
}
.pv-orbit::before {
  content: "";
  position: absolute;
  top: -2px;
  left: 50%;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  border-radius: var(--radius-full);
  background: var(--accent);
  transform-origin: 2.5px 10px;
  animation: pv-spin 1.1s linear infinite;
}

/* Card / disclosure / status ---------------------------------------------- */
.pv[data-kind="card"],
.pv[data-kind="tool-card"],
.pv[data-kind="collapsed"],
.pv[data-kind="approval"],
.pv[data-kind="error"],
.pv[data-kind="commit"],
.pv[data-kind="git"],
.pv[data-kind="provider"],
.pv[data-kind="status"] {
  background: var(--surface-panel);
}
.preset-option[data-active="true"] .pv[data-kind="card"],
.preset-option:hover .pv[data-kind="card"],
.preset-option[data-active="true"] .pv[data-kind="tool-card"],
.preset-option:hover .pv[data-kind="tool-card"] {
  background: var(--surface-raised);
}

.pv-row {
  display: flex;
  align-items: center;
  gap: 4px;
}
.pv[data-kind="status"],
.pv[data-kind="git"],
.pv[data-kind="commit"],
.pv[data-kind="provider"] {
  flex-direction: row;
  align-items: center;
  gap: 5px;
}
.pv[data-kind="git"] svg,
.pv[data-kind="commit"] svg {
  color: var(--accent);
  flex-shrink: 0;
}

.pv-chevron {
  width: 0;
  height: 0;
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
  border-top: 4px solid var(--text-muted);
  margin-left: auto;
  transition: transform var(--motion-fast) var(--ease-out);
}
.pv-chevron[data-open="true"] {
  transform: rotate(180deg);
}

.pv-status-dot {
  width: 7px;
  height: 7px;
  border-radius: var(--radius-full);
  background: var(--accent);
  flex-shrink: 0;
}
.pv-check {
  width: 9px;
  height: 9px;
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--success) 22%, transparent);
  border: 1.5px solid var(--success);
  flex-shrink: 0;
}
.pv-alert {
  width: 9px;
  height: 9px;
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--danger) 20%, transparent);
  border: 1.5px solid var(--danger);
  flex-shrink: 0;
}
.pv-provider-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--accent), color-mix(in srgb, var(--accent) 40%, var(--info)));
  flex-shrink: 0;
}

/* Chips -------------------------------------------------------------------- */
.pv[data-kind="chips"],
.pv[data-kind="chips-wrap"] {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  align-content: center;
  gap: 4px;
}
.pv-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 12px;
  min-width: 18px;
  padding: 0 4px;
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--accent) 55%, transparent);
  color: var(--text-inverse);
}
.pv-chip[data-soft="true"] {
  background: color-mix(in srgb, var(--accent) 14%, var(--surface-inset));
}
.pv-chip[data-icon="true"] {
  background: var(--accent);
}
.pv-chip svg { display: block; }

/* Timeline rail ------------------------------------------------------------ */
.pv[data-kind="timeline"] {
  position: relative;
  justify-content: center;
  gap: 4px;
  padding-left: 12px;
}
.pv-rail {
  position: absolute;
  /* Centre the rail on the node dots: dots sit at padding-left(12) + dot(5)/2 =
     14.5; rail (1.5px) centred there → left 13.75. */
  left: 13.75px;
  top: 9px;
  bottom: 9px;
  width: 1.5px;
  background: color-mix(in srgb, var(--accent) 30%, transparent);
}
.pv-rail-step {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pv-rail-step i {
  width: 5px;
  height: 5px;
  border-radius: var(--radius-full);
  background: var(--surface-panel);
  border: 1.5px solid var(--accent);
  flex-shrink: 0;
}

/* Terminal ----------------------------------------------------------------- */
.pv[data-kind="terminal"] {
  background: color-mix(in srgb, var(--text-primary) 88%, var(--accent));
  gap: 3px;
}
.pv[data-kind="terminal"] .pv-line[data-tone="muted"] {
  background: color-mix(in srgb, #ffffff 28%, transparent);
}
.pv-term-bar {
  display: flex;
  gap: 3px;
  margin-bottom: 1px;
}
.pv-term-bar i {
  width: 4px;
  height: 4px;
  border-radius: var(--radius-full);
  background: color-mix(in srgb, #ffffff 35%, transparent);
}

/* Progress / budget bar ---------------------------------------------------- */
.pv-bar {
  height: 5px;
  border-radius: var(--radius-full);
  background: var(--surface-inset);
  overflow: hidden;
}
.pv-bar-fill {
  display: block;
  height: 100%;
  width: 65%;
  border-radius: var(--radius-full);
  background: var(--accent);
}
.pv-bar-fill[data-level="mid"] { width: 50%; }

/* Approval buttons --------------------------------------------------------- */
.pv-banner {
  height: 7px;
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--warning) 26%, var(--surface-inset));
}
.pv-btn-row {
  display: flex;
  gap: 3px;
  margin-top: 2px;
}
.pv-btn {
  flex: 1;
  height: 7px;
  border-radius: var(--radius-sm);
  background: var(--surface-inset);
  border: 1px solid var(--border-subtle);
}
.pv-btn[data-variant="primary"] {
  background: var(--accent);
  border-color: var(--accent);
}

/* Code --------------------------------------------------------------------- */
.pv[data-kind="code"] {
  background: var(--surface-panel);
  gap: 4px;
}
.preset-option[data-active="true"] .pv[data-kind="code"],
.preset-option:hover .pv[data-kind="code"] {
  background: var(--surface-raised);
}
.pv-code-row {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pv-code-row[data-indent="true"] {
  padding-left: 8px;
}
.pv-gutter {
  width: 2px;
  height: 7px;
  border-radius: 1px;
  background: color-mix(in srgb, var(--text-muted) 30%, transparent);
  flex-shrink: 0;
}

/* Diff --------------------------------------------------------------------- */
.pv[data-kind="diff"] {
  gap: 0;
  padding: 5px;
  background: var(--surface-panel);
}
.preset-option[data-active="true"] .pv[data-kind="diff"],
.preset-option:hover .pv[data-kind="diff"] {
  background: var(--surface-raised);
}
.pv-diff-row {
  display: flex;
  align-items: center;
  padding: 1.5px 4px;
}
.pv-diff-row[data-sign="add"] {
  background: color-mix(in srgb, var(--success) 12%, transparent);
}
.pv-diff-row[data-sign="del"] {
  background: color-mix(in srgb, var(--danger) 12%, transparent);
}

/* Data grid ---------------------------------------------------------------- */
.pv[data-kind="data"] {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: 1fr;
  gap: 2px;
  padding: 6px;
}
.pv[data-kind="data"] span {
  border-radius: 2px;
  background: color-mix(in srgb, var(--accent) 16%, var(--surface-inset));
}
.pv[data-kind="data"] span:nth-child(3n + 1) {
  background: color-mix(in srgb, var(--accent) 32%, var(--surface-inset));
}

/* Surface (right panel / overlay) ------------------------------------------ */
.pv[data-kind="surface"] {
  position: relative;
  flex-direction: row;
  gap: 3px;
  padding: 6px;
}
.pv-pane {
  height: 100%;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: var(--surface-inset);
}
.pv-pane[data-side="left"] { flex: 1.4; }
.pv-pane[data-side="right"] { flex: 1; }
.pv-pane[data-side="full"] { flex: 1; }
.pv-pane[data-active="true"] {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, var(--surface-inset));
}
.pv-overlay {
  position: absolute;
  inset: 12px 9px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--accent);
  background: color-mix(in srgb, var(--accent) 16%, var(--surface-panel));
  box-shadow: var(--shadow-sm);
}

/* Git changed files -------------------------------------------------------- */
.pv[data-kind="git-files"] {
  gap: 4px;
}
.pv-file {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pv-file em {
  margin-left: auto;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  line-height: 1;
}
.pv-file em[data-sign="add"] { color: var(--success); }
.pv-file em[data-sign="del"] { color: var(--danger); }

/* Icon-led tiles ----------------------------------------------------------- */
.pv[data-kind="icon"] svg,
.pv[data-kind="visual"] svg {
  color: var(--accent);
}
.pv[data-kind="visual"] {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-inset));
}

/* Theme swatches ----------------------------------------------------------- */
.pv[data-kind="theme"] {
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 4px;
}
.pv-swatch {
  width: 13px;
  height: 18px;
  border: 1px solid;
  border-radius: var(--radius-sm);
}

@media (prefers-reduced-motion: reduce) {
  .pv-caret,
  .pv-dots i,
  .pv-pulse,
  .pv-minimal,
  .pv-shimmer-text > span,
  .pv-bars i,
  .pv-orbit::before {
    animation: none;
  }
}

/* Transparent layout container — the light-gray page (body / --surface-canvas)
   shows through, so the unified product card floats on the gray background. */
/* `.exported-shell` is the exported scaffold's root. It shares this rule rather than
   carrying a copy, because `.preview-frame` (height: 100%, min-height: 0) is designed
   against exactly this sizing context — and `.preview-overlay-surface` positions
   absolutely against it. Selector added only; no declaration changed. */
.builder-surface,
.exported-shell {
  display: grid;
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  /* The builder sets these to the room the floating chrome needs, so the canvas
     spans the window while its contents stay in the clear. The exported shell
     has no chrome and falls through to an even 24px. */
  padding: var(--canvas-pad-top, 24px) var(--canvas-pad-right, 24px)
    var(--canvas-pad-bottom, 24px) var(--canvas-pad-left, 24px);
  /* The left value changes when the rail folds, and the canvas has to move
     with the card rather than snap while the card glides. Plain `--ease-out`,
     not the card's `--ease-back`: the canvas overshooting its own gutter would
     read as a wobble, and nothing is covering the gap it would open. */
  transition: padding var(--motion-rail-out) var(--ease-out);
  border: 0;
  border-radius: 0;
  /* Set from preferences; the literals are the fallback for the exported shell,
     which has no preferences to read. Longhand because the textured backdrops
     set an image and a tile size over the colour. */
  background-color: var(--canvas-bg, #DDE1E9);
  background-image: var(--canvas-bg-image, none);
  background-size: var(--canvas-bg-size, auto);
  box-shadow: none;
}

/* A size container so the 16:10 canvas can be sized against this box in both
   axes — a width calc has no other way to ask how tall the room is. Only the
   builder's surface: the exported shell is a real product filling a window, not
   a canvas with a page on it. */
.builder-surface {
  container-type: size;
}

/*
 * The column divider, and the thing you grab to move it.
 *
 * It used to be a 5px-wide flex item, so the left column ended five pixels
 * before the centre one began and the strip between them was neither column.
 * Hovering the centre module showed it: the highlight started five pixels to
 * the right of the sidebar's edge. Every style then had to decide what to do
 * with a five-pixel channel it never asked for — fill it (a band five times the
 * weight of every other line in that style), or leave it (a dead gutter).
 *
 * So the handle takes *no* width. The columns meet. Both of its jobs move to
 * overlays that cost no layout:
 *
 *   ::before — the grab strip, 8px of transparent hit area straddling the seam.
 *              A pointer needs about that much; the reader sees none of it.
 *   ::after  — the line, at whatever weight the style asked for.
 *
 * Which means the divider is now a style decision rather than a structural
 * leftover: `--divider-w` and `--divider-c`, set per style below. A style that
 * wants no line sets the weight to 0 (Native, Illustrated — their columns are
 * told apart by fill); a style whose column already draws its own edge does the
 * same rather than stacking a second line on it (Pixel Desk, Retro); a style
 * that wants a gap asks for one explicitly (Zine, whose columns are separate
 * sheets on a board).
 */
.resize-handle {
  position: relative;
  z-index: 2;
  width: 0;
  flex: 0 0 auto;
  background: transparent;
}

.resize-handle::before {
  position: absolute;
  inset-block: 0;
  /* Centred on the seam, not on the line: the line can be 0–2.5px and the grab
     strip should not move with it. */
  left: -4px;
  width: 8px;
  cursor: col-resize;
  content: "";
}

/* The two columns' edges. Both side columns are fixed-width flex items, so
   each handle drives its column's custom property directly —
   `--session-width-set` on the left, `--right-width-set` on the right. Same
   class as each other, so they look and behave alike — including being
   exempt from the canvas's click suppression. */
.sidebar-resize-handle {
  flex: 0 0 auto;
  cursor: col-resize;
  touch-action: none;
}

.sidebar-resize-handle[data-dragging="true"]::after {
  background: var(--select-line);
}

.right-resize-handle {
  flex: 0 0 auto;
  cursor: col-resize;
  touch-action: none;
}

.right-resize-handle[data-dragging="true"]::after {
  background: var(--select-line);
}

.resize-handle::after {
  position: absolute;
  inset-block: 0;
  left: 0;
  width: var(--divider-w, 1px);
  background: var(--divider-c, var(--border-subtle));
  transition: background var(--motion-fast) var(--ease-out);
  content: "";
}

.resize-handle:hover::after,
.resize-handle[data-resize-handle-active]::after {
  background: color-mix(in srgb, var(--accent) 55%, var(--border-strong));
}

/* The horizontal twin, kept in step with the rule above. Nothing applies this
   class today — `.resize-handle` is only ever rendered vertically — so it is
   here to stay coherent, not because anything reads it. */
.resize-handle.horizontal {
  width: auto;
  height: 0;
}

.resize-handle.horizontal::before {
  inset-block: auto;
  inset-inline: 0;
  top: -4px;
  width: auto;
  height: 8px;
  cursor: row-resize;
}

.resize-handle.horizontal::after {
  inset-block: auto;
  inset-inline: 0;
  top: 0;
  width: auto;
  height: var(--divider-w, 1px);
}

/* One unified product surface: the sidebar, chat, composer, and right panel sit
   flush inside a single card and are separated by hairlines, not gaps — like a
   real agent client. The card floats on the canvas (builder-surface padding). */
.preview-frame {
  container: preview-frame / inline-size;
  display: flex;
  position: relative;
  gap: 0;
  height: 100%;
  min-height: 0;
  border: 0;
  outline: 0;
  border-radius: 14px;
  background: var(--surface-panel);
  background-clip: padding-box;
  box-shadow: 0 4px 14px rgba(13, 18, 28, 0.045), 0 1px 3px rgba(13, 18, 28, 0.025);
  overflow: hidden;
}

/* Shared icon button for the canvas rails (sidebar/output collapse toggles and
   the output expand button) — borderless ghost with a circular hover highlight,
   identical across styles. */
.rail-icon-btn {
  display: inline-grid;
  place-items: center;
  width: var(--rail-icon-button-size, 28px);
  height: var(--rail-icon-button-size, 28px);
  flex: none;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: background var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out);
}
.rail-icon-btn:hover:not(:disabled) {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.native-rail-icon,
.legacy-rail-icon {
  display: inline-grid;
  place-items: center;
  width: 15px;
  height: 15px;
  line-height: 0;
}

.native-rail-icon {
  display: none;
}

.native-rail-icon svg,
.legacy-rail-icon svg {
  display: block;
}

.preview-frame[data-style-preset="native"] .native-rail-icon {
  display: inline-grid;
}

.preview-frame[data-style-preset="native"] .legacy-rail-icon {
  display: none;
}

/* The new-task icon, switched the same way as the rail icons above.
   The comic style's version is its own artwork — a filled page with a folded
   corner — rather than the shared glyph recoloured, so it cannot be expressed
   as a token override. `iconStyle` could not carry it either: `studio`
   resolves to "line", which it shares with three other styles. */
.comic-new-icon,
.default-new-icon {
  display: inline-grid;
  place-items: center;
  line-height: 0;
}

.comic-new-icon {
  display: none;
}

.comic-new-icon svg,
.default-new-icon svg {
  display: block;
}

.preview-frame[data-style-preset="studio"] .comic-new-icon {
  display: inline-grid;
}

.preview-frame[data-style-preset="studio"] .default-new-icon {
  display: none;
}

.tech-new-icon {
  display: none;
  place-items: center;
  line-height: 0;
}

.preview-frame[data-style-preset="tech"] .tech-new-icon {
  display: inline-grid;
}

.preview-frame[data-style-preset="tech"] .default-new-icon {
  display: none;
}

/* The artifact card's mark, switched the same way. Its comic version is a page
   with a folded corner rather than the shared globe — a globe is right for the
   website preview this card started as and wrong for the file it usually
   shows. */
.comic-artifact-icon,
.pixel-artifact-icon,
.default-artifact-icon {
  display: inline-grid;
  place-items: center;
  line-height: 0;
}

.comic-artifact-icon,
.pixel-artifact-icon {
  display: none;
}

.comic-artifact-icon svg,
.pixel-artifact-icon svg,
.default-artifact-icon svg {
  display: block;
}

/* Both pixel styles take the registry glyph; the hardcoded globe was the one
   curved mark left in a grid of square ones. */
.preview-frame:is([data-style-preset="pixel"], [data-style-preset="pixeldesk"]) .pixel-artifact-icon {
  display: inline-grid;
}

.preview-frame:is([data-style-preset="pixel"], [data-style-preset="pixeldesk"]) .default-artifact-icon {
  display: none;
}

.preview-frame[data-style-preset="studio"] .comic-artifact-icon {
  display: inline-grid;
}

.preview-frame[data-style-preset="studio"] .default-artifact-icon {
  display: none;
}

.preview-frame[data-style-preset="native"] .session-brand-actions .rail-icon-btn,
.preview-frame[data-style-preset="native"] .session-brand-actions .session-search-trigger,
.preview-frame[data-style-preset="native"] .utility-header-actions .rail-icon-btn,
.preview-frame[data-style-preset="native"] .preview-rail-float[data-side="left"],
.preview-frame[data-style-preset="native"] .preview-rail-float[data-side="right"] {
  color: var(--text-primary);
}

.preview-frame[data-style-preset="native"] .rail-icon-btn:hover:not(:disabled) {
  background: var(--preview-hover-fill);
  color: var(--preview-hover-text);
}

/* Right-panel header actions (expand + collapse) sit together, right-aligned. */
.utility-header-actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

/* Brings a column back — shown while a rail is collapsed, and (on the right)
   while the column has been deleted from the canvas.

   16px, which is where the sidebar's own collapse control sits inside its
   header: the two read as one line of controls across the top of the frame.
   Measured — the sidebar's toggle lands 16px below the frame's top edge, and
   this was 14px, so the pair sat 2px out of line. */
.preview-rail-float {
  position: absolute;
  top: 16px;
  z-index: 6;
}
.preview-rail-float[data-side="left"] {
  left: 12px;
}
.preview-rail-float[data-side="right"] {
  right: 12px;
}
/* Keep the reopen float from sitting on top of the chat header content.
   The extra [data-appearance] (always present) lifts specificity above the
   per-preset `.frame-header { padding: … }` rules (native/illustrated) that
   appear later in the file and would otherwise reset this clearance. */
.preview-frame[data-left-collapsed="true"][data-appearance] .chat-frame .frame-header {
  padding-left: 48px;
}
.preview-frame[data-right-collapsed="true"][data-appearance] .chat-frame .frame-header,
.preview-frame[data-right-toggle="true"][data-appearance] .chat-frame .frame-header {
  padding-right: 48px;
}

.preview-panels {
  flex: 1;
  min-width: 0;
}

/* Strip per-module chrome; connect modules with hairline dividers. */
.preview-frame > .session-sidebar {
  gap: 8px;
  border: 0;
  border-right: 1px solid var(--border-subtle);
  border-radius: 0;
  box-shadow: none;
}

.preview-frame .chat-frame {
  border: 0;
  border-radius: 0;
  box-shadow: none;
  /* Transparent, so the centre column is one surface.
     `.chat-frame` shares a rule with `.utility-card` and was taking
     `--surface-panel` while the composer's holder below it shows the frame's
     `--surface-canvas`. Nothing was painting the composer strip — the
     conversation was painting itself *lighter*, and the strip was the canvas
     showing through, which read as a darker band under the conversation.
     Letting the conversation show the canvas too makes the column a single
     colour, which is what removes the band. Cards *on* the column (tool calls,
     output) keep their own fill. */
  background: transparent;
}

.preview-frame .preview-stack,
.preview-frame .right-panel {
  gap: 0;
}

.preview-frame .composer-frame {
  border-top: 0;
  padding: 10px 22px 16px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0), var(--surface-panel) 24%);
}

/*
 * The approval prompt sits directly above the composer, in the stack's flow.
 *
 * Bottom-anchoring it absolutely gave the same rule two different wrong answers: in a
 * conversation the panel was painted over the composer and hid the input field completely,
 * and in the welcome state a separate override turned it static so it landed *below* the
 * input. The prompt asks what should run next, so it belongs above the field — and the field
 * has to stay visible, because "type an answer instead" is one of the listed choices.
 *
 * All three surfaces (external, the inline demo, the inline surface a live run mounts) share
 * this placement; a preset preview that sat somewhere other than the real run would be
 * previewing the wrong thing.
 */
.preview-approval-overlay {
  z-index: 12;
  align-self: end;
  justify-self: center;
  width: 100%;
  padding: 0 18px 6px;
  pointer-events: none;
  display: grid;
  justify-items: center;
}

.preview-approval-overlay .external-approval-panel,
.preview-approval-overlay .inline-approval-panel {
  /* Follows the composer rather than the stack, so the two always share an edge. */
  width: min(var(--composer-measure), 100%);
  max-width: none;
  pointer-events: auto;
  /* A question docked on the composer, not a second page: it never takes
     more than ~40% of the column, and a long one scrolls inside itself. */
  max-height: min(48vh, 360px);
  overflow-y: auto;
  scrollbar-width: thin;
}

/* The request's arguments, kept to a few lines so the choices and the confirm
   key stay on screen; a long payload scrolls inside its own box. */
.preview-approval-overlay .external-approval-command {
  max-height: 84px;
  overflow-y: auto;
  gap: 4px;
  padding: 6px 10px;
  border-radius: 10px;
}

.preview-frame .utility-card {
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.preview-frame .right-panel > .utility-card:not(:last-child) {
  border-bottom: 1px solid var(--border-subtle);
}

.preview-frame .right-panel > .artifact-frame:has(+ .git-panel) {
  border-bottom: 0;
}

/* When the right panel is hidden the chat + composer take the full width. */
.preview-stack-solo {
  flex: 1;
  min-width: 0;
}

.preview-stack,
.right-panel {
  display: grid;
  gap: 12px;
  height: 100%;
  min-height: 0;
  scroll-padding: 12px;
}

/*
 * No scrollbars anywhere inside the preview canvas.
 *
 * `.preview-stack` already hid its own, but the two `<Panel>` wrappers around it are rendered
 * by react-resizable-panels with `overflow: auto` and no class of their own, so theirs stayed.
 * Where the OS draws classic (space-taking) scrollbars, switching the output tab changed the
 * content height, the bar appeared or vanished, and the whole canvas jumped by its width.
 *
 * Hidden rather than `scrollbar-gutter: stable`: a permanently reserved gutter would stop the
 * jump too, but it also puts a dead strip down the edge of a surface whose entire job is to
 * show what the composed product looks like. The rail and the preset panel already made this
 * same call.
 *
 * Scrolling itself is untouched — wheel, trackpad and keyboard all still work.
 */
.preview-panel,
.preview-frame .right-panel,
.preview-frame .session-list {
  scrollbar-width: none;
}

.preview-panel::-webkit-scrollbar,
.preview-frame .right-panel::-webkit-scrollbar,
.preview-frame .session-list::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

.preview-stack {
  position: relative;
  grid-template-rows: minmax(0, 1fr) auto;
  overflow: auto;
  scrollbar-width: none;

  /*
   * The composer's measure, published so the surfaces that belong to the composer can align
   * with it instead of each picking a width.
   *
   * The approval overlays are siblings of `.composer-frame`, not children, so nothing made
   * them agree: the overlay spanned the full stack while the welcome-state composer capped
   * at 660px and centred. Two surfaces that read as one stack sat on different grids.
   */
  --composer-measure: 100%;
}

.preview-stack::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

.preview-frame[data-preview-refreshing="true"] .preview-stack {
  animation: preview-refresh-pulse 360ms var(--ease-out);
}

.right-panel {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  overflow-x: hidden;
  overflow-y: auto;
}

.right-panel > .utility-card {
  flex: 0 0 auto;
}

/* ─── Session history sidebar (scaffolded product chrome) ───────────────── */
/*
 * Left sidebar drawer.
 *
 * Slides on `margin-left`, not `width`. Width would reflow the contents on every frame — the
 * session titles would re-wrap and the row pills re-measure as the panel narrowed. A negative
 * margin keeps the panel at its full width the whole way and lets `.preview-frame`'s existing
 * `overflow: hidden` clip it, so only the position animates.
 *
 * Driven by `data-left-collapsed` on the frame, which both shells already set, and living in
 * app.css — which travels with an export. That is why this is CSS and not a motion component:
 * the editor and the generated app get the same drawer from one source, with no animation code
 * duplicated into the scaffold template.
 *
 * `visibility` is in the transition with `allow-discrete` so the panel stays visible while it
 * slides out and only leaves the tab order and the a11y tree once it is actually gone. Without
 * it a collapsed drawer is still focusable, which reads as a keyboard trap.
 */
.preview-frame .session-sidebar {
  transition:
    margin-left var(--motion-slow) var(--ease-out),
    visibility var(--motion-slow) var(--ease-out);
  transition-behavior: allow-discrete;
}

.preview-frame[data-left-collapsed="true"] .session-sidebar {
  margin-left: calc(-1 * var(--session-width));
  visibility: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .preview-frame .session-sidebar {
    transition: none;
  }
}

/* ---- The side columns' width -------------------------------------------
 *
 * One default for both, so the canvas opens symmetrical: the right column is
 * as wide as the sidebar opposite it, in every style. Declared on the zoom
 * wrapper rather than the frame so the region labels — siblings of the frame —
 * read the same number. The styles that narrow their sidebar narrow this.
 */
/* The exported app has no zoom wrapper — its frame sits in `.exported-shell` —
   so the shell carries the same default, or every export would open both
   columns at 236px whatever the style asked for. */
.exported-shell {
  --side-col-w: 236px;
}

:is(.canvas-zoom, .exported-shell):has(> .preview-frame[data-style-preset="inkwash"]) {
  --side-col-w: 180px;
}

/* `cqi` resolves where it is used, so inside the frame this is the frame's
   width — the same range 复古风's sidebar has always used. */
:is(.canvas-zoom, .exported-shell):has(> .preview-frame[data-style-preset="retro"]) {
  --side-col-w: clamp(150px, 25.777cqi, 229.414px);
}

/* …except that 复古风 makes the two-pane group a container of its own, so
   inside it `cqi` is the group's width, not the frame's, and the right column
   came out 4px narrower than the sidebar (225 against 229, measured). A
   registered length is computed to pixels where it is declared — on the
   group, whose own `cqi` still answers to the frame — and inherits as that
   number. */
@property --side-col-px {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

.preview-frame[data-style-preset="retro"] > .preview-panels {
  --side-col-px: clamp(150px, 25.777cqi, 229.414px);
}

.preview-frame[data-style-preset="retro"] .preview-panel-slot[data-slot="right"] {
  --side-col-override: var(--side-col-px);
}

/* ---- The centre and the right column -----------------------------------
 *
 * Two fixed-shape panes in a row: the centre takes what is left, the right
 * column is `--side-col-w` wide (or what its handle was dragged to). Each pane
 * is a slot wrapping a `.preview-panel` — the inner box every style's rules
 * already address, kept so none of them had to change when the resizable
 * split this replaced went away.
 */
.preview-frame .preview-panels {
  display: flex;
  flex-flow: row;
  width: 100%;
  height: 100%;
  /* `clip`, not `hidden`: a `hidden` box can still be scrolled by script, and
     the right column mounting folded off its edge was scrolled into view by
     its own tabs — the group slid 55px sideways mid-slide (measured). */
  overflow: clip;
}

.preview-panel-slot {
  display: flex;
  min-width: 0;
  min-height: 0;
  max-height: 100%;
}

.preview-panel-slot > .preview-panel {
  flex-grow: 1;
  min-width: 0;
  max-width: 100%;
  max-height: 100%;
  overflow: auto;
}

.preview-panel-slot[data-slot="main"] {
  flex: 1 1 0;
}

/* ---- Folding the right column -----------------------------------------
 *
 * The left column's fold, mirrored — same property, same duration, same
 * curve, so the two read as one gesture. The column keeps its width and
 * slides out past the right edge on a negative margin; the centre is
 * `flex: 1`, so it widens into the room as the margin opens it, frame by
 * frame, with nothing reflowing to nothing. `visibility` rides along with
 * `allow-discrete`, as on the left: on screen for the whole slide, out of the
 * tab order once it is gone.
 *
 * `data-right-folding` is up for `COLUMN_EXIT_MS` in both directions — see
 * `toggleRightColumn`, which mounts the column folded and then lowers the flag
 * so the same transition runs forwards.
 */
.preview-panel-slot[data-slot="right"] {
  --right-col-w: var(--right-width-set, var(--side-col-override, var(--side-col-w, 236px)));
  flex: none;
  width: var(--right-col-w);
  transition:
    margin-right var(--motion-slow) var(--ease-out),
    visibility var(--motion-slow) var(--ease-out);
  transition-behavior: allow-discrete;
}

/* The column is a size container, so its header can answer to its own width:
   at 水墨风's 180px the 产物 / 控制台 labels, the expand key and the fold key
   do not fit one row and the label ran under the icons. Narrow, the switch
   goes to its glyphs — each button keeps its name in `aria-label` and
   `title` — and the words come back as soon as the column is dragged wider. */
.preview-panel-slot[data-slot="right"] {
  container: right-column / inline-size;
}

@container right-column (max-width: 219px) {
  .preview-frame .output-source-label {
    display: none;
  }

  .preview-frame .output-source-switch button {
    padding: 0 8px;
  }
}

.preview-frame[data-right-folding="true"] .preview-panel-slot[data-slot="right"] {
  margin-right: calc(-1 * var(--right-col-w));
  visibility: hidden;
}

/* Opening is the same slide run forwards, from the column's first frame:
   `@starting-style` is the folded position it transitions *from* when it is
   mounted. So every way of opening it — its toggle, clicking an artifact, a
   rail pick that lives in it — on the canvas and in the exported app alike,
   slides it in the same way, with no timer to keep in step. */
@starting-style {
  .preview-panel-slot[data-slot="right"] {
    margin-right: calc(-1 * var(--right-col-w));
    visibility: hidden;
  }
}

/* The grab handle goes with it: a separator between a pane and a pane that is
   on its way out has nothing to separate. */
.preview-frame .preview-panels > .resize-handle {
  transition: opacity var(--motion-fast) var(--ease-out);
}

.preview-frame[data-right-folding="true"] .preview-panels > .resize-handle {
  opacity: 0;
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  .preview-panel-slot[data-slot="right"] {
    transition: none;
  }
}


.session-sidebar {
  /* Overridable so the editor's drag handle can set it, with 236px as the
     default the exported scaffold ships with. */
  --session-width: var(--session-width-set, var(--side-col-w, 236px));
  --session-edge-x: 22px;
  /* How far the highlight pill bleeds past the row text on each side. Text/labels
     stay aligned with the New Chat icon at --session-edge-x (22px); the pill sits
     --session-edge-x − --session-row-bleed = 10px from the panel's left edge. */
  --session-row-bleed: 12px;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  width: var(--session-width);
  flex: none;
  height: 100%;
  min-height: 0;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  background: var(--surface-panel);
  padding: 0 var(--session-edge-x) var(--space-3);
  box-shadow: var(--shadow-sm);
}

/* No header row — none of the title, search or collapse control was picked —
   so nothing is holding the top of the column and the first thing in it sat
   against the frame's edge. 40px reads as the same breathing room the header
   used to give. */
.session-sidebar[data-header="none"] {
  padding-top: 40px;
}

.session-new {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  height: var(--control-md);
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-primary);
  padding: 0;
  font-size: var(--text-md);
  font-weight: var(--weight-title);
  transition: background var(--motion-fast) var(--ease-out),
    border-color var(--motion-fast) var(--ease-out);
}

.session-new:hover {
  background: transparent;
}

.session-actions {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.preview-frame .session-actions:empty {
  display: none;
}

.session-actions .session-new {
  flex: 1;
  justify-content: flex-start;
  border-color: transparent;
  background: transparent;
  /* Same box as a conversation row's pill, so any style that fills this button
     fills the same rectangle as the selected row below it.
     The pill is `.session-item-bg` at `inset: 2px calc(-1 * bleed)` inside a
     list that is itself pulled out by `margin-inline: -bleed` — so it spans the
     sidebar's content width plus `bleed` on each side. This button was only as
     wide as the content box, which left its fill 2 × bleed narrower than the
     row it sits above.
     The negative margin grows the box outward into the sidebar's padding (where
     the pill already overhangs) and the padding puts the icon and label back
     where they were. */
  margin-inline: calc(-1 * var(--session-row-bleed));
  padding-inline: var(--session-row-bleed);
}

.session-new svg {
  display: block;
  flex: none;
}

.session-search-menu {
  position: static;
  flex: none;
}

.session-search-trigger {
  display: inline-grid;
  place-items: center;
  width: var(--rail-icon-button-size, 28px);
  height: var(--rail-icon-button-size, 28px);
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  padding: 0;
  transition: background var(--motion-fast) var(--ease-out),
    color var(--motion-fast) var(--ease-out),
    border-color var(--motion-fast) var(--ease-out);
}

.session-search-trigger:hover,
.session-search-trigger[aria-expanded="true"] {
  border-color: transparent;
  background: transparent;
  color: var(--text-primary);
}

.session-search-overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: color-mix(in srgb, #111827 10%, transparent);
  padding: 18px;
}

.session-search-popover {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 10px;
  width: min(520px, calc(100% - 24px));
  max-height: min(72%, 460px);
  overflow: hidden;
  border: 1px solid var(--border-subtle);
  border-radius: 18px;
  background: var(--surface-panel);
  padding: 13px 10px 12px;
  box-shadow: 0 18px 46px rgba(13, 18, 28, 0.14);
  transform: none;
}

.session-search {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-height: 36px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--text-muted);
  padding: 0 10px 8px;
}

.session-search input {
  min-width: 0;
  flex: 1;
  height: 100%;
  border: 0;
  background: transparent;
  color: var(--text-primary);
  font-size: 15px;
  line-height: 1.3;
  outline: none;
}

.session-search-results {
  display: grid;
  gap: 8px;
  min-height: 0;
  overflow: auto;
  padding: 0 6px 3px;
}

.session-search-popover :is(.session-group) {
  gap: 2px;
}

.session-search-popover :is(.session-group) h4 {
  padding: 0 10px 3px;
  font-size: 12px;
  font-weight: 650;
}

.session-search-popover :is(.session-item-shell) {
  min-height: 36px;
}

.session-search-popover :is(.session-item-bg) {
  inset: 2px 0;
  border-radius: 9px;
}

.session-search-popover :is(.session-item) {
  min-height: 36px;
  border-radius: 9px;
  padding: 0 10px;
  font-size: 14px;
}

.session-list {
  display: grid;
  align-content: start;
  justify-items: stretch;
  gap: var(--space-4);
  flex: 1;
  min-height: 0;
  /* Bleed the scroll container into the sidebar padding by --session-row-bleed
     and pad it back by the same amount: rows stay aligned at --session-edge-x
     while the pill can overhang into the padding without overflow:auto clipping it. */
  margin-inline: calc(-1 * var(--session-row-bleed));
  padding-inline: var(--session-row-bleed);
  overflow: auto;
}

/* Session sidebar brand/title — bold agent name at the top (Codex-like). The
   left padding clears the frame's top-left collapse toggle. */
.session-brand {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: var(--preview-header-height, 60px);
  padding: 10px 0;
}
.session-brand-name {
  font-size: var(--preview-title-size, 16px);
  font-weight: 760;
  line-height: 1.25;
  color: var(--text-primary);
}

.session-brand-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: none;
  /* Holds the right edge when the title is not one of the chosen modules:
     `space-between` has nothing to push against with a single child, so the
     collapse control slid to the left of the column. */
  margin-left: auto;
}

.session-group {
  display: grid;
  justify-items: stretch;
  gap: 3px;
  width: 100%;
  min-width: 0;
}

.session-group h4 {
  padding: 0 0 2px;
  color: var(--text-muted);
  font-size: var(--text-xs);
  font-weight: var(--weight-eyebrow);
  text-transform: none;
  letter-spacing: 0.02em;
}

.session-item-shell {
  position: relative;
  width: 100%;
  min-width: 0;
  justify-self: stretch;
  min-height: var(--control-md);
}

.session-item-bg {
  position: absolute;
  inset: 2px calc(-1 * var(--session-row-bleed));
  border-radius: 12px;
  background: transparent;
  pointer-events: none;
  transition: background var(--motion-fast) var(--ease-out);
}

.session-item {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  width: 100%;
  min-width: 0;
  min-height: var(--control-md);
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-secondary);
  padding: 0;
  text-align: left;
  transition: color var(--motion-fast) var(--ease-out);
}

/* A marked row is icon-then-label on one line.
 *
 * This lived in the Game and 复古像素风 branches and nowhere else, so in the
 * other nine styles the mark landed on an implicit second grid row and sat
 * *above* the title — one conversation taking two lines, with the glyph
 * apparently belonging to nothing. Two columns is what "a row with a mark on
 * it" means in every style, so it belongs in the base and the branches keep
 * only their colours and sizes.
 *
 * `auto minmax(0, 1fr)`: the glyph takes what it needs, the label takes the
 * rest and is allowed to shrink below its content — without the `minmax` the
 * label's own width wins and pushes the row wider than the column. */
.session-item:has(.session-item-icon) {
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--space-2);
}

.session-item-icon {
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 16px;
  height: 16px;
}

.session-item-label {
  position: relative;
  min-width: 0;
  overflow: hidden;
  font-size: var(--text-sm);
  font-weight: var(--weight-body);
  line-height: 1.35;
  overflow-wrap: normal;
  /* Ellipsis, not `clip`: a title cut mid-glyph reads as a rendering fault,
     where "…" reads as "there is more of this name". */
  text-overflow: ellipsis;
  white-space: nowrap;
}

.session-item:hover {
  background: transparent;
  color: var(--text-primary);
}

.session-item-shell:hover .session-item-bg {
  background: var(--accent-soft);
}

.session-item[data-active="true"] {
  background: transparent;
  color: var(--accent-hover);
}

.session-item-shell[data-active="true"] .session-item-bg {
  background: var(--accent-soft);
}

.session-footer {
  /*
   * Pinned to the bottom of the column rather than trailing the session list.
   *
   * The sidebar is a flex column and this is its last child, so with no sessions to fill the
   * space it rode up under "New chat" — which is exactly what an export shows, because a
   * shipped scaffold has no session store and passes an empty list. `margin-top: auto` puts
   * it on the floor whether the list has five rows or none.
   */
  margin: auto 0 0;
  color: var(--text-muted);
  padding: 0;
  font-size: var(--text-xs);
  line-height: 1.4;
}

.session-footer:hover {
  background: transparent;
  color: var(--text-muted);
}

.preview-overlay-surface {
  position: absolute;
  right: 18px;
  bottom: 18px;
  z-index: 8;
  width: min(420px, calc(100% - 36px));
  max-height: calc(100% - 36px);
  overflow: auto;
  border-radius: calc(var(--radius) + 2px);
  box-shadow: var(--shadow);
}

.preview-overlay-surface .artifact-frame {
  min-height: 260px;
}

.provider-floating-settings {
  position: relative;
  z-index: 12;
  display: inline-flex;
  flex-shrink: 0;
}

.provider-floating-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  min-height: 30px;
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  background: var(--surface-panel);
  color: var(--text-secondary);
  padding: 0;
}

.provider-floating-trigger:hover,
.provider-floating-trigger[aria-expanded="true"] {
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border-strong));
}

.provider-floating-popover {
  position: absolute;
  left: 0;
  bottom: 38px;
  display: grid;
  gap: 10px;
  width: min(440px, calc(100vw - 56px));
  max-height: min(620px, calc(100vh - 190px));
  overflow: auto;
  border: 1px solid var(--border-strong);
  border-radius: calc(var(--radius) + 2px);
  background: var(--surface-panel);
  box-shadow: var(--shadow);
  padding: 12px;
}

.provider-floating-popover header,
.provider-floating-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.provider-floating-popover header div,
.provider-floating-card-header div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.provider-floating-popover header strong,
.provider-floating-card-header strong {
  color: var(--text-primary);
  font-size: 13px;
}

.provider-floating-popover header span,
.provider-floating-card-header span {
  color: var(--text-muted);
  font-size: 11px;
}

.provider-floating-popover header button,
.provider-floating-card-header button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: var(--surface-raised);
  color: var(--text-muted);
  padding: 0 8px;
  font-size: 11px;
  font-weight: 620;
}

.provider-floating-card-header button[data-active="true"] {
  border-color: color-mix(in srgb, var(--accent) 32%, var(--border-subtle));
  background: var(--accent-soft);
  color: var(--accent);
}

.provider-floating-list {
  display: grid;
  gap: 8px;
}

.provider-floating-card {
  display: grid;
  gap: 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  background: var(--surface-raised);
  padding: 10px;
}

.provider-floating-card label {
  display: grid;
  gap: 4px;
}

.provider-floating-card label span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  text-transform: none;
}

.provider-floating-card input,
.provider-floating-card select {
  width: 100%;
  height: 30px;
  max-width: none;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  background: var(--surface-panel);
  color: var(--text-secondary);
  padding: 0 8px;
  font-size: 12px;
}

.provider-floating-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.provider-floating-actions button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  background: var(--surface-panel);
  color: var(--text-secondary);
  padding: 0 8px;
  font-size: 12px;
  font-weight: 600;
}

.debug-surface {
  height: 100%;
  min-height: 0;
}

.chat-frame,
.composer-frame,
.utility-card,
.debug-dock {
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  background: var(--surface-panel);
  box-shadow: var(--shadow-sm);
}

.chat-frame {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-height: 0;
  overflow: hidden;
}

.frame-header,
.utility-header,
.debug-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-subtle);
}

.frame-header h2,
.utility-header h3,
.debug-header h3 {
  font-family: var(--font-display);
  font-size: 14px;
  line-height: 1.2;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border-radius: 999px;
  padding: 4px 10px;
  background: var(--surface-inset);
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 620;
}

.status-pill[data-status="running"] {
  background: color-mix(in srgb, var(--info) 12%, var(--surface-panel));
  color: var(--info);
}

.status-pill[data-status="finished"] {
  background: color-mix(in srgb, var(--success) 13%, var(--surface-panel));
  color: var(--success);
}

.tool-card[data-status="running"] {
  color: var(--info);
}

.tool-card[data-status="success"] {
  color: var(--success);
}

.timeline-list {
  display: grid;
  align-content: start;
  gap: 14px;
  min-height: 0;
  overflow: auto;
  padding: 18px 16px;
  scroll-padding: 18px;
}

[data-preview-anchor] {
  scroll-margin: 12px;
}

.reasoning-block,
.tool-card,
.artifact-inline,
.step-item,
.error-item,
.empty-state,
.approval-box {
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  background: var(--surface-panel);
}

/* Conversation rows: avatar + stacked bubble content */
.message-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
  border-radius: 0;
}

.message-bubble {
  width: auto;
}

.message-item[data-role="user"] {
  flex-direction: row-reverse;
}

.msg-avatar {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: var(--space-7);
  height: var(--space-7);
  border-radius: var(--radius-full);
  border: 1px solid var(--border-strong);
  background: var(--surface-inset);
  color: var(--text-muted);
  box-shadow: var(--shadow-sm);
}

.msg-avatar[data-role="assistant"] {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border-strong));
  background: var(--accent-soft);
  color: var(--accent);
}

/* Original "orb" agent avatar: when chosen, it fills the avatar (no clashing
   circle behind it) and blinks + gently floats. */
.msg-avatar:has(.orb-face),
.msg-avatar:has(.robot-face),
.msg-avatar:has(.active-robot-face),
.msg-avatar:has(.robot-head-face),
.msg-avatar:has(.custom-avatar-face) {
  background: transparent !important;
  border: 0;
  box-shadow: none;
  padding: 0;
}

.msg-avatar .orb-face,
.msg-avatar .robot-face,
.msg-avatar .active-robot-face,
.msg-avatar .robot-head-face,
.msg-avatar .custom-avatar-face {
  width: 100%;
  height: 100%;
}

/* The positioning context for the oversized canvas inside. The head occupies
   under half the frame the package draws (see `PLACEMENT` in
   `robotHeadAvatars`), so the canvas is absolutely positioned at ~2x the span
   and pulled up until the head's centre lands on the span's — the air around
   it overhangs, which is why this must not clip. */
.robot-head-face {
  position: relative;
  display: inline-block;
  overflow: visible;
  /* The `size` the call site passed, which any of the slot rules below is free
     to override — see the note in `robotHeadAvatars` on why this is a property
     and not an inline width. */
  width: var(--robot-head-box, 24px);
  height: var(--robot-head-box, 24px);
}

/* Bigger than the 32px (`--space-7`) every other style's avatar gets. The LED
   matrix is bloomed from a pixel-per-LED image, so it has a floor the painted
   and vector faces do not: at 32px the head reads but its expression does not,
   and the expression is the whole reason to put a screen on a robot. Scoped to
   this style's own avatars, so no other slot moves. */
.preview-frame[data-style-preset="tech"] .msg-avatar:has(.robot-head-face) {
  width: 40px;
  height: 40px;
}

/* The welcome greeting, same bump for the same reason. It runs 28px rather than
   the conversation's 32px (`.preview-frame .composer-greeting-avatar`), so this
   keeps that 7:8 and lands on 36 — a greeting head larger than the ones in the
   thread would read as a different robot. */
.preview-frame[data-style-preset="tech"] .composer-greeting-avatar:has(.robot-head-face) {
  width: 36px;
  height: 36px;
}

.preview-frame .msg-avatar .agent-spark-avatar {
  width: 24px;
  height: 29px;
}

.preview-frame[data-style-preset="native"] .msg-avatar .agent-spark-avatar {
  width: 26px;
  height: 31px;
}

.robot-face-body {
  transform-box: fill-box;
  transform-origin: center;
  animation: orb-face-float 3.4s var(--ease-in-out) infinite;
}

.robot-face-body-position {
  transform-box: view-box;
  transform-origin: 12px 12px;
  transform: translateY(var(--robot-face-body-offset-y, 0));
}

.robot-face-eyes {
  transform-box: fill-box;
  transform-origin: center;
  animation: orb-face-blink 4s var(--ease-in-out) infinite;
}

.agent-first-avatar-eyes {
  transform-box: fill-box;
  transform-origin: center;
  animation: agent-first-avatar-look 3.6s var(--ease-in-out) infinite;
}

.agent-work-bot-avatar-eyes {
  transform-box: fill-box;
  transform-origin: center;
  animation: agent-work-bot-avatar-look 2.8s var(--ease-in-out) infinite;
}

.agent-work-bot-avatar-glyph {
  transform-box: view-box;
  transform-origin: 37px 37px;
  transform: scale(var(--agent-work-bot-glyph-scale, 1));
}

.agent-work-bot-avatar {
  --agent-work-bot-body: #28477D;
  --agent-work-bot-face: #FFFFFF;
  --agent-work-bot-eye: var(--agent-work-bot-body);
  --agent-work-bot-screen-start: #2791FF;
  --agent-work-bot-screen-end: #B000BD;
  overflow: visible;
}

:is(.preview-frame, .preset-panel)[data-style-preset="native"] .agent-work-bot-avatar {
  --agent-work-bot-body: #28477D;
  --agent-work-bot-face: #FFFFFF;
  --agent-work-bot-eye: #28477D;
  --agent-work-bot-screen-start: #2791FF;
  --agent-work-bot-screen-end: #B000BD;
}

.preview-frame[data-style-preset="native"][data-appearance="dark"] .agent-work-bot-avatar {
  --agent-work-bot-body: #F3C66E;
  --agent-work-bot-face: color-mix(in srgb, var(--surface-panel) 82%, #000);
  --agent-work-bot-eye: #F3C66E;
  --agent-work-bot-screen-start: #FF8B73;
  --agent-work-bot-screen-end: #FFD56A;
}

:is(.preview-frame, .preset-panel):not([data-style-preset="native"]) .agent-work-bot-avatar {
  --agent-work-bot-body: var(--accent);
  --agent-work-bot-face: var(--surface-panel);
  --agent-work-bot-eye: var(--accent);
  --agent-work-bot-screen-start: color-mix(in srgb, var(--accent) 58%, var(--surface-panel));
  --agent-work-bot-screen-end: color-mix(in srgb, var(--accent-hover) 76%, var(--surface-panel));
}

.preview-frame:not([data-style-preset="native"])[data-appearance="dark"] .agent-work-bot-avatar {
  --agent-work-bot-body: color-mix(in srgb, var(--accent) 42%, var(--text-primary));
  --agent-work-bot-face: color-mix(in srgb, var(--surface-panel) 86%, #000);
  --agent-work-bot-eye: var(--agent-work-bot-body);
  --agent-work-bot-screen-start: color-mix(in srgb, var(--accent) 68%, var(--surface-panel));
  --agent-work-bot-screen-end: color-mix(in srgb, var(--accent-hover) 72%, var(--text-primary));
}

.agent-orange-blob-avatar {
  --agent-orange-blob-bg: #10264A;
  --agent-orange-blob-body: #FA8352;
  --agent-orange-blob-eye: #FFF7D8;
  transform-box: fill-box;
  transform-origin: center;
  animation: agent-orange-blob-avatar-wobble 3.8s var(--ease-in-out) infinite;
}

.agent-orange-blob-avatar-glyph {
  transform-box: view-box;
  transform-origin: 16px 16px;
  transform: translateY(var(--agent-orange-blob-glyph-y, 0)) scale(var(--agent-orange-blob-glyph-scale, 1));
}

.agent-orange-blob-avatar-eyes {
  transform-box: fill-box;
  transform-origin: center;
  animation: agent-orange-blob-avatar-eye-squint 3.8s var(--ease-in-out) infinite;
}

.preview-frame[data-style-preset="native"] .agent-orange-blob-avatar {
  --agent-orange-blob-glyph-scale: 1;
  --agent-orange-blob-glyph-y: 0;
}

.agent-spark-avatar {
  --agent-spark-main-start: #111E36;
  --agent-spark-main-end: #615DE0;
  --agent-spark-small-start: #111E36;
  --agent-spark-small-end: #615DE0;
  --agent-spark-glow-start: #615DE0;
  --agent-spark-glow-end: #111E36;
  --agent-spark-glow-opacity: 0.46;
  overflow: visible;
}

:is(.preview-frame, .preset-panel)[data-style-preset="native"] .agent-spark-avatar {
  --agent-spark-main-start: #111E36;
  --agent-spark-main-end: #615DE0;
  --agent-spark-small-start: #111E36;
  --agent-spark-small-end: #615DE0;
  --agent-spark-glow-start: #615DE0;
  --agent-spark-glow-end: #111E36;
  --agent-spark-glow-opacity: 0.46;
}

:is(.preview-frame, .preset-panel)[data-style-preset="native"][data-theme-preset="sand-workspace"] .agent-spark-avatar {
  --agent-spark-main-start: #6F472F;
  --agent-spark-main-end: #C98656;
  --agent-spark-small-start: #805235;
  --agent-spark-small-end: #D69A66;
  --agent-spark-glow-start: #C98656;
  --agent-spark-glow-end: #A7673F;
  --agent-spark-glow-opacity: 0.34;
}

:is(.preview-frame, .preset-panel)[data-style-preset="native"][data-theme-preset="apricot-agent"] .agent-spark-avatar {
  --agent-spark-main-start: #7D3F39;
  --agent-spark-main-end: #D66A50;
  --agent-spark-small-start: #92504A;
  --agent-spark-small-end: #EE8C72;
  --agent-spark-glow-start: #D66A50;
  --agent-spark-glow-end: #F0A07E;
  --agent-spark-glow-opacity: 0.36;
}

.preview-frame[data-style-preset="native"][data-appearance="dark"] .agent-spark-avatar {
  --agent-spark-main-start: #F7C56E;
  --agent-spark-main-end: #FF7B9A;
  --agent-spark-small-start: #FFE08A;
  --agent-spark-small-end: #FF9DB0;
  --agent-spark-glow-start: #FFB15E;
  --agent-spark-glow-end: #FF6F9A;
  --agent-spark-glow-opacity: 0.5;
}

:is(.preview-frame, .preset-panel)[data-style-preset="illustrated"] .agent-spark-avatar {
  --agent-spark-main-start: var(--accent);
  --agent-spark-main-end: color-mix(in srgb, var(--accent) 58%, var(--surface-panel));
  --agent-spark-small-start: color-mix(in srgb, var(--accent) 84%, var(--text-primary));
  --agent-spark-small-end: color-mix(in srgb, var(--accent-hover) 64%, var(--surface-panel));
  --agent-spark-glow-start: color-mix(in srgb, var(--accent) 72%, var(--surface-panel));
  --agent-spark-glow-end: var(--accent-hover);
  --agent-spark-glow-opacity: 0.5;
}

.preview-frame[data-style-preset="illustrated"][data-appearance="dark"] .agent-spark-avatar {
  --agent-spark-main-start: color-mix(in srgb, var(--accent) 48%, var(--text-primary));
  --agent-spark-main-end: color-mix(in srgb, var(--accent-hover) 58%, var(--text-primary));
  --agent-spark-small-start: color-mix(in srgb, var(--accent) 72%, var(--text-primary));
  --agent-spark-small-end: color-mix(in srgb, var(--accent-hover) 68%, var(--surface-panel));
  --agent-spark-glow-start: color-mix(in srgb, var(--accent) 72%, var(--surface-panel));
  --agent-spark-glow-end: color-mix(in srgb, var(--accent-hover) 64%, var(--text-primary));
  --agent-spark-glow-opacity: 0.58;
}

.agent-spark-avatar-glow {
  transform-box: fill-box;
  transform-origin: center;
  animation: agent-spark-avatar-glow-spread 3s var(--ease-out) infinite;
}

.agent-spark-avatar-main,
.agent-spark-avatar-small {
  transform-box: fill-box;
  transform-origin: center;
}

.agent-spark-avatar-main {
  animation: agent-spark-avatar-main-breathe 3s var(--ease-in-out) infinite;
}

.agent-spark-avatar-small {
  animation: agent-spark-avatar-small-spin 3s var(--ease-out) infinite;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] :is(
  .user-blue-smile-features,
  .user-heart-eye,
  .user-heart-mouth,
  .user-golden-joy-eye,
  .user-golden-joy-mouth,
  .user-green-calm-eye,
  .user-green-calm-mouth,
  .user-purple-bored-pupil
) {
  transform-box: fill-box;
  transform-origin: center;
  will-change: transform;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] .user-blue-smile-features {
  animation: user-blue-smile-look-around 3.4s var(--ease-in-out) infinite;
}

:is(.preview-frame, .preset-panel)[data-style-preset="native"] .user-blue-smile-avatar {
  --user-blue-smile-bg: #C0D3F8;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] .user-heart-eye {
  animation: user-heart-eye-grow 3.1s var(--ease-in-out) infinite;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] .user-heart-mouth {
  animation: user-heart-mouth-smile 3.1s var(--ease-in-out) infinite;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] .user-golden-joy-eye {
  animation: user-golden-joy-nod 3.2s var(--ease-in-out) infinite;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] .user-golden-joy-mouth {
  animation: user-golden-joy-nod 3.2s var(--ease-in-out) infinite;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] .user-green-calm-eye {
  animation: user-green-calm-blink 4.2s var(--ease-in-out) infinite;
}

.preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] .user-purple-bored-pupil {
