}

@media (prefers-reduced-motion: reduce) {
  .composer-voice-wave span,
  .robot-face-body,
  .robot-face-eyes,
  .agent-first-avatar-eyes,
  .agent-work-bot-avatar-eyes,
  .agent-orange-blob-avatar,
  .agent-orange-blob-avatar-eyes,
  .agent-spark-avatar-glow,
  .agent-spark-avatar-main,
  .agent-spark-avatar-small,
  .preview-frame[data-style-preset="native"] .msg-avatar[data-role="user"] :is(
    .user-blue-smile-features,
    .user-heart-eye,
    .user-heart-mouth,
    .user-golden-joy-eye,
    .user-golden-joy-mouth,
    .user-green-calm-eye,
    .user-purple-bored-pupil
  ) {
    animation: none;
  }
}

.orb-face-body {
  transform-box: fill-box;
  transform-origin: center;
  animation: orb-face-float 3.2s var(--ease-in-out) infinite;
}

.orb-face-eyes {
  transform-box: fill-box;
  transform-origin: center;
  animation: orb-face-blink 4.4s var(--ease-in-out) infinite;
}

@keyframes orb-face-float {
  0%, 100% { transform: translateY(0.5px); }
  50% { transform: translateY(-0.6px); }
}

@keyframes orb-face-blink {
  0%, 90%, 100% { transform: scaleY(1); }
  95% { transform: scaleY(0.12); }
}

@keyframes agent-first-avatar-look {
  0%, 18%, 100% { transform: translateX(0); }
  35%, 50% { transform: translateX(2px); }
  68%, 82% { transform: translateX(-2px); }
}

@keyframes agent-work-bot-avatar-look {
  0%, 12%, 100% { transform: translate(0, 0); }
  26%, 38% { transform: translate(1.4px, -0.8px); }
  52%, 62% { transform: translate(-1.2px, 0.8px); }
  76%, 86% { transform: translate(0.7px, 0.5px); }
}

@keyframes agent-orange-blob-avatar-wobble {
  0%, 21%, 100% { transform: rotate(0deg) translate(0, 0); }
  6% { transform: rotate(-2.6deg) translate(-0.35px, 0.15px); }
  12% { transform: rotate(2deg) translate(0.35px, -0.2px); }
  18% { transform: rotate(-1.1deg) translate(-0.15px, 0); }
}

@keyframes agent-orange-blob-avatar-eye-squint {
  0%, 8%, 21%, 100% {
    transform: scaleY(1);
  }
  12%, 15% {
    transform: scaleY(0.12);
  }
}

@keyframes agent-spark-avatar-glow-spread {
  0% {
    opacity: 0.92;
    transform: scale(0.76);
  }
  48% {
    opacity: 0.64;
    transform: scale(1.1);
  }
  78%, 100% {
    opacity: 0.24;
    transform: scale(1.34);
  }
}

@keyframes agent-spark-avatar-main-breathe {
  0%, 100% {
    transform: scale(1);
  }
  48% {
    transform: scale(1.07);
  }
}

@keyframes agent-spark-avatar-small-spin {
  0%, 6% {
    transform: rotate(0deg);
  }
  22%, 100% {
    transform: rotate(360deg);
  }
}

@keyframes user-blue-smile-look-around {
  0%, 100% { transform: translateX(0) rotate(0deg); }
  22% { transform: translateX(-3.2px) rotate(-5deg); }
  46% { transform: translateX(3.4px) rotate(5.5deg); }
  68% { transform: translateX(-1.6px) rotate(-2.4deg); }
}

@keyframes user-heart-eye-grow {
  0%, 24%, 100% { transform: scale(1); }
  38% { transform: scale(1.16); }
  52% { transform: scale(1.06); }
}

@keyframes user-heart-mouth-smile {
  0%, 24%, 100% { transform: translateY(0) scaleX(1); }
  38% { transform: translateY(1.2px) scaleX(1.08); }
}

@keyframes user-golden-joy-nod {
  0%, 14%, 100% { transform: translateY(0); }
  30%, 42% { transform: translateY(2.2px); }
  58% { transform: translateY(-1.1px); }
  72% { transform: translateY(0.6px); }
}

@keyframes user-green-calm-blink {
  0%, 88%, 100% { transform: scaleY(1); }
  92%, 94% { transform: scaleY(0.12); }
  96% { transform: scaleY(1); }
  97%, 98% { transform: scaleY(0.18); }
}

@keyframes user-purple-bored-pupil-orbit {
  0%, 100% { transform: translate(0, 0); }
  14% { transform: translate(2px, 0); }
  28% { transform: translate(1.4px, 2px); }
  42% { transform: translate(-1.4px, 2px); }
  56% { transform: translate(-2px, 0); }
