  inset: 0;
  transform-origin: 14px 14px;
  animation: reasoning-orb-morph-twist 9.6s linear infinite;
}

:is(.preview-frame, .preset-panel)[data-style-preset="native"] .reasoning-orb-morph-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  margin: -1.5px 0 0 -1.5px;
  border-radius: 50%;
  background: currentColor;
  animation: reasoning-orb-morph 4.8s cubic-bezier(0.4, 0, 0.2, 1) infinite both;
}

@media (prefers-reduced-motion: reduce) {
  :is(.preview-frame, .preset-panel)[data-style-preset="native"] .reasoning-native-orb-glyph * {
    animation: none !important;
  }
}

@keyframes reasoning-orb-wave {
  0% {
    opacity: var(--orb-rest);
    transform: scale(1);
    animation-timing-function: cubic-bezier(0.66, 0, 0.34, 1);
  }
  28% {
    opacity: 1;
    transform: scale(1.18);
    animation-timing-function: cubic-bezier(0.66, 0, 0.34, 1);
  }
  56%,
  100% {
    opacity: var(--orb-rest);
    transform: scale(1);
  }
}

@keyframes reasoning-orb-handoff {
  0% {
    opacity: 0;
    filter: blur(2.4px);
    transform: translateX(-11px) scale(0.55);
    animation-timing-function: cubic-bezier(0.33, 1, 0.68, 1);
  }
  22% {
    opacity: 1;
    filter: blur(0);
    transform: translateX(-1px) scale(1);
    animation-timing-function: linear;
  }
  37% {
    opacity: 1;
    filter: blur(0);
    transform: translateX(0) scale(1);
    animation-timing-function: linear;
  }
  52% {
    opacity: 1;
    filter: blur(0);
    transform: translateX(1px) scale(1);
    animation-timing-function: cubic-bezier(0.33, 1, 0.68, 1);
  }
  70%,
  100% {
    opacity: 0;
    filter: blur(2.4px);
    transform: translateX(11px) scale(0.55);
  }
}

@keyframes reasoning-orb-breathe {
  0%,
  100% {
    opacity: 0.16;
    filter: blur(2.4px);
    transform: scale(1.2);
  }
  50% {
    opacity: 0.32;
    filter: blur(1.6px);
    transform: scale(0.98);
  }
}

@keyframes reasoning-orb-morph {
  0%, 5% { transform: translate(var(--m-1)); }
  25%, 30% { transform: translate(var(--m-2)); }
  50%, 55% { transform: translate(var(--m-3)); }
  75%, 80% { transform: translate(var(--m-4)); }
  100% { transform: translate(var(--m-1)); }
}

@keyframes reasoning-orb-morph-twist {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.reasoning-infinity {
  width: 18px;
  height: 18px;
  overflow: visible;
}

.reasoning-infinity svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.reasoning-infinity path {
  vector-effect: non-scaling-stroke;
  stroke-linejoin: round;
}

.reasoning-infinity-track {
  stroke: currentColor;
  stroke-width: 2;
  opacity: 0.26;
}

.reasoning-infinity-line {
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-dasharray: 78;
  stroke-dashoffset: 0;
  animation: reasoning-infinity-trim 6.2s cubic-bezier(0.3, 0, 0.3, 1) infinite;
}

.reasoning-terminal {
  justify-content: start;
}

.terminal-cursor {
  width: 1.5px;
  height: 12px;
  border-radius: 1px;
  background: currentColor;
  animation: terminal-cursor-blink 950ms steps(1, end) infinite;
}

.reasoning-minimal::before {
  width: 24px;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
  animation: reasoning-minimal-sweep 1.25s ease-in-out infinite;
  opacity: 0.72;
  content: "";
}

/* Per-character shimmer (Codex-style): each glyph carries the same diagonal
   light sweep, delayed by its index so a single soft highlight travels
   left→right across the word. No vertical float — the text must not bob. */
/* The rule down the settled body's left edge marks the recount as quoted
   rather than said.
   Keyed on `data-done-rule`, not on `doneStyle="timed"`. It used to ride along
   with the timed title, so a reader who wanted the clock got the rule whether
   they wanted it or not — and could not have the rule with any other title. */
.reasoning-block[data-done-rule="true"][data-status="done"] .reasoning-body {
  border-left: 1.5px solid var(--border-subtle);
  padding-left: 12px;
}

/* Peek one line: the block stays closed, the body shows its first line and
   fades out. `max-height` in `em` so it tracks the text size rather than a
   guessed pixel height, and the mask does the fade — a gradient overlay would
   have to know the surface colour, which varies per style. */
.reasoning-block[data-done-body="first-line"][data-status="done"] .reasoning-body {
  display: block;
  max-height: 1.7em;
  overflow: hidden;
  mask-image: linear-gradient(to bottom, #000 0.6em, transparent 1.7em);
}

/* How the reasoning text arrives. Ported from the exported scaffold's
   stylesheet, which had these three for the answer text and nothing for the
   thinking — so the configurator's canvas showed no difference at all. */
/* The summary arrives as a couple of lines of plain text, and the newlines are
   the author's: one thought per line reads as reasoning, one long wrapped
   paragraph reads as prose. */
.reasoning-body p {
  white-space: pre-line;
}

/* How the reasoning text arrives is `WritingText`'s job now — a real
   progressive reveal, the same component that writes the answer out. Three CSS
   stand-ins used to live here (a fade, a `max-height` "typewriter", an opacity
   ramp); they animated the block rather than the text, wiping it in one go and
   unable to follow wrapped lines, which is the reason that component exists.
   `data-writing-motion` stays on the body as a styling hook. */

.reasoning-block[data-motion="shimmer"] .reasoning-title {
  overflow: visible;
}
.reasoning-block[data-motion="shimmer"] .reasoning-title > span {
  display: inline-block;
  background: linear-gradient(
    100deg,
    var(--text-muted) 0%,
    var(--text-muted) 42%,
    color-mix(in srgb, var(--accent) 30%, #ffffff) 50%,
    var(--text-muted) 58%,
    var(--text-muted) 100%
  );
  background-size: 240% 100%;
  background-position: 130% 0;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: reasoning-text-shimmer 1.8s linear infinite;
  animation-delay: calc(var(--char-index, 0) * 0.14s);
}

/* Shimmer thinking has no leading glyph (only the illustrated style swaps in an
   orb), so drop the empty indicator column and keep the chevron next to text. */
/* Two motions whose whole indicator is the words: shimmer sweeps them, bars
   cycles through the stages. Neither draws a glyph beside the text — a glyph
   would be a second thing saying "working" next to the words already saying it. */
/* Only shimmer loses its glyph now.
   The `bars` arm of these two rules is gone: the text cycle is no longer a
   motion, so there is no glyph of its own to suppress, and the glyph standing
   beside it belongs to whichever indicator the reader picked. Hiding it here
   was what made "dots + cycling text" impossible to see even once the two
   stopped overwriting each other in the schema.
   Shimmer keeps the rule because it genuinely *is* the words — the sweep is
   drawn across the title itself, so a glyph would be a second thing saying
   "working" next to it. */
.preview-frame:not([data-style-preset="illustrated"]) .reasoning-block[data-motion="shimmer"] .reasoning-header {
  grid-template-columns: auto auto;
  justify-content: start;
  padding-left: 2px;
}
.preview-frame:not([data-style-preset="illustrated"]) .reasoning-block[data-motion="shimmer"] .reasoning-indicator-slot {
  display: none;
}

/* The stage label fades as it swaps, so the words read as one line changing its
   mind rather than three labels taking turns. Keyed on the text, so the
   animation restarts on every change. */
/* Keyed on the block's own cycling flag rather than on `data-motion="bars"`,
   which no longer exists as a motion. */
.reasoning-block[data-text-cycle="true"] .reasoning-title,
.pv-thinking-label[data-cycling="true"] {
  animation: thinking-stage-in var(--motion-base) var(--ease-out);
}
@keyframes thinking-stage-in {
  from { opacity: 0; transform: translateY(2px); }
}

/* Reasoning finished ("已完成思考"): the glyph stays, at rest.
   It used to be removed outright here, on the reading that a finished block has
   no activity to announce. But the glyph is also the answer to "which indicator
   did I pick" — a reader who chooses Dots and then Thought for N seconds was
   shown the seconds and no dot, and had no way to tell whether the first choice
   had taken. `ReasoningIndicator` already threads `active={running}` into both
   its variants (`paused` on the orb, `active` on the classic glyph), so what
   shows here is a still mark rather than something animating in a block that
   has stopped.
   The header keeps its two-column shape: with the indicator present there is no
   third thing to place, since the chevron sits beside the label either way. */
.preview-frame .reasoning-block[data-status="done"] .reasoning-header {
  justify-content: start;
  padding-left: 2px;
}

.reasoning-bars {
  display: inline-flex;
  justify-content: center;
  gap: 3px;
}

.reasoning-bars span {
  width: 4px;
  height: 14px;
  border-radius: 999px;
  background: currentColor;
  animation: reasoning-bar-wave 840ms ease-in-out infinite;
}

.reasoning-bars span:nth-child(2) {
  animation-delay: 110ms;
}

.reasoning-bars span:nth-child(3) {
  animation-delay: 220ms;
}

.reasoning-body,
.tool-card-body {
  overflow: hidden;
}

.reasoning-body p,
.tool-card-body {
  padding: 0 10px 10px 31px;
}

.reasoning-block[data-collapse="summary-first"] {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.reasoning-block[data-collapse="summary-first"] .reasoning-header {
  padding: 10px 2px 5px;
}

.reasoning-block[data-collapse="summary-first"] .reasoning-header:hover {
  background: transparent;
}

/* The always-open body used to read in the primary ink while its label stayed
   muted — the same two-voice split, arriving through the disclosure mode rather
   than through a style. Colour comes from `--reasoning-type-color` now. */
.reasoning-block[data-collapse="summary-first"] .reasoning-body p {
  padding: 0 2px 4px;
}

.display-block {
  display: grid;
  gap: 5px;
  margin-top: 8px;
}

.display-block span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 650;
  text-transform: none;
}

.tool-style-badge {
  border-radius: 999px;
  padding: 3px 7px;
  background: var(--surface-inset);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 620;
}

.tool-card[data-style="inline"],
.tool-card[data-style="expanded"] {
  width: 100%;
}

.tool-card[data-style="inline"] .tool-card-header,
.tool-card[data-style="expanded"] .tool-card-header {
  grid-template-columns: auto minmax(0, 1fr) auto;
  padding: 7px 9px;
}

.tool-card[data-style="inline"] .tool-preview,
.tool-card[data-style="inline"] .chevron,
.tool-card[data-style="expanded"] .tool-preview,
.tool-card[data-style="expanded"] .chevron {
  display: none;
}

.tool-card[data-timeline-rail="true"] {
  position: relative;
}

.tool-card[data-timeline-rail="true"] .tool-card-header {
  position: relative;
}

/* Node: a soft green circle-check (matching the reference). Its left edge is
   flush with the lane (aligned with the agent name); vertically centred on the
   header row whether the card is collapsed or expanded. */
.tool-card[data-style="drawer"] {
  border-color: color-mix(in srgb, var(--text-primary) 20%, var(--border-subtle));
  background: color-mix(in srgb, var(--surface-inset) 55%, var(--surface-panel));
}

.tool-card[data-style="drawer"] pre {
  background: var(--text-primary);
  color: var(--text-inverse);
}

.tool-progress {
  height: 3px;
  overflow: hidden;
  margin: -2px 10px 8px 33px;
  border-radius: 999px;
  background: var(--surface-inset);
}

.tool-progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
}

.tool-progress[data-status="running"] span,
.tool-progress[data-status="args_streaming"] span {
  animation: tool-progress-running 1s ease-in-out infinite;
}

pre {
  overflow: auto;
  margin: 0;
  border-radius: calc(var(--radius) - 2px);
  background: var(--surface-inset);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 1.5;
  padding: 9px;
  white-space: pre-wrap;
}

.approval-box,
.external-approval-panel {
  display: grid;
  gap: 8px;
  margin-bottom: 8px;
  border: 1px solid color-mix(in srgb, var(--warning) 32%, var(--border-subtle));
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--warning) 8%, var(--surface-panel));
  padding: 8px;
  color: var(--warning);
  font-size: 12px;
}

.external-approval-panel {
  width: min(620px, 84%);
  margin-bottom: 0;
}

/* In the canvas the approval panel spans the full lane, aligning its right edge
   with the user row (like the tool cards below it).
   Expressed as the composer's measure rather than a literal 100%: during a conversation the
   composer is the full lane and this still resolves to 100%, but in the welcome state the
   composer caps and centres, and a literal 100% left this panel on a different grid. */
.preview-frame .external-approval-panel {
  width: min(var(--composer-measure, 100%), 100%);
}

.approval-copy {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
}

.approval-copy div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.approval-copy strong {
  color: var(--text-primary);
  font-size: 12px;
}

.approval-copy span {
  color: var(--text-secondary);
  line-height: 1.35;
}

.approval-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.approval-actions button {
  min-height: 26px;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: var(--surface-raised);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 620;
  padding: 0 9px;
  cursor: pointer;
  transition: background var(--motion-fast) var(--ease-out),
    border-color var(--motion-fast) var(--ease-out),
    color var(--motion-fast) var(--ease-out),
    transform var(--motion-fast) var(--ease-out);
}

.approval-actions button:hover {
  border-color: var(--border-strong);
  background: var(--surface-hover);
}

.approval-actions button:active {
