  outline-offset: 1px;
}

.approval-actions button[data-approval-action="yes"] {
  border-color: color-mix(in srgb, var(--success) 42%, var(--border-subtle));
  color: var(--success);
}

.approval-actions button[data-approval-action="yes"]:hover {
  border-color: var(--success);
  background: color-mix(in srgb, var(--success) 12%, transparent);
}

.approval-actions button[data-approval-action="no"] {
