  color: var(--danger);
}

.approval-actions button[data-approval-action="no"]:hover {
  border-color: var(--danger);
  background: color-mix(in srgb, var(--danger) 12%, transparent);
}

.approval-decision {
  display: inline-flex;
  align-items: center;
