}

.external-approval-head div {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
}

.external-approval-title-row {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.external-approval-title-icon {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: none;
  border-radius: 999px;
  background: var(--surface-inset);
  color: var(--text-muted);
}

.external-approval-head strong {
  color: var(--text-primary);
  font-size: var(--text-md);
  font-weight: 700;
}

.external-approval-head span,
.external-approval-head small {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--text-muted);
  font-size: var(--text-sm);
  font-weight: 560;
  line-height: 1.45;
}

.external-approval-head .external-approval-title-row {
  gap: 7px;
  color: var(--text-primary);
}

.external-approval-head .external-approval-title-icon {
  display: inline-grid;
  place-items: center;
