}

.external-approval-options button[data-selected="true"] {
  border-color: transparent;
  background: var(--accent-soft);
  color: var(--text-primary);
}

.preview-frame[data-style-preset="native"] .external-approval-options button[data-selected="true"] {
  background: var(--native-sidebar-active);
}

.preview-frame[data-style-preset="native"] .external-approval-options button:hover {
  background: var(--native-sidebar-active);
}

.preview-frame[data-style-preset="native"][data-appearance="light"] .external-approval-options button[data-selected="true"] {
  background: var(--preview-hover-fill);
}

.preview-frame[data-style-preset="native"][data-appearance="light"] .external-approval-options button:hover {
  background: var(--preview-hover-fill);
  color: var(--preview-hover-text);
}

.external-approval-index {
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 720;
  text-align: right;
}

.external-approval-option-copy {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  min-width: 0;
}

.external-approval-option-copy strong {
  flex: none;
  color: inherit;
  font-size: var(--text-md);
  font-weight: 700;
}

.external-approval-option-copy span {
  overflow: hidden;
  color: var(--text-muted);
  font-size: var(--text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.external-approval-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
  padding-top: 1px;
}

.external-approval-footer > span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.35;
}

.external-approval-confirm {
  flex: none;
  min-height: 32px;
  border: 0;
  border-radius: 10px;
  background: var(--text-primary);
  color: var(--surface-panel);
  font-size: 12px;
  font-weight: 760;
  padding: 0 13px;
  cursor: pointer;
}

.inline-approval-panel {
  display: grid;
  gap: var(--space-2);
  width: 100%;
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  background: var(--surface-panel);
  /* Docked on the composer, so it only needs to lift off the transcript, not
     float over the page. */
  box-shadow: 0 6px 18px rgba(13, 18, 28, 0.08);
  color: var(--text-primary);
  padding: var(--space-3) var(--space-3) var(--space-2);
}

.inline-approval-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-3);
}

.inline-approval-head > div:first-child {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  min-width: 0;
}

.inline-approval-head span:first-child {
  flex: none;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: var(--surface-panel);
  color: var(--text-primary);
  font-size: var(--text-xs);
  font-weight: 400;
  line-height: 1;
  padding: 3px 9px;
}

.inline-approval-head strong {
  color: var(--text-primary);
  font-size: var(--text-md);
  font-weight: 400;
  line-height: 1.45;
}

.inline-approval-stepper {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  flex: none;
  color: var(--text-muted);
  font-size: var(--text-sm);
  font-weight: 620;
}

.inline-approval-stepper button {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
}

.inline-approval-stepper button:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.inline-approval-options {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* Each option a row you can hit anywhere, with a quiet hover — a list of
   choices, not a numbered paragraph. */
.inline-approval-options li {
  display: grid;
  align-items: baseline;
  grid-template-columns: 20px minmax(0, 1fr);
  gap: var(--space-2);
  padding: 6px 8px;
  border-radius: 8px;
  color: var(--text-secondary);
  transition: background var(--motion-fast) var(--ease-out);
}

.inline-approval-options li:hover {
  background: var(--surface-hover);
}

.inline-approval-option-index {
  color: var(--text-muted);
  font-size: var(--text-sm);
  font-weight: 400;
  line-height: 1.45;
  text-align: right;
}

.inline-approval-options li div {
  display: inline;
  min-width: 0;
  line-height: 1.45;
}

.inline-approval-options li strong {
  margin-right: 10px;
  color: var(--text-primary);
  font-size: var(--text-md);
  font-weight: 400;
}

.inline-approval-options li span:not(.inline-approval-option-index) {
  color: var(--text-muted);
  font-size: var(--text-sm);
  font-weight: 400;
}

.inline-approval-option-button {
  display: block;
  width: 100%;
  min-width: 0;
  border: 0;
  background: transparent;
  color: inherit;
  line-height: 1.45;
  padding: 0;
  text-align: left;
  cursor: pointer;
}

.inline-approval-option-button:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 65%, transparent);
  outline-offset: 2px;
}

.inline-approval-option-button:disabled,
.inline-approval-secondary:disabled,
.inline-approval-primary:disabled {
  cursor: wait;
  opacity: 0.58;
}

.inline-approval-answer {
  width: 100%;
  border: 0;
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  font-size: var(--text-md);
  line-height: 1.45;
  padding: 0;
}

.inline-approval-answer::placeholder {
  color: var(--text-muted);
}

.inline-approval-answer:focus {
  outline: none;
}

.inline-approval-options li[data-placeholder="true"] strong,
.inline-approval-options li[data-placeholder="true"] .inline-approval-option-index {
  color: color-mix(in srgb, var(--text-muted) 62%, var(--surface-panel));
}

.inline-approval-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  min-width: 0;
}

.inline-approval-footer > span {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--text-muted);
  font-size: var(--text-sm);
  font-weight: 560;
}

.inline-approval-info {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 999px;
  color: var(--text-secondary);
  font-size: var(--text-xs);
  font-style: normal;
  font-weight: 760;
  line-height: 1;
}

.inline-approval-footer div {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  flex: none;
}

.inline-approval-secondary,
.inline-approval-primary {
  min-height: 30px;
  border-radius: 10px;
  font-size: var(--text-sm);
  font-weight: 760;
  padding: 0 var(--space-3);
  cursor: pointer;
}

.inline-approval-secondary {
  border: 1px solid var(--border-subtle);
  background: var(--surface-panel);
  color: var(--text-primary);
}

.inline-approval-secondary:hover {
  background: var(--surface-hover);
}

.inline-approval-primary {
  border: 1px solid var(--text-primary);
  background: var(--text-primary);
  color: var(--surface-panel);
}

.inline-approval-primary:hover {
  background: color-mix(in srgb, var(--text-primary) 88%, var(--surface-panel));
}

.artifact-inline,
.step-item,
.error-item {
  display: grid;
  gap: 4px;
  padding: 10px;
}

.artifact-inline span:not(.artifact-launch-kind, .artifact-action-open span, .media-player-play, .media-player-play *, .media-player-video-play, .media-player-video-play *),
.step-item span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 650;
  text-transform: none;
}

.error-item {
  border-color: color-mix(in srgb, var(--danger) 35%, var(--border-subtle));
}

.error-item[data-collapse="true"] small {
  color: var(--text-muted);
  font-size: var(--preview-meta-size);
}

/* The composer sits on the stack's last row, so it stays at the bottom of the
   column whether or not a conversation is above it. The stack's rows are
   `minmax(0, 1fr) auto`; auto-placed, a composer with no conversation above it
   took the 1fr row and floated in the middle of the column. The welcome state
   has its own single-row grid and centres on purpose, so it is excluded. */
.preview-stack:not([data-welcome="true"]) > .composer-frame {
  grid-row: 2;
}

/*
 * …and with an approval open, it takes row 2 and the composer moves to 3.
 *
 * Without this the overlay was auto-placed: rows 1 and 2 were taken (the
 * conversation, and the composer pinned to 2), so it opened an implicit third
 * row and landed *under* the composer — a question answered below the field it
 * belongs to. Keyed on the overlay being there, so a stack with no approval
 * keeps its two rows and no extra gap.
 */
.preview-stack:not([data-welcome="true"]):has(> .preview-approval-overlay) {
  grid-template-rows: minmax(0, 1fr) auto auto;
}

.preview-stack:not([data-welcome="true"]):has(> .preview-approval-overlay) > .preview-approval-overlay {
  grid-row: 2;
}

.preview-stack:not([data-welcome="true"]):has(> .preview-approval-overlay) > .composer-frame {
  grid-row: 3;
}

/* While a question is open the composer steps back so the question sits right
   on the field: the prompt chips go (they are not an answer to it), and the
   run dock folds to its progress line. Both come back when it is answered. */
.preview-stack:has(> .preview-approval-overlay) > .composer-frame .prompt-shortcuts,
.preview-stack:has(> .preview-approval-overlay) > .composer-frame .run-dock :is(.run-dock-body, .run-dock-chevron) {
  display: none;
}

.composer-frame {
  display: grid;
  gap: var(--space-2);
  padding: 0;
  border: 0;
  background: transparent;
  border-radius: 0;
  box-shadow: none;
}

/* One unified input field: attachments + textarea + toolbar share a shell. */
.composer-shell {
  display: grid;
  gap: var(--space-2);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  background: var(--surface-panel);
  padding: var(--space-3) var(--space-3) var(--space-2);
  box-shadow: var(--shadow-sm);
  transition: border-color var(--motion-fast) var(--ease-out),
    box-shadow var(--motion-fast) var(--ease-out);
}

.composer-shell:has(.ui-textarea:focus) {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border-strong));
  box-shadow: var(--shadow-sm);
}

.prompt-shortcuts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.prompt-shortcuts button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: var(--control-sm);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: var(--surface-panel);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 400;
  padding: 0 9px;
}

.composer-prompt-row {
  position: relative;
  display: grid;
  gap: 8px;
  min-width: 0;
  min-height: 34px;
}

.prompt-context {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  max-width: calc(100% - 24px);
}

.context-chips {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  min-width: 0;
}

.context-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  min-height: 24px;
  border: 1px solid transparent;
  border-radius: var(--radius-full);
  background: var(--surface-inset);
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 400;
  padding: 2px 4px 2px 7px;
  transition: border-color var(--motion-fast) var(--ease-out),
    background var(--motion-fast) var(--ease-out);
}

.context-chip:hover {
  border-color: var(--border-strong);
  background: var(--surface-hover);
}

.context-chip span,
.context-chip em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-style: normal;
  line-height: 1;
}

.context-chip .context-chip-remove {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-full);
  background: transparent;
  color: var(--text-muted);
  transition: background var(--motion-fast) var(--ease-out),
    color var(--motion-fast) var(--ease-out);
}

.context-chip .context-chip-remove:hover {
  background: color-mix(in srgb, var(--danger) 14%, transparent);
  color: var(--danger);
}

.context-chip em {
  color: var(--text-muted);
  opacity: 0.72;
}

.prompt-context button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 26px;
  padding: 0 8px;
  white-space: nowrap;
}

.composer-actions {
  justify-content: space-between;
  flex-wrap: nowrap;
  gap: 6px;
  min-width: 0;
}

.composer-tools {
  align-items: center;
  flex: 1 1 auto;
  flex-wrap: nowrap;
  gap: 6px;
  justify-content: flex-start;
  max-width: 100%;
  min-width: 0;
  overflow: hidden;
}

.composer-submit-controls {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.composer-tools .composer-upload {
  position: relative;
  margin-right: 12px;
}

.composer-tools .composer-upload::after {
  position: absolute;
  top: 50%;
  right: -10px;
  width: 1px;
  height: 11px;
  transform: translateY(-50%);
  background: var(--border-subtle);
  content: "";
  pointer-events: none;
}

.composer-frame[data-has-tools-after-upload="false"] .composer-tools .composer-upload {
  margin-right: 0;
}

.composer-frame[data-has-tools-after-upload="false"] .composer-tools .composer-upload::after {
  display: none;
}

.permission-mode-trigger,
.budget-mode-trigger,
.combined-model-budget-trigger {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: var(--control-md);
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 13px;
  font-weight: 400;
  padding: 0 8px;
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out);
}

.permission-mode-trigger:hover,
.permission-mode-trigger[data-state="open"],
.budget-mode-trigger:hover,
.budget-mode-trigger[data-state="open"],
.combined-model-budget-trigger:hover,
.combined-model-budget-trigger[data-state="open"] {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.permission-mode-trigger svg,
.budget-mode-trigger svg,
.provider-model-icon {
  flex: none;
}

.combined-model-budget-trigger {
  max-width: min(260px, 44vw);
  gap: 7px;
  background: var(--surface-inset);
  padding: 0 11px;
}

.combined-model-budget-model,
.combined-model-budget-budget {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.combined-model-budget-model {
  color: var(--text-secondary);
}

.combined-model-budget-budget {
  color: var(--text-muted);
}

.combined-model-budget-menu {
  display: grid;
  gap: 4px;
  min-width: 250px;
  max-width: min(360px, calc(100vw - 24px));
  border-radius: 10px;
  padding: 8px;
  box-shadow: var(--shadow-md);
}

.combined-model-budget-root-menu {
  min-width: 280px;
}

.combined-model-budget-submenu {
  min-width: 240px;
}

.combined-model-budget-label {
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
}

.combined-model-budget-summary-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 14px;
  gap: 8px;
  height: auto;
  min-height: 42px;
  align-items: center;
  border-radius: 7px;
  padding: 7px 8px 7px 10px;
}

.combined-model-budget-summary-item[data-highlighted],
.combined-model-budget-summary-item[data-state="open"] {
  background: var(--accent-soft);
}

.combined-model-budget-summary-item[data-highlighted] .combined-model-budget-row-label,
.combined-model-budget-summary-item[data-state="open"] .combined-model-budget-row-label {
  color: var(--accent);
}

.combined-model-budget-row-label,
.combined-model-budget-row-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.combined-model-budget-row-label {
  color: var(--text-primary);
}

.combined-model-budget-row-value {
  color: var(--text-muted);
}

.combined-model-budget-summary-item .composer-menu-chevron {
  color: var(--text-muted);
}

.combined-model-budget-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 18px;
  gap: 8px;
  height: auto;
  min-height: 36px;
  align-items: center;
  border-radius: 7px;
  padding: 7px 8px;
}

.combined-model-budget-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.combined-model-budget-copy strong,
.combined-model-budget-copy span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.combined-model-budget-copy strong {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.2;
}

.combined-model-budget-copy span {
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 400;
  line-height: 1.25;
}

.combined-model-budget-check {
  color: var(--accent);
  font-size: 18px;
  line-height: 1;
  text-align: center;
}

.combined-model-budget-separator {
  margin-block: 5px;
}

.permission-mode-trigger .composer-menu-chevron,
.budget-mode-trigger .composer-menu-chevron,
.provider-model-picker .composer-menu-chevron {
  width: 14px;
  height: 14px;
  stroke-width: 2;
  transform: rotate(0deg);
  transition: transform var(--motion-base) var(--ease-out);
}

.permission-mode-trigger[data-state="open"] .composer-menu-chevron,
.budget-mode-trigger[data-state="open"] .composer-menu-chevron,
.provider-model-picker:has(.ui-select[data-state="open"]) .composer-menu-chevron {
  transform: rotate(-90deg);
}

.permission-mode-menu,
.budget-mode-menu {
  display: grid;
  gap: 4px;
  min-width: 220px;
  border-radius: 18px;
  padding: 8px;
  box-shadow: var(--shadow-md);
}

.minimal-composer-menu.permission-mode-menu,
.minimal-composer-menu.budget-mode-menu {
  border-radius: 10px;
}

.minimal-composer-menu .permission-mode-item,
.minimal-composer-menu .budget-mode-item {
  border-radius: 7px;
}

.permission-mode-item,
.budget-mode-item {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) 18px;
  gap: 8px;
  height: auto;
  min-height: 44px;
  align-items: start;
  border-radius: 10px;
  padding: 7px 8px;
}

.permission-mode-item > svg,
.budget-mode-item > svg {
  width: 16px;
  height: 16px;
  margin-top: 1px;
  color: var(--text-primary);
}

/*
 * The unguarded approval mode reads in the danger colour — icon and label together, so it is
 * legible without relying on colour alone (the label already says "Allow all", and the hint
 * says what that costs).
 *
 * Only this one row is toned. If every row carried a status colour the menu would read as a
 * palette and the one choice with irreversible consequences would stop standing out.
 */
.permission-mode-item[data-tone="danger"] > svg,
.permission-mode-item[data-tone="danger"] .permission-mode-copy strong {
  color: var(--danger);
}

.permission-mode-copy,
.budget-mode-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.permission-mode-copy strong,
.budget-mode-copy strong {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.2;
}

.permission-mode-copy span,
.budget-mode-copy span {
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 400;
  line-height: 1.25;
}

.permission-mode-check,
.budget-mode-check {
  color: var(--accent);
  font-size: 18px;
  line-height: 1;
  text-align: center;
}

.text-control {
  height: var(--control-md);
  color: var(--text-secondary);
}

.model-picker {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: var(--control-md);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--surface-inset);
  padding: 0 10px;
  transition: border-color var(--motion-fast) var(--ease-out);
}

.provider-model-picker {
  position: relative;
  display: inline-flex;
  align-items: center;
  width: auto;
  flex: 0 1 auto;
  min-width: 0;
  height: var(--control-md);
  max-width: min(320px, 100%);
  overflow: visible;
  border: 1px solid transparent;
  border-radius: var(--radius-full);
  background: var(--surface-inset);
  color: var(--text-secondary);
  padding: 0;
  transition:
    background var(--motion-fast) var(--ease-out),
    border-color var(--motion-fast) var(--ease-out);
}

.provider-model-picker:hover {
  border-color: transparent;
}

.provider-model-summary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 220px;
  font-size: 13px;
  line-height: 1;
  white-space: nowrap;
}

.provider-model-summary em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-style: normal;
}

.provider-model-summary em {
  color: var(--text-muted);
  font-weight: 400;
}

.provider-model-menu .ui-select {
  width: auto;
  min-width: 0;
  height: 100%;
  justify-content: flex-start;
  gap: 5px;
  border: 0;
  border-radius: var(--radius-full);
  background: transparent;
  padding: 0 12px;
  color: var(--text-muted);
  box-shadow: none;
}

.provider-model-menu .ui-select:hover,
.provider-model-menu .ui-select[data-state="open"] {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
  color: var(--text-secondary);
}

.provider-model-menu .ui-select:focus-visible {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.provider-model-menu .ui-select-menu-value {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.provider-model-menu .ui-select-chevron {
  display: none;
}

.model-picker:hover {
  border-color: var(--border-strong);
}

.model-picker span {
  color: var(--text-muted);
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: none;
}

.model-picker select {
  height: calc(var(--control-md) - 10px);
  max-width: 142px;
  border: 0;
  background: transparent;
  padding: 0;
}

.send-button {
  flex-shrink: 0;
}

/*
 * Layer 1 primitive density compatibility.
 * ComposerFrame now renders Button / IconButton / Select primitives while
 * keeping the legacy composer class names (send-button / text-control /
 * model-picker). These scoped overrides win on specificity so the primitives
 * inherit the exact pre-refactor heights, paddings, and borderless model
 * picker look — visual density stays identical.
 */
.ui-button.send-button[data-size] {
  border-radius: var(--radius-full);
  padding: 0 18px;
  font-size: 13px;
  font-weight: var(--weight-strong);
}

.ui-button.text-control[data-size] {
  border-radius: var(--radius-md);
  padding: 0 10px;
  font-size: 13px;
  font-weight: var(--weight-body);
  border-color: transparent;
  background: transparent;
  color: var(--text-secondary);
}

.ui-button.text-control[data-size]:hover {
  border-color: transparent;
  background: var(--surface-inset);
}

.model-picker .ui-select-wrap {
  width: 100%;
  height: 100%;
}

.model-picker .ui-select-wrap[data-size] .ui-select {
  height: 100%;
  max-width: none;
  width: 100%;
  border: 0;
  background: transparent;
  border-radius: 0;
  padding: 0;
  color: transparent;
}

.model-picker .ui-select-chevron {
  display: none;
}

.composer-frame .ui-textarea {
  min-height: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 2px 3px;
  line-height: 1.5;
  resize: none;
}

.composer-prompt-row .ui-textarea {
  width: 100%;
  min-width: 0;
}

.composer-frame .ui-textarea:focus-visible {
  outline: none;
  box-shadow: none;
}

/* Attachment chips sit inside the first text line; the textarea's first line
   indents to create the wrap-around effect. */
.composer-shell .prompt-context {
  padding-bottom: 0;
  border-bottom: 0;
}

.prompt-shortcuts .ui-button[data-size] {
  height: auto;
  min-height: 28px;
  border-radius: 999px;
  padding: 0 9px;
  font-size: 12px;
  font-weight: 400;
}

.utility-card {
  min-height: 0;
  /* `clip`, not `hidden`: a hidden box can still be scrolled from script, and
     `scrollIntoView` did — it slid the right panel's card 2px sideways (its
     content is 237px in a 235px box) and cut the left edge off 工作区文件 and
     its highlight. `clip` clips the same and cannot be scrolled. */
  overflow: clip;
}

.artifact-frame {
  min-height: 140px;
}

.artifact-content,
.capability-list,
.changed-files,
.git-status {
  display: grid;
  gap: 8px;
  padding: 10px;
}

/* Code artifact reads as an intentional viewer: a header bar (file · lang ·
   copy) sitting above an inset code surface. */
.code-output {
  gap: 0;
  padding: 0;
}

.code-output .artifact-title {
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-muted);
}

.code-output .artifact-title span {
  color: var(--text-secondary);
}

.code-output .artifact-title code {
  margin-left: 2px;
}

.code-copy-button {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  margin-left: auto;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  transition: background var(--motion-fast) var(--ease-out),
    color var(--motion-fast) var(--ease-out);
}

.code-copy-button:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.code-output pre {
  margin: 10px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.diff-preview .diff-line {
  display: block;
  white-space: pre-wrap;
}

.diff-preview .diff-line-add {
  color: var(--success);
  background: color-mix(in srgb, var(--success) 12%, transparent);
}

.diff-preview .diff-line-del {
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 12%, transparent);
}

.diff-preview .diff-line-hunk {
  color: var(--info);
}

.diff-preview .diff-line-meta {
  color: var(--text-muted);
}

.markdown-preview {
  display: grid;
  gap: 6px;
  border-radius: calc(var(--radius) - 2px);
  background: var(--surface-inset);
  color: var(--text-secondary);
  padding: 10px;
}

.markdown-preview h4 {
  font-size: 14px;
  line-height: 1.2;
}

.markdown-preview li,
.markdown-preview p {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.45;
}

.markdown-preview li {
  margin-left: 14px;
}

/* --- Completed markdown rendering: lists, quotes, code, math, mermaid --- */

.markdown-preview ul {
  margin: 0;
  padding: 0;
  list-style: disc;
}

.markdown-preview h5 {
  font-size: 13px;
  line-height: 1.25;
  color: var(--text-primary);
}

.markdown-preview h6 {
  font-size: 12px;
  line-height: 1.3;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.markdown-preview blockquote {
  margin: 0;
  padding: 2px 0 2px 10px;
  border-left: 2px solid var(--accent);
  color: var(--text-secondary);
}

.markdown-preview hr {
  margin: 4px 0;
  border: 0;
  border-top: 1px solid var(--border-subtle);
}

.markdown-preview code {
  padding: 1px 5px;
  border-radius: calc(var(--radius) - 4px);
  background: var(--surface-inset);
  font-family: var(--font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace);
  font-size: 0.92em;
  color: var(--text-primary);
}

.markdown-preview pre.md-code-block {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--surface-inset);
  overflow-x: auto;
  font-family: var(--font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace);
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-primary);
  white-space: pre;
}

.markdown-preview pre.md-code-block::before {
  content: attr(data-language);
  display: block;
  margin-bottom: 6px;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-tertiary, var(--text-secondary));
}

.markdown-preview a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.markdown-preview .md-math-inline .katex {
  font-size: 1.05em;
}

.markdown-preview .md-math-block {
  display: block;
  overflow-x: auto;
  padding: 2px 0;
}

.markdown-preview .md-math-block .katex-display {
  margin: 0;
}

.markdown-preview code.md-math-fallback {
  color: var(--text-secondary);
}

.markdown-preview .md-mermaid {
  display: block;
  padding: 10px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--surface-inset);
  overflow-x: auto;
  text-align: center;
}

.markdown-preview .md-mermaid[data-mermaid-state="rendered"] svg {
  max-width: 100%;
  height: auto;
}

.markdown-preview .md-mermaid-placeholder {
  display: block;
  min-height: 96px;
  border-radius: calc(var(--radius) - 4px);
  background: var(--preview-soft-fill, var(--surface-inset));
  animation: md-mermaid-pulse 1.2s ease-in-out infinite;
}

.markdown-preview .md-mermaid[data-mermaid-state="failed"] pre {
  margin: 0;
  text-align: left;
  font-family: var(--font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace);
  font-size: 12px;
  white-space: pre;
}

@keyframes md-mermaid-pulse {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

.rendered-preview {
  display: grid;
  gap: 6px;
  min-height: 92px;
  align-content: center;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border-subtle));
  border-radius: calc(var(--radius) - 2px);
  background: var(--surface-inset);
  padding: 12px;
}

.rendered-preview strong {
  font-size: 14px;
}

.rendered-preview p {
  color: var(--text-muted);
}

.artifact-title {
  gap: 8px;
  min-width: 0;
}

.artifact-title span {
  min-width: 0;
  overflow: hidden;
  font-size: 13px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.artifact-title code,
.capability-item code,
.schema-strip code {
  border-radius: 999px;
  padding: 3px 7px;
  background: var(--surface-inset);
  color: var(--text-muted);
  font-size: 11px;
}

/* Inside the canvas the extension is a word, not a chip: the filled pill was a
   third surface in a card that already has a tab strip and a segmented
   control. `.schema-strip` above keeps its fill — that row is the editor's own
   debug chrome, not part of the product. */
.preview-frame :is(.artifact-title, .capability-item) code {
  background: transparent;
  padding: 0;
}

.capability-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  align-items: start;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 8px;
}

.capability-item strong {
  display: block;
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.capability-item p {
  margin-top: 2px;
  color: var(--text-muted);
  font-size: 12px;
}

.changed-files span {
  color: var(--text-muted);
  font-size: 11px;
}

.git-status {
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 8px;
  align-items: center;
  border-bottom: 1px solid var(--border-subtle);
}

.git-status span,
.git-status small {
  grid-column: 1 / -1;
  color: var(--text-muted);
  font-size: 11px;
}

.git-status strong {
  min-width: 0;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.changed-files code {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
  border-radius: var(--radius-md);
  background: var(--surface-inset);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 12px;
  padding: 7px 9px;
}

.changed-files code .file-path {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.changed-files code .diff-stat {
  display: inline-flex;
  flex: none;
  gap: 6px;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.changed-files code .stat-add {
  color: var(--success);
}

.changed-files code .stat-del {
  color: var(--danger);
}

.commit-message-panel {
  display: grid;
  gap: 4px;
  margin: 0 10px 10px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  background: var(--surface-inset);
  padding: 8px;
}

.commit-message-panel span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 650;
  text-transform: none;
}

.commit-message-panel strong {
  font-size: 12px;
}

.git-actions {
  justify-content: flex-end;
  gap: 8px;
  padding: 0 10px 10px;
}

.git-actions .secondary-button {
  min-width: 0;
  padding-inline: 9px;
  white-space: nowrap;
}

.debug-dock {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  height: 100%;
  overflow: hidden;
}

.debug-header span {
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 620;
}

.debug-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(280px, 0.7fr);
  gap: 10px;
  min-height: 0;
  padding: 10px;
}

.debug-pane {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-height: 0;
  overflow: hidden;
}

/* Harness capture import. Editor chrome only — never part of a composed product, and not
   packed into an export. All new selectors; nothing existing is modified. */
.harness-import {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  background: var(--surface-panel);
}

.harness-import[data-dragging] {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.harness-import-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--text-secondary);
  font-size: 12px;
}

.harness-import-drop {
  padding: 14px 10px;
  border: 1px dashed var(--border-subtle);
  border-radius: 8px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.harness-import-drop:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.harness-import-hint {
  margin: 0;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.5;
}

.harness-import-status {
  max-height: 220px;
  margin: 0;
  overflow: auto;
  font-size: 11px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.harness-import-status[data-tone="error"] {
  color: var(--danger, #d4380d);
}

/* Admission report. Spans the grid so the diagnosis reads as a band rather than being
   squeezed into a 0.7fr column. Only rendered when there is something to report, so the
   dock is unchanged for a stream that maps cleanly. */
.debug-pane-wide {
  grid-column: 1 / -1;
}

.debug-pane-wide pre {
  white-space: pre-wrap;
  word-break: break-word;
}

.debug-pane-wide[data-severity="blocked"] h4 {
  color: var(--danger, #d4380d);
}

.debug-pane h4 {
  margin-bottom: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  text-transform: none;
}

.event-rows {
  display: grid;
  align-content: start;
  gap: 4px;
  overflow: auto;
}

.event-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 78px;
  gap: 8px;
  align-items: center;
  border-radius: calc(var(--radius) - 2px);
  background: var(--surface-inset);
  padding: 6px 8px;
}

.event-row span,
.event-row em {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 12px;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-row code {
  color: var(--text-muted);
  font-size: 11px;
}

.empty-state {
  display: grid;
  place-items: center;
  min-height: 72px;
  padding: 12px;
  color: var(--text-muted);
  font-size: 13px;
  text-align: center;
}

.starter-prompts,
.capability-hints {
  grid-template-columns: repeat(3, minmax(0, auto));
  gap: 8px;
  justify-content: center;
}

.starter-prompts button {
  min-height: 28px;
  padding: 0 10px;
}

.starter-prompts button:hover {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border-subtle));
  background: var(--surface-inset);
  color: var(--accent);
}

.starter-prompts button:active {
  background: color-mix(in srgb, var(--surface-inset) 90%, black);
}

.capability-hints span {
  border-radius: 999px;
  background: var(--surface-inset);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
  padding: 6px 10px;
}

.schema-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 38px;
  padding: 8px 10px;
}

.activity-dots {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: currentColor;
}

.activity-dots span {
  border-radius: 999px;
  background: currentColor;
  opacity: 0.32;
}

.activity-dots[data-active="true"] span {
  animation: thinking-dot 1.2s ease-in-out infinite;
}

.activity-dots[data-active="true"] span:nth-child(2) {
  animation-delay: 120ms;
}

.activity-dots[data-active="true"] span:nth-child(3) {
  animation-delay: 240ms;
}

.activity-spinner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.activity-spinner[data-active="true"] svg {
  animation: spinner-rotate 0.9s linear infinite;
}

.tooltip-content {
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  background: var(--text-primary);
  color: var(--text-inverse);
  font-size: 12px;
  padding: 6px 8px;
}

.tooltip-arrow {
  fill: var(--text-primary);
}

/* WorkBuddy-style reading surface: fewer boxes, warmer neutrals, steadier type.
   Scoped to the generated preview so the configurator logic and chrome stay
   untouched. */
.preview-frame {
  --preview-header-height: 60px;
  --preview-header-x: 22px;
  /*
   * The corner every media surface in the output panel takes — the image
   * loader, the frame it develops inside, the revealed image, and the audio and
   * video players beside it.
   *
   * One token because they are concentric: the loader sits at `inset: 0` in its
   * frame, so a different radius on each is not a nested corner, it is a
   * mismatch. And a token rather than a literal because the literal was
   * `clamp(28px, 7%, 64px)`, written in a CSS module with no way to see which
   * style it was rendering in — so 像素风, whose whole radius scale is 0, drew a
   * 28px pillow while it was loading, and 复古风, which rounds at 8px, drew the
   * same one. Reported directly: this corner follows the style.
   *
   * Each style points it at its own largest radius, which is the right tier: in
   * this panel the media surface *is* the largest object. Eight styles need no
   * line at all because `--fn-r-xl` is already that tier for them; the three
   * that keep their scale under another name (原生风's `--nr-*`, 复古风's fluid
   * `--retro-round`, 无障碍风's `--minimal-radius-*`) say so below.
   */
  --preview-media-radius: var(--fn-r-xl);
  /* One scale for every style: 16 / 14 / 12.
     It used to be 16/15/13 here with 原生风 and 无障碍风 overriding copy and
     meta down a step — so five styles read at 15/13 and one at 14/12, and the
     difference was not a decision anyone had made about those five. Asked to
     put them all on 原生风's, which is the tighter of the two and the one the
     product opens in.
     Only 复古风 still declares its own, because its three are *fluid* (`cqi`,
     tied to the preview's width); its maxima are these same numbers, so at
     desktop it lands here too. See `docs/TYPE_SCALE_SPEC.md`. */
  --preview-title-size: 16px;
  --preview-copy-size: 14px;
  --preview-copy-line: 1.62;
  --preview-meta-size: 12px;
  --preview-soft-line: var(--border-subtle);
  --preview-soft-fill: var(--surface-inset);
  --preview-hover-fill: var(--accent-soft);
  --preview-hover-text: var(--accent);
  --preview-shimmer-light: #ffffff;
}

.preview-frame .chat-frame,
.preview-frame .utility-card,
/* The composer's holder paints nothing; `.composer-shell` inside it is the card.
   This used to fill the whole bottom strip — the prompt-shortcut chips sat on a
   panel-coloured band that read as a second surface under the conversation,
   with the real card floating inside it. Every style inherited that, which is
   why the band appeared in all four of the new ones too. */
.preview-frame .composer-frame {
  background: transparent;
  border: 0;
  box-shadow: none;
}

.preview-frame .frame-header,
.preview-frame .utility-header {
  justify-content: space-between;
  gap: 12px;
  min-height: var(--preview-header-height);
  padding: 10px var(--preview-header-x);
  border-bottom: 0;
}

.preview-frame .utility-header-leading {
  display: inline-flex;
  align-items: center;
  min-width: 0;
}

.preview-frame .output-header {
  padding-inline-end: 10px;
}

.preview-frame .output-header .utility-header-actions {
  margin-left: auto;
}


.preview-frame .frame-header h2,
.preview-frame .utility-header h3 {
  color: var(--text-primary);
  font-size: var(--preview-title-size);
  font-weight: 760;
  line-height: 1.25;
}

/* Optically centred, not just geometrically.
 *
 * A row centred with `align-items: center` centres the *line box*, and a line
 * box is not the ink: it carries the font's whole ascent and descent, which are
 * rarely symmetric around the glyphs you can see. Measured in 复古风, whose
 * EB Garamond has a 5/16 descent — the row, the title and both icons all had
 * their boxes on 236.0, and "My Agent"'s visible letters sat **2.35px below**
 * that line. Geometry said centred, the eye said low, and the eye was right.
 *
 * `text-box-trim` trims the box to the cap height and the alphabetic baseline,
 * so what gets centred is the ink. Behind `@supports` because it is recent
 * (Chrome 133+); without it the rows are exactly as before, which is the
 * current behaviour rather than a broken one.
 *
 * Applied to the canvas's two header voices — the centre column's title and the
 * left column's brand — because those are the rows where one short string sits
 * alone in a tall box and the offset has nothing to hide behind.
 */
@supports (text-box-trim: trim-both) {
  .preview-frame .frame-header h2,
  .preview-frame .utility-header h3,
  .preview-frame .session-brand-name,
  .preview-frame .session-brand-title {
    text-box-trim: trim-both;
    text-box-edge: cap alphabetic;
  }
}

.preview-frame .frame-header p,
.preview-frame .utility-header p {
  color: var(--text-muted);
  font-size: var(--preview-meta-size);
  line-height: 1.35;
}

.preview-frame .output-source-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border-radius: 999px;
  /* No track fill. The active button keeps its `--text-primary` colour and the
     pill below keeps its 1px ring, so which one is on is still legible without
     a plate behind the pair. */
  background: transparent;
}

.preview-frame .output-source-switch button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: auto;
  height: 30px;
  padding: 0 9px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: var(--preview-meta-size);
  font-weight: 650;
  line-height: 1;
  cursor: pointer;
  transition: background var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out);
}

.preview-frame .output-source-switch button svg {
  width: 15px;
  height: 15px;
  flex: none;
  stroke-width: 1.7;
}

.preview-frame .output-source-label {
  line-height: 1;
  white-space: nowrap;
}

.preview-frame .output-source-switch button:hover {
  background: var(--preview-hover-fill);
  color: var(--preview-hover-text);
}

/*
 * Colour only. The active tab's surface is now the shared `.output-source-pill`, which slides
 * between the two buttons; leaving a background here as well would paint a second, stationary
 * pill under the moving one.
 */
.preview-frame .output-source-switch button[data-active="true"] {
  color: var(--text-primary);
}

.preview-frame .output-source-pill {
  position: absolute;
  top: 2px;
  bottom: 2px;
  left: 0;
  z-index: 0;
  width: var(--source-pill-w, 0px);
  transform: translateX(var(--source-pill-x, 0px));
  pointer-events: none;
  /* The switch's radius, which every style sets to match its buttons — the
     minimal preset's squarer corner carries through. */
  border-radius: inherit;
  /* The ring alone. Filling it made the active segment a panel-coloured slab
     that read as a second surface inside the output card. */
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--preview-soft-line);
}

/* A slight overshoot, the spring the motion version had, so the ring arrives
   rather than stops. Only after the first measurement (`data-ready`). */
.preview-frame .output-source-pill[data-ready="true"] {
  transition:
    transform 320ms cubic-bezier(0.34, 1.32, 0.5, 1),
    width 320ms cubic-bezier(0.34, 1.32, 0.5, 1);
}

@media (prefers-reduced-motion: reduce) {
  .preview-frame .output-source-pill[data-ready="true"] { transition: none; }
}

/* Lift the label and icon above the pill; both are static by default and would paint under it. */
.preview-frame .output-source-switch button svg,
.preview-frame .output-source-label {
  position: relative;
  z-index: 1;
}

.preview-frame .status-pill {
  gap: 6px;
  min-height: 28px;
  padding: 0 12px;
  border: 0;
  background: color-mix(in srgb, var(--success) 13%, var(--surface-panel));
  color: var(--success);
  font-size: var(--preview-meta-size);
  font-weight: 700;
}

.preview-frame .timeline-list {
  gap: 20px;
  padding: 12px 26px 22px;
  scroll-padding: 12px;
  /* Thin, subtle, theme-tinted scrollbar (Codex-like). */
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text-muted) 30%, transparent) transparent;
  /* The soft bottom fade is below, on `[data-more-below]`. It used to live here
     unconditionally, and that is a different thing from what it is for: with
     nothing to scroll it still ate the last 28px of the last row, so a settled
     conversation's final pill sat under a wash with no content behind it to
     explain the fade. */
}

/* Scrolled content dissolves before the composer instead of cutting off hard —
   only while there *is* content below the fold, which `ChatFrame`'s
   `useMoreBelow` measures (`scrollHeight - scrollTop - clientHeight`).
   Applies across all styles.

   A mask, not a gradient overlay: several styles paint the conversation on a
   texture — halftone dots, paper tooth, a grid — and a flat gradient in the
   surface colour would sit on top of that as a visible band. */
.preview-frame .timeline-list[data-more-below="true"] {
  -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 28px), transparent);
  mask-image: linear-gradient(to bottom, #000 calc(100% - 28px), transparent);
}
.preview-frame .timeline-list::-webkit-scrollbar {
  width: 8px;
}
.preview-frame .timeline-list::-webkit-scrollbar-track {
  background: transparent;
}
.preview-frame .timeline-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  border: 2px solid transparent;
  background: color-mix(in srgb, var(--text-muted) 28%, transparent);
  background-clip: padding-box;
}
.preview-frame .timeline-list::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--text-muted) 44%, transparent);
  background-clip: padding-box;
}

.preview-frame .assistant-turn,
.preview-frame .message-item {
  gap: 14px;
}

.preview-frame .assistant-lane {
  gap: 10px;
  /* Fill to the row's right edge so the agent content module lines up with the
     right edge of the user row (avatar, or bubble when no avatar). */
  max-width: none;
}

.preview-frame .msg-stack {
  max-width: min(700px, 78%);
}

.preview-frame .assistant-turn-label,
.preview-frame .message-role {
  color: var(--text-muted);
  font-size: var(--preview-meta-size);
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
}

.preview-frame .msg-avatar,
.preview-frame .composer-greeting-avatar {
  --avatar-bg: var(--accent-soft);
  --avatar-fg: var(--accent);
  --avatar-fg-muted: color-mix(in srgb, var(--accent) 56%, var(--surface-panel));
  --avatar-cutout: color-mix(in srgb, var(--surface-panel) 86%, var(--accent-soft));
  --avatar-detail: var(--surface-panel);
  --avatar-stroke: color-mix(in srgb, var(--accent) 22%, var(--border-subtle));
  --avatar-active-cyan: color-mix(in srgb, var(--accent) 42%, var(--surface-panel));
  --avatar-active-blue: color-mix(in srgb, var(--accent) 72%, var(--surface-panel));
  --avatar-active-violet: color-mix(in srgb, var(--accent-hover) 84%, var(--surface-panel));
  --avatar-active-face: #020909;
  --avatar-active-face-top: color-mix(in srgb, var(--accent) 32%, var(--avatar-active-face));
  --avatar-orb-highlight: #ffffff;
  --avatar-orb-mid: color-mix(in srgb, var(--accent) 70%, #ffffff);
  --avatar-orb-base: var(--accent);
  --avatar-active-ripple-start: color-mix(in srgb, var(--accent-soft) 70%, var(--surface-panel));
  --avatar-active-ripple-end: color-mix(in srgb, var(--accent) 18%, transparent);
  --avatar-active-start: var(--accent);
  --avatar-active-mid: color-mix(in srgb, var(--accent-hover) 82%, var(--surface-panel));
  --avatar-active-end: color-mix(in srgb, var(--accent) 74%, var(--warning));
  width: 28px;
  height: 28px;
  border: 0;
  background: var(--surface-soft, var(--surface-inset));
  color: var(--text-secondary);
  box-shadow: none;
}

.preview-frame .msg-avatar:has(.active-robot-face) {
  --avatar-bg: var(--surface-panel);
  width: 48px;
  height: 48px;
  overflow: visible;
}

.preview-frame[data-appearance="light"] .msg-avatar:has(.active-robot-face) {
  --avatar-bg: #ffffff;
}

.preview-frame .msg-avatar[data-role="assistant"] {
  background: var(--accent);
  color: var(--text-inverse);
}

.preview-frame .msg-avatar[data-role="assistant"]:has(.active-robot-face) {
  background: #ffffff;
}

.preview-frame[data-style-preset="native"][data-theme-preset="soft-glass"] .msg-avatar {
  --avatar-bg: #D7E1F3;
  --avatar-fg: #1F4E9D;
  --avatar-fg-muted: color-mix(in srgb, #1F4E9D 54%, #D7E1F3);
  --avatar-cutout: color-mix(in srgb, #FFFFFF 88%, #D7E1F3);
  --avatar-detail: #FFFFFF;
  --avatar-stroke: color-mix(in srgb, #1F4E9D 18%, #D7E1F3);
  --avatar-orb-highlight: color-mix(in srgb, #FFFFFF 86%, #28477D);
  --avatar-orb-mid: color-mix(in srgb, #28477D 82%, #FFFFFF);
  --avatar-orb-base: #28477D;
}

.preview-frame[data-style-preset="native"][data-theme-preset="soft-glass"] {
  --composer-voice-active-bg: #A9C3FF;
}

.preview-frame[data-style-preset="native"][data-theme-preset="soft-glass"] .robot-face {
  --avatar-bg: #D7E1F3;
  --avatar-fg: #28477D;
  --avatar-fg-muted: #28477D;
  --robot-face-body-offset-y: 1.8px;
}

.preview-frame[data-style-preset="native"][data-theme-preset="soft-glass"] .robot-face-highlight {
  display: none;
}

.preview-frame[data-style-preset="native"][data-theme-preset="soft-glass"] .agent-orange-blob-avatar {
