.preview-frame .message-item p,
.preview-frame .reasoning-body p,
.preview-frame .step-item p,
.preview-frame .error-item p,
.preview-frame .artifact-content p,
.preview-frame .message-bubble[data-role="assistant"] .msg-surface p {
  color: var(--text-primary);
  font-size: var(--preview-copy-size);
  line-height: var(--preview-copy-line);
}

.preview-frame .message-action-icon {
  border-color: transparent;
  background: transparent;
  color: var(--text-muted);
}

.preview-frame .message-action-icon:hover {
  border-color: transparent;
  background: var(--preview-hover-fill);
  color: var(--preview-hover-text);
}

.preview-frame .reasoning-block,
.preview-frame .tool-card,
.preview-frame .artifact-inline,
/* `.error-item` is deliberately absent: a run state is a card again, on
   request, and this rule is what used to flatten it. Everything else in the
   list keeps the canvas's no-chrome default. */
.preview-frame .step-item,
.preview-frame .empty-state,
.preview-frame .approval-box {
  border-color: transparent;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.preview-frame .reasoning-block,
.preview-frame .tool-card {
  border-left: 0;
}

.preview-frame .reasoning-header,
.preview-frame .tool-card-header {
  padding: 8px 0;
  border-radius: 8px;
  gap: 2px;
}

.preview-frame .reasoning-header:hover {
  background: transparent;
}

/* Read/Edit tool cards always carry a card background — collapsed AND expanded —
   themed for light / dark; hover shifts the whole-card fill. */
.preview-frame {
  --tool-card-bg: #ffffff;
  --tool-card-hover: var(--preview-hover-fill);
  --tool-file-link: #3f6f9f;
  --tool-file-link-hover: #28547f;
}
.preview-frame[data-appearance="dark"] {
  --tool-card-bg: rgba(255, 255, 255, 0.08);
  --tool-card-hover: var(--preview-hover-fill);
  --tool-file-link: #93b9d8;
  --tool-file-link-hover: #b6d4ec;
}
.preview-frame .tool-card {
  background: var(--tool-card-bg);
  /* Theme-derived hairline so a white card stays legible on a white canvas
     without shouting — --border-strong follows the active theme (light/dark). */
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  padding: 0 10px;
}
.preview-frame .tool-card:hover {
  background: var(--tool-card-hover);
}

.preview-frame .tool-card[data-action] {
  width: 100%;
  justify-self: stretch;
  border: 0;
  border-left-width: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  padding: 0;
}

.preview-frame .tool-card[data-action]:hover {
  background: transparent;
}

.preview-frame .tool-card[data-action] .tool-status-icon {
  background: transparent;
}

.preview-frame .tool-card[data-action] .tool-progress[data-status="running"] span,
.preview-frame .tool-card[data-action] .tool-progress[data-status="args_streaming"] span {
  animation: none;
  transform: none;
}

/* Hover paints the whole card, so keep the header itself transparent. */
.preview-frame .tool-card-header:hover {
  background: transparent;
}

.preview-frame .reasoning-header {
  grid-template-columns: auto auto auto;
  justify-content: start;
}

.preview-frame:not([data-style-preset="illustrated"]) .reasoning-block[data-motion="shimmer"] .reasoning-header {
  grid-template-columns: auto auto;
  justify-content: start;
}

.preview-frame .tool-card-header {
  grid-template-columns: auto auto auto auto auto;
  justify-content: start;
  cursor: pointer;
}

.preview-frame .tool-card-header[data-clickable="false"] {
  cursor: default;
}

.preview-frame .tool-card .tool-status-icon {
  width: 20px;
  height: 20px;
  background: transparent;
  color: var(--text-muted);
}

.preview-frame .tool-title {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  color: var(--text-muted);
  font-size: var(--preview-copy-size);
  line-height: 1.3;
}

.preview-frame .tool-card[data-action] .tool-title {
  color: var(--text-muted);
}

.preview-frame .tool-card[data-status="running"][data-action] .tool-title,
.preview-frame .tool-card[data-status="args_streaming"][data-action] .tool-title,
.preview-frame .tool-card[data-running-title="true"][data-action] .tool-title {
  background: linear-gradient(
    100deg,
    var(--text-muted) 0%,
    var(--text-muted) 34%,
    color-mix(in srgb, var(--preview-shimmer-light) 92%, transparent) 48%,
    color-mix(in srgb, var(--preview-shimmer-light) 60%, var(--text-muted)) 56%,
    var(--text-muted) 68%,
    var(--text-muted) 100%
  );
  background-size: 260% 100%;
  background-position: 180% 0;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: tool-title-shimmer 1.7s linear infinite;
}

.preview-frame .tool-card[data-status="cancelled"] .tool-title,
.preview-frame .tool-card[data-status="success"][data-action]:not([data-running-title="true"]) .tool-title {
  background: none;
  color: var(--text-muted);
  animation: none;
}

.preview-frame .tool-card[data-action]:hover .tool-card-header,
.preview-frame .tool-card[data-file-tool="true"]:hover .tool-card-header {
  background: transparent;
}

.preview-frame .tool-card[data-action]:hover .tool-status-icon,
.preview-frame .tool-card[data-action]:hover .tool-title,
.preview-frame .tool-card[data-action]:hover .tool-preview,
.preview-frame .tool-card[data-action]:hover .tool-disclosure-button,
.preview-frame .tool-card[data-file-tool="true"]:hover .tool-status-icon,
.preview-frame .tool-card[data-file-tool="true"]:hover .tool-title,
.preview-frame .tool-card[data-file-tool="true"]:hover .tool-preview,
.preview-frame .tool-card[data-file-tool="true"]:hover .tool-disclosure-button {
  background: none;
  color: var(--text-primary);
  animation: none;
}

.preview-frame .tool-title-file {
  display: inline-flex;
  min-width: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--tool-file-link, #3f6f9f);
  padding: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.preview-frame .tool-title-file:hover {
  color: var(--tool-file-link-hover, #28547f);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.preview-frame .tool-title-file:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--tool-file-link, #3f6f9f) 45%, transparent);
  outline-offset: 3px;
}

.preview-frame .tool-file-list {
  display: grid;
  gap: 4px;
  padding: 2px 0 8px;
}

.preview-frame .tool-card[data-timeline-rail="true"] .tool-card-body {
  padding-left: var(--tool-timeline-title-x, 23px);
}

.preview-frame .tool-card[data-timeline-rail="true"] .tool-file-list {
  --tool-timeline-rail-x: -14.5px;
  position: relative;
  padding-left: 0;
}

.preview-frame .tool-card[data-timeline-rail="true"] .tool-file-list::before {
  position: absolute;
  top: 0.72em;
  bottom: calc(0.72em + 8px);
  left: var(--tool-timeline-rail-x);
  width: 1px;
  background: var(--border-subtle);
  content: "";
}

.preview-frame .tool-file-row {
  display: flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
  color: var(--text-muted);
  font-size: var(--preview-copy-size);
  font-weight: 400;
  line-height: 1.45;
}

.preview-frame .tool-file-row-status {
  flex: none;
}

.preview-frame .tool-card[data-action] .tool-file-row-status[data-active="true"] {
  background: linear-gradient(
    100deg,
    var(--text-muted) 0%,
    var(--text-muted) 38%,
    color-mix(in srgb, var(--preview-shimmer-light) 88%, transparent) 50%,
    var(--text-muted) 62%,
    var(--text-muted) 100%
  );
  background-size: 240% 100%;
  background-position: 160% 0;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: tool-title-shimmer 1.9s linear infinite;
}

.preview-frame .tool-file-row-name {
  max-width: min(240px, 58%);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.preview-frame .tool-file-row-meta {
  flex: none;
  color: var(--text-muted);
  font-size: var(--preview-meta-size);
}

.preview-frame .tool-disclosure-button {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  padding: 0;
  cursor: pointer;
}

/* The chevron arrives on hover, and stays while the card is open.
   Faded with `opacity`, not removed with `display`: the button holds 14px in
   the header row, so taking it out of flow would shift the title sideways
   every time the pointer crossed the card. Kept at 1 when
   `aria-expanded="true"` because an opened card whose only close control is
   invisible reads as stuck — the reader opened it, the affordance should not
   then hide from them. `:focus-within` is the keyboard's version of hover:
   tabbing to the control has to reveal it too. */
.preview-frame .tool-disclosure-button {
  opacity: 0;
  transition: opacity 120ms ease;
}

.preview-frame .tool-card:hover .tool-disclosure-button,
.preview-frame .tool-card:focus-within .tool-disclosure-button,
.preview-frame .tool-disclosure-button[aria-expanded="true"] {
  opacity: 1;
}

.preview-frame .tool-disclosure-button:hover {
  background: transparent;
  color: var(--text-primary);
}

.preview-frame .reasoning-title,
.preview-frame .tool-title {
  color: var(--text-muted);
  font-size: var(--preview-copy-size);
  font-weight: 400;
  line-height: 1.3;
}

.preview-frame .reasoning-meta code,
.preview-frame .tool-preview,
.preview-frame .artifact-inline em {
  color: var(--text-muted);
  font-family: var(--font-ui);
  font-size: var(--preview-meta-size);
  font-weight: 500;
}

.preview-frame .reasoning-header:hover .reasoning-title,
.preview-frame .reasoning-header:hover .reasoning-meta code,
.preview-frame .reasoning-header:hover .chevron,
.preview-frame .reasoning-header:hover .reasoning-indicator-slot,
.preview-frame .reasoning-header:hover .reasoning-classic,
.preview-frame .reasoning-header:hover .reasoning-native-orb,
.preview-frame .reasoning-header:hover .reasoning-pulse,
.preview-frame .reasoning-header:hover .reasoning-terminal,
.preview-frame .reasoning-header:hover .reasoning-minimal,
.preview-frame .reasoning-header:hover .reasoning-bars,
.preview-frame .reasoning-header:hover .reasoning-ninety-ring {
  color: var(--text-primary);
}

.preview-frame .reasoning-header:hover .reasoning-title[data-shimmer-text="true"] > span {
  background: none;
  color: var(--text-primary);
  animation: none;
}

.preview-frame .artifact-inline,
.preview-frame .step-item,
.preview-frame .error-item {
  gap: 2px;
  padding: 8px 0;
}

/* ---- A run state, as a card --------------------------------------------
   One card, one line, one sentence: the glyph, the state, and the cause and
   result together. No disclosure — there is nothing folded away, so a chevron
   would open an empty box.

   It went through two wrong shapes first, both worth naming. It was one line of
   three registers (state word + prose + "调试详情已隐藏于侧栏"), which read as a
   run-on; then three stacked lines, which is right for a client that has detail
   behind them and wrong here, where the sentence *is* the detail. */
.preview-frame .error-item {
  display: flex;
  flex-direction: row;
  /*
   * Centred, not `baseline`.
   *
   * `baseline` sets the icon's *bottom* on the text's baseline — an icon box
   * has no text in it, so its baseline is its bottom margin edge. Measured,
   * that put the glyph 12px from the top of the row and 15.9px from the bottom
   * in every style: 3.9px high, in a 43px row.
   *
   * It also made the row's height depend on the icon's, and the extra landed
   * entirely above the text. 游戏风's marks are 19px images where the other
   * styles' are 15px SVGs, so its row was 4px taller and its sentence sat 5.2px
   * below centre while the other four were within 1.2px. That is the reported
   * one.
   *
   * `.step-item`, the row directly beside this one, has always been `center`;
   * this was the odd one out rather than the convention.
   */
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--fn-r-md, 10px);
  background: var(--surface-panel);
}

/* The 1px nudge `agentmatrix.css` gives this icon is for *its* layout, where
   the row is `align-items: flex-start` and the glyph needs lifting off the
   text's ascent. On a centred row it is just 0.5px of decentring.

   The colour is the other half, and it applies to every style on the canvas:
   the same `--text-muted` the tool rows' `.tool-status-icon` uses, not
   `--danger`. Asked for directly — 所有风格的画布内容区都不要这个红色，要和工具
   行的色调一致.

   `agentmatrix.css` sets `.error-icon { color: var(--danger) }` for the
   component library, and that stays: a run's incident list outside the canvas
   is a place where red is the point. This is scoped to `.preview-frame` because
   what changed is the *canvas*, where four consecutive red rows under one
   assistant turn read as an alarm rather than as a transcript — the tool rows
   above them report failure in ink and are legible precisely because they do.
   原生风 already reached this conclusion on its own and overrode the red
   locally ("the native surface stays calm"); that override is now the rule
   rather than one style's exception, and it keeps its own further-muted mix. */
.preview-frame .error-item .error-icon {
  margin-top: 0;
  color: var(--text-muted);
}

/* The sentence takes the *state word's* treatment, which is what it replaced:
   primary ink at the row size, not the secondary prose the paragraph would
   otherwise get. Asked for: 字的视觉效果要按重试中三个字来. */
.preview-frame .error-item > p {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  color: var(--text-primary);
  font-size: var(--preview-copy-size);
  line-height: 1.35;
}

/* The code stays a machine string rather than joining the sentence: it is an
   identifier the reader copies, not prose. */
.preview-frame .error-item-code {
  flex: none;
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 0.85em;
  color: var(--text-muted);
}

/* ---- A stopped run, as a break in the stream ---------------------------
   A rule across the column with the word on it. The interrupt used to be a row
   like any other, which put `session` — an internal kind name — at the front of
   a sentence, and made "the reader stopped this" look like something the agent
   said. */
.preview-frame .run-separator {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  color: var(--text-muted);
  font-size: var(--preview-meta-size, 12px);
}

/* The word and its glyph read as one mark on the line. */
.preview-frame .run-separator-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.preview-frame .run-separator::before,
.preview-frame .run-separator::after {
  flex: 1;
  height: 1px;
  background: var(--border-subtle);
  content: "";
}

/* Every span in the card, minus the two that are words rather than markers.
   This is what was bolding the type badge and the open control in the three
   styles that do not override them: a blanket `span` rule outranks a rule named
   for the class (0,2,1 against 0,2,0), so setting the weight on
   `.artifact-launch-kind` had no effect outside 漫画风, which happened to carry
   its own. Excluded here rather than fought with higher specificity — the two
   are not markers, and the exclusion says so where a reader will find it. */
.preview-frame .artifact-inline span:not(.artifact-launch-kind, .artifact-action-open span, .media-player-play, .media-player-play *, .media-player-video-play, .media-player-video-play *),
.preview-frame .step-item span {
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.preview-frame .artifact-inline strong,
.preview-frame .step-item strong,
.preview-frame .error-item strong {
  color: var(--text-primary);
  font-size: var(--preview-copy-size);
  line-height: 1.35;
}

/* Artifact reference card — a produced file shown as [type icon | name + kind |
   status badge], instead of three loose stacked lines. */
.preview-frame .artifact-inline {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border-strong);
  border-radius: 12px;
  background: var(--tool-card-bg);
}
.preview-frame .artifact-inline .artifact-inline-icon {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: none;
  border-radius: 8px;
  background: var(--preview-soft-fill);
  color: var(--text-secondary);
}
.preview-frame .artifact-inline .artifact-inline-body {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
  min-width: 0;
}
.preview-frame .artifact-inline .artifact-inline-body strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.preview-frame .artifact-inline .artifact-inline-kind {
  font-size: var(--preview-meta-size);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}
.preview-frame .artifact-inline .artifact-inline-status {
  flex: none;
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: var(--preview-meta-size);
  font-weight: 600;
  font-style: normal;
  color: var(--text-muted);
  background: var(--preview-soft-fill);
}
.preview-frame .artifact-inline .artifact-inline-status[data-status="success"],
.preview-frame .artifact-inline .artifact-inline-status[data-status="done"],
.preview-frame .artifact-inline .artifact-inline-status[data-status="completed"] {
  color: var(--success);
  background: color-mix(in srgb, var(--success) 14%, transparent);
}
.preview-frame .artifact-inline .artifact-inline-status[data-status="error"],
.preview-frame .artifact-inline .artifact-inline-status[data-status="cancelled"] {
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 14%, transparent);
}

.preview-frame .artifact-launch-card {
  gap: 14px;
  min-height: 64px;
  padding: var(--space-3) var(--space-4);
  border-color: var(--border-strong);
  border-radius: 16px;
  background: var(--surface-panel);
  box-shadow: none;
}

.preview-frame .artifact-launch-card .artifact-inline-icon {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: var(--surface-inset);
  color: color-mix(in srgb, var(--accent) 76%, var(--text-primary));
}

.preview-frame .artifact-launch-card .artifact-inline-body {
  gap: 3px;
}

.preview-frame .artifact-launch-card .artifact-inline-body strong {
  font-size: var(--preview-title-size);
  font-weight: 640;
  letter-spacing: 0;
}

/* The type marker and the open control both read at body weight, in every
   style. They are a noun and a verb beside a file name, and bolding them made
   the two smallest strings on the card the loudest. Set here and cleared from
   the per-style branches below, so a new style inherits the same answer. */
.preview-frame .artifact-launch-kind {
  color: var(--text-muted);
  font-size: var(--preview-meta-size);
  font-weight: 400;
  line-height: 1.25;
}

.preview-frame .generated-image-inline {
  display: block;
  width: 270px;
  max-width: 100%;
  border: 0;
  background: transparent;
  padding: 4px 0;
  box-shadow: none;
}

.preview-frame .generated-image-inline-button {
  display: block;
  width: 100%;
  border: 0;
  background: transparent;
  padding: 0;
  color: inherit;
  cursor: pointer;
}

