/* ── Apple "Liquid Glass" preview — composer block only (native, for eval) ──
   Frosted translucent panel + large continuous radius + soft floating shadow +
   system-blue send. Apple-INSPIRED aesthetic, not a copy of Apple assets. */
.preview-frame[data-style-preset="native"] .composer-shell {
  border-radius: 20px;
  padding: 8px;
  /* Colors follow the active theme so it adapts: --border-subtle ≈ #F0F0F0 and
     --surface-panel ≈ #FFF on light themes, and their dark equivalents on dark. */
  border: 1px solid var(--border-subtle);
  background: var(--surface-panel);
  box-shadow: 0 3px 14px color-mix(in srgb, var(--text-primary) 5%, transparent);
}

.preview-frame[data-style-preset="native"] .composer-shell:has(.ui-textarea:focus) {
  border-color: var(--surface-disabled);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--surface-panel) 90%, transparent),
    0 3px 14px color-mix(in srgb, var(--text-primary) 5%, transparent);
}

/* ── Particle style (id: illustrated) ──────────────────────────────────────
   Codex-clean base (light, airy, flat, monochrome) with a restrained accent
   drawn from the orb. Scoped + visual-only — no logic/content, no other styles
   touched. The thinking indicator is the particle orb (wired separately). */
.preview-frame[data-style-preset="illustrated"] {
  /* Its scale is `--minimal-radius-*`; 8px is the top tier, and this style
     already sized `.image-output-preview` from it by hand. */
  --preview-media-radius: var(--minimal-radius-xl);
  /* Sizes struck for the same reason as 原生风's above: they are the base now. */
  --preview-copy-line: 1.62;
  --particle-accent: var(--accent);
  --particle-accent-2: var(--accent-hover);
  --particle-accent-deep: var(--accent-hover);
  --particle-ink: var(--text-primary);
  --particle-muted: var(--text-muted);
  --particle-soft: var(--text-secondary);
  --particle-line: color-mix(in srgb, var(--particle-accent) 12%, var(--border-subtle));
  --particle-divider-line: color-mix(in srgb, var(--particle-line) 42%, transparent);
  --particle-fill: color-mix(in srgb, var(--particle-accent) 8%, var(--surface-panel));
  --particle-selection-bg: var(--accent-soft);
  --particle-selection-text: var(--accent);
  --particle-user-bubble-bg: var(--particle-selection-bg);
  --particle-user-bubble-text: var(--text-primary);
  --particle-sidebar-bg: color-mix(in srgb, var(--surface-canvas) 60%, var(--surface-panel));
  --preview-soft-fill: var(--particle-fill);
  --preview-soft-line: var(--particle-line);
  /* Minimal radius scale: small controls stay crisp; larger containers get proportionally larger corners. */
  --minimal-radius-xs: 2px;
  --minimal-radius-sm: 3px;
  --minimal-radius-md: 4px;
  --minimal-radius-lg: 6px;
  --minimal-radius-xl: 8px;
  --minimal-radius-popover: 10px;
  --minimal-radius-input: 12px;
  --radius-sm: var(--minimal-radius-sm);
  --radius-md: var(--minimal-radius-md);
  --radius-lg: var(--minimal-radius-lg);
  --radius: var(--minimal-radius-md);
  --radius-full: var(--minimal-radius-md);
  background: var(--surface-panel);
}

