.command-backdrop {
  position: fixed;
  inset: 0;
  /* A modal's backdrop has to cover the shell chrome, which floats over the
     canvas now — at its old 20 the rail card sat on top of the dimming. */
  z-index: var(--z-overlay);
  display: grid;
  place-items: start center;
  background: rgba(15, 18, 24, 0.28);
  padding-top: 14vh;
}

.command-menu {
  width: min(560px, calc(100vw - 32px));
  overflow: hidden;
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  background: var(--surface-panel);
  box-shadow: var(--shadow-lg);
}

.command-input-row {
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 10px 12px;
}

.command-input-row input {
  width: 100%;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--text-primary);
}

[cmdk-list] {
  max-height: 320px;
  overflow: auto;
  padding: 8px;
}

[cmdk-group-heading] {
  padding: 7px 8px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

[cmdk-item] {
  display: grid;
  gap: 3px;
  border-radius: var(--radius);
  padding: 9px 10px;
  color: var(--text-secondary);
}

[cmdk-item][data-selected="true"] {
  background: var(--surface-inset);
  color: var(--text-primary);
}

[cmdk-item] small {
  color: var(--text-muted);
}

@keyframes thinking-dot {
  0%,
  70%,
  100% {
    opacity: 0.3;
    transform: translateY(0);
  }
  35% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

@keyframes spinner-rotate {
  to {
    transform: rotate(360deg);
  }
}

@keyframes reasoning-infinity-trim {
  0% {
    stroke-dashoffset: 0;
    stroke-dasharray: 0 78;
  }
  17% {
    stroke-dasharray: 70 78;
  }
  44% {
    stroke-dasharray: 70 78;
  }
  74% {
    stroke-dashoffset: -312;
    stroke-dasharray: 0 78;
  }
  100% {
    stroke-dashoffset: -312;
    stroke-dasharray: 0 78;
  }
}

@keyframes terminal-cursor-blink {
  0%,
  48% {
    opacity: 1;
  }
  49%,
  100% {
    opacity: 0.2;
  }
}

@keyframes reasoning-minimal-sweep {
  0%,
  100% {
    transform: scaleX(0.45);
    opacity: 0.38;
  }
  45% {
    transform: scaleX(1);
    opacity: 1;
  }
}

@keyframes reasoning-text-shimmer {
  0% {
    background-position: 160% 0;
  }
  100% {
    background-position: -80% 0;
  }
}

@keyframes tool-title-shimmer {
  0% {
    background-position: 160% 0;
  }
  100% {
    background-position: -80% 0;
  }
}

@keyframes reasoning-bar-wave {
  0%,
  100% {
    transform: scaleY(0.38);
    opacity: 0.45;
  }
  45% {
    transform: scaleY(1);
    opacity: 1;
  }
}

@keyframes tool-progress-preview {
  0%,
  100% {
    transform: translateX(-28px);
    opacity: 0.46;
  }
  50% {
    transform: translateX(22px);
    opacity: 1;
  }
}

@keyframes tool-progress-running {
  0%,
  100% {
    transform: translateX(-16%);
  }
  50% {
    transform: translateX(12%);
  }
}

/* Refined media-generation component language ----------------------------- */
.pv-media-frame,
.pv-media-audio-card,
.pv-media-video-frame {
  isolation: isolate;
  width: 54px;
  height: 38px;
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-subtle));
  border-radius: 11px;
  background:
    radial-gradient(circle at 22% 18%, color-mix(in srgb, var(--accent) 30%, transparent), transparent 34%),
    linear-gradient(145deg, color-mix(in srgb, var(--surface-panel) 92%, transparent), color-mix(in srgb, var(--accent) 9%, var(--surface-inset)));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--preview-shimmer-light) 50%, transparent),
    0 10px 22px color-mix(in srgb, var(--shadow-color) 10%, transparent);
}

.pv-media-frame::before,
.pv-media-audio-card::before,
.pv-media-video-frame::before {
  content: "";
  position: absolute;
  inset: -30% -20% auto 18%;
  z-index: 0;
  height: 72%;
  border-radius: 999px;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 34%, transparent), transparent 68%);
  filter: blur(7px);
  opacity: 0.8;
  animation: media-soft-orbit 2.6s var(--ease-in-out) infinite;
}

.pv-media-frame::after,
.pv-media-audio-card::after,
.pv-media-video-frame::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 3;
  background: linear-gradient(110deg, transparent 15%, color-mix(in srgb, var(--preview-shimmer-light) 64%, transparent) 48%, transparent 78%);
  transform: translateX(-120%);
  animation: media-skeleton-sweep 1.85s var(--ease-in-out) infinite;
}

.pv-media-grid,
.pv-media-layers,
.pv-media-caption,
.pv-media-audio-cover,
.pv-media-wave,
.pv-media-play,
.pv-media-video-strip {
  z-index: 2;
}

.pv-media-frame .pv-media-grid {
  inset: 6px 6px 10px;
  grid-template-columns: 1.25fr 0.85fr;
  gap: 3px;
}

.pv-media-grid i,
.pv-media-layers i,
.pv-media-video-strip i {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--preview-shimmer-light) 18%, transparent), transparent 48%),
    color-mix(in srgb, var(--accent) 20%, var(--surface-panel));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 14%, transparent);
}

.pv-media-frame .pv-media-grid i:first-child {
  grid-row: span 2;
  background:
    radial-gradient(circle at 36% 30%, color-mix(in srgb, var(--preview-shimmer-light) 34%, transparent), transparent 30%),
    color-mix(in srgb, var(--accent) 30%, var(--surface-panel));
}

.pv-media-frame[data-media-style="blur"] .pv-media-grid {
  grid-template-columns: repeat(2, 1fr);
}

.pv-media-frame[data-media-style="blur"] .pv-media-grid i {
  border-radius: 999px;
  filter: blur(1.8px);
  transform: scale(1.1);
  opacity: 0.9;
}

.pv-media-frame[data-media-style="palette"] .pv-media-grid i:nth-child(1) {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 56%, var(--surface-panel)), color-mix(in srgb, var(--accent-hover) 24%, var(--surface-panel)));
}

.pv-media-frame[data-media-style="palette"] .pv-media-grid i:nth-child(2) {
  background: color-mix(in srgb, var(--accent-hover) 40%, var(--surface-panel));
}

.pv-media-frame[data-media-style="palette"] .pv-media-grid i:nth-child(3) {
  background: color-mix(in srgb, var(--accent) 18%, var(--preview-soft-fill));
}

.pv-media-frame[data-media-style="palette"] .pv-media-grid i:nth-child(4) {
  background: color-mix(in srgb, var(--text-primary) 10%, var(--surface-panel));
}

.pv-media-frame[data-media-style="layers"] .pv-media-layers {
  inset: 7px 10px 9px 8px;
}

.pv-media-frame[data-media-style="layers"] .pv-media-layers i {
  border-radius: 7px;
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--preview-shimmer-light) 22%, transparent), transparent 54%),
    color-mix(in srgb, var(--accent) 20%, var(--surface-panel));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 20%, transparent),
    0 5px 10px color-mix(in srgb, var(--shadow-color) 10%, transparent);
}

.pv-media-audio-card {
  grid-template-columns: 15px 1fr;
  gap: 6px;
  padding: 6px;
}

.pv-media-audio-cover {
  width: 15px;
  height: 15px;
  border-radius: 6px;
  background:
    radial-gradient(circle at 38% 34%, color-mix(in srgb, var(--preview-shimmer-light) 48%, transparent), transparent 24%),
    color-mix(in srgb, var(--accent) 44%, var(--surface-panel));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 22%, transparent);
}

.pv-media-wave {
  align-items: end;
  height: 20px;
}

.pv-media-wave i {
  width: 2px;
  background: linear-gradient(to top, color-mix(in srgb, var(--accent) 34%, var(--surface-panel)), color-mix(in srgb, var(--accent) 76%, var(--surface-panel)));
}

.pv-media-audio-card[data-media-style="player"] {
  grid-template-columns: 17px 1fr;
}

.pv-media-audio-card[data-media-style="player"] .pv-media-audio-cover {
  border-radius: 50%;
}

.pv-media-audio-card[data-media-style="player"] .pv-media-wave {
  position: relative;
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 16%, transparent);
}

.pv-media-audio-card[data-media-style="player"] .pv-media-wave::before {
  content: "";
  display: block;
  width: 48%;
  height: 100%;
  border-radius: inherit;
  background: color-mix(in srgb, var(--accent) 62%, var(--surface-panel));
  animation: media-progress-load 1.9s var(--ease-in-out) infinite;
}

.pv-media-audio-card[data-media-style="spectrum"] .pv-media-wave {
  gap: 1px;
}

.pv-media-audio-card[data-media-style="spectrum"] .pv-media-wave i {
  width: 3px;
  border-radius: 3px 3px 1px 1px;
}

.pv-media-audio-card[data-media-style="transcript"] .pv-media-wave {
  align-content: center;
}

.pv-media-audio-card[data-media-style="transcript"] .pv-media-wave i {
  width: 14px;
  height: 3px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 24%, transparent);
  animation: media-caption-pulse 1.6s var(--ease-in-out) infinite;
}

.pv-media-video-frame {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--text-primary) 10%, transparent) 0 12%, transparent 12% 88%, color-mix(in srgb, var(--text-primary) 10%, transparent) 88% 100%),
    radial-gradient(circle at 70% 20%, color-mix(in srgb, var(--accent) 32%, transparent), transparent 38%),
    color-mix(in srgb, var(--surface-panel) 88%, var(--preview-soft-fill));
}

.pv-media-play {
  width: 15px;
  height: 15px;
  background:
    linear-gradient(90deg, transparent 42%, color-mix(in srgb, var(--accent) 70%, var(--text-primary)) 42% 72%, transparent 72%),
    color-mix(in srgb, var(--surface-panel) 90%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--preview-shimmer-light) 45%, transparent);
}

.pv-media-video-strip {
  right: 7px;
  bottom: 6px;
  left: 7px;
  gap: 3px;
  height: 6px;
}

.pv-media-video-frame[data-media-style="cinema"] {
  height: 32px;
  border-radius: 7px;
  box-shadow:
    inset 0 6px 0 color-mix(in srgb, var(--text-primary) 10%, transparent),
    inset 0 -6px 0 color-mix(in srgb, var(--text-primary) 10%, transparent),
    0 10px 22px color-mix(in srgb, var(--shadow-color) 10%, transparent);
}

.pv-media-video-frame[data-media-style="timeline"] .pv-media-video-strip {
  height: 5px;
  padding: 1px;
}

.pv-media-video-frame[data-media-style="timeline"] .pv-media-video-strip i:first-child {
  background: color-mix(in srgb, var(--accent) 72%, var(--surface-panel));
}

.pv-media-video-frame[data-media-style="frames"] .pv-media-video-strip {
  inset: 7px;
  gap: 4px;
}

.preview-frame .media-generation-inline {
  align-items: flex-start;
}

.preview-frame .media-generation-preview {
  isolation: isolate;
  width: 148px;
  height: 90px;
  border-color: color-mix(in srgb, var(--accent) 24%, var(--preview-soft-line));
  border-radius: 20px;
  background:
    radial-gradient(circle at 20% 18%, color-mix(in srgb, var(--accent) 30%, transparent), transparent 34%),
    radial-gradient(circle at 78% 84%, color-mix(in srgb, var(--accent-hover) 18%, transparent), transparent 42%),
    linear-gradient(145deg, color-mix(in srgb, var(--surface-panel) 88%, transparent), color-mix(in srgb, var(--preview-soft-fill) 86%, var(--surface-panel)));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--preview-shimmer-light) 54%, transparent),
    0 16px 36px color-mix(in srgb, var(--shadow-color) 12%, transparent);
  color: color-mix(in srgb, var(--accent) 78%, var(--text-primary));
}

.preview-frame .media-generation-preview::before,
.preview-frame .generated-image-skeleton::before,
.preview-frame .video-output-stage::before,
.preview-frame .media-output-cover::before {
  content: "";
  position: absolute;
  inset: -34% -20% auto 24%;
  z-index: 0;
  height: 76%;
  border-radius: 999px;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 30%, transparent), transparent 66%);
  filter: blur(13px);
  opacity: 0.86;
  animation: media-soft-orbit 3s var(--ease-in-out) infinite;
}

.preview-frame .media-generation-preview > *,
.preview-frame .generated-image-skeleton > *,
.preview-frame .video-output-stage > *,
.preview-frame .media-output-cover > * {
  position: relative;
  z-index: 1;
}

.preview-frame .media-generation-preview::after,
.preview-frame .generated-image-skeleton::after,
.preview-frame .video-output-stage::after {
  z-index: 4;
  background: linear-gradient(
    112deg,
    transparent 12%,
    color-mix(in srgb, var(--preview-shimmer-light) 12%, transparent) 32%,
    color-mix(in srgb, var(--preview-shimmer-light) 72%, transparent) 48%,
    color-mix(in srgb, var(--preview-shimmer-light) 14%, transparent) 63%,
    transparent 84%
  );
  animation-duration: 2.05s;
}

.preview-frame .media-generation-preview[data-media-kind="image"] {
  place-items: center;
}

.preview-frame .media-generation-image-grid {
  width: 108px;
  height: 62px;
  gap: 7px;
  grid-template-columns: 1.35fr 0.9fr;
}

.preview-frame .media-generation-image-grid span,
.preview-frame .generated-image-grid span {
  border-radius: 14px;
  background:
    radial-gradient(circle at 34% 26%, color-mix(in srgb, var(--preview-shimmer-light) 34%, transparent), transparent 28%),
    linear-gradient(135deg, color-mix(in srgb, var(--accent) 28%, var(--surface-panel)), color-mix(in srgb, var(--accent) 12%, var(--preview-soft-fill)));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 18%, transparent),
    0 8px 16px color-mix(in srgb, var(--shadow-color) 8%, transparent);
  animation: media-tile-breathe 2.4s var(--ease-in-out) infinite;
}

.preview-frame .media-generation-image-grid span:first-child,
.preview-frame .generated-image-grid span:first-child {
  grid-row: span 2;
}

.preview-frame .media-generation-preview[data-media-style="blur"],
.preview-frame .generated-image-skeleton[data-media-style="blur"] {
  background:
    radial-gradient(circle at 34% 34%, color-mix(in srgb, var(--accent) 34%, transparent), transparent 24%),
    radial-gradient(circle at 70% 64%, color-mix(in srgb, var(--accent-hover) 24%, transparent), transparent 26%),
    radial-gradient(circle at 24% 78%, color-mix(in srgb, var(--text-primary) 9%, transparent), transparent 30%),
    color-mix(in srgb, var(--preview-soft-fill) 82%, var(--surface-panel));
}

.preview-frame .media-generation-preview[data-media-style="blur"] .media-generation-image-grid,
.preview-frame .generated-image-skeleton[data-media-style="blur"] .generated-image-grid {
  filter: saturate(1.12);
}

.preview-frame .media-generation-preview[data-media-style="blur"] .media-generation-image-grid span,
.preview-frame .generated-image-skeleton[data-media-style="blur"] .generated-image-grid span {
  border-radius: 999px;
  filter: blur(4px);
  transform: scale(1.08);
  opacity: 0.86;
}

.preview-frame .media-generation-preview[data-media-style="palette"] .media-generation-image-grid span:nth-child(1),
.preview-frame .generated-image-skeleton[data-media-style="palette"] .generated-image-grid span:nth-child(1) {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 58%, var(--surface-panel)), color-mix(in srgb, var(--accent-hover) 28%, var(--surface-panel)));
}

.preview-frame .media-generation-preview[data-media-style="palette"] .media-generation-image-grid span:nth-child(2),
.preview-frame .generated-image-skeleton[data-media-style="palette"] .generated-image-grid span:nth-child(2) {
  background: color-mix(in srgb, var(--accent-hover) 38%, var(--surface-panel));
}

.preview-frame .media-generation-preview[data-media-style="palette"] .media-generation-image-grid span:nth-child(3),
.preview-frame .generated-image-skeleton[data-media-style="palette"] .generated-image-grid span:nth-child(3) {
  background: color-mix(in srgb, var(--accent) 18%, var(--preview-soft-fill));
}

.preview-frame .media-generation-preview[data-media-style="palette"] .media-generation-image-grid span:nth-child(4),
.preview-frame .generated-image-skeleton[data-media-style="palette"] .generated-image-grid span:nth-child(4) {
  background: color-mix(in srgb, var(--text-primary) 10%, var(--surface-panel));
}

.preview-frame .media-generation-preview[data-media-style="layers"] .media-generation-layer-stack {
  width: 96px;
  height: 58px;
}

.preview-frame .media-generation-layer-stack i,
.preview-frame .generated-image-layers span {
  border-radius: 18px;
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--preview-shimmer-light) 26%, transparent), transparent 58%),
    color-mix(in srgb, var(--accent) 18%, var(--surface-panel));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 20%, transparent),
    0 14px 28px color-mix(in srgb, var(--shadow-color) 12%, transparent);
  animation: media-layer-float 2.7s var(--ease-in-out) infinite;
}

.preview-frame .media-generation-layer-stack i:nth-child(2),
.preview-frame .generated-image-layers span:nth-child(2) {
  animation-delay: 120ms;
}

.preview-frame .media-generation-layer-stack i:nth-child(3),
.preview-frame .generated-image-layers span:nth-child(3) {
  animation-delay: 240ms;
}

.preview-frame .media-generation-preview[data-media-kind="audio"] {
  justify-content: end;
  padding: 14px;
}

.preview-frame .media-generation-audio-icon {
  top: 13px;
  left: 13px;
  width: 36px;
  height: 36px;
  background:
    radial-gradient(circle at 38% 34%, color-mix(in srgb, var(--preview-shimmer-light) 42%, transparent), transparent 24%),
    color-mix(in srgb, var(--accent) 20%, var(--surface-panel));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 20%, transparent);
}

.preview-frame .mini-waveform {
  align-items: end;
  width: 90px;
  height: 56px;
  gap: 4px;
  margin-left: 30px;
}

.preview-frame .mini-waveform span,
.preview-frame .waveform-skeleton span {
  background: linear-gradient(to top, color-mix(in srgb, var(--accent) 42%, var(--surface-panel)), color-mix(in srgb, var(--accent) 78%, var(--surface-panel)));
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent) 18%, transparent);
}

.preview-frame .media-generation-preview[data-media-style="player"] .mini-waveform,
.preview-frame .audio-output-preview[data-media-style="player"] .waveform-skeleton {
  position: relative;
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 16%, transparent);
}

.preview-frame .media-generation-preview[data-media-style="player"] .mini-waveform::before,
.preview-frame .audio-output-preview[data-media-style="player"] .waveform-skeleton::before {
  content: "";
  display: block;
  width: 44%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 72%, var(--surface-panel)), color-mix(in srgb, var(--accent-hover) 44%, var(--surface-panel)));
  animation: media-progress-load 2s var(--ease-in-out) infinite;
}

.preview-frame .media-generation-preview[data-media-style="spectrum"] .mini-waveform span,
.preview-frame .audio-output-preview[data-media-style="spectrum"] .waveform-skeleton span {
  width: 7px;
  border-radius: 4px 4px 1px 1px;
  background: linear-gradient(to top, color-mix(in srgb, var(--accent) 32%, var(--surface-panel)), color-mix(in srgb, var(--accent) 82%, var(--preview-shimmer-light)));
}

.preview-frame .media-generation-preview[data-media-style="transcript"] .mini-waveform {
  width: 46px;
  opacity: 0.7;
}

.preview-frame .media-generation-preview[data-media-style="transcript"] .media-generation-transcript {
  right: 12px;
  bottom: 14px;
  left: 58px;
  gap: 5px;
}

.preview-frame .media-generation-transcript i,
.preview-frame .audio-transcript-skeleton span,
.preview-frame .generated-image-caption span {
  background: color-mix(in srgb, var(--text-muted) 20%, transparent);
  animation: media-caption-pulse 1.9s var(--ease-in-out) infinite;
}

.preview-frame .media-generation-preview[data-media-kind="video"] {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--text-primary) 9%, transparent) 0 13%, transparent 13% 87%, color-mix(in srgb, var(--text-primary) 9%, transparent) 87% 100%),
    radial-gradient(circle at 68% 24%, color-mix(in srgb, var(--accent) 30%, transparent), transparent 34%),
    color-mix(in srgb, var(--surface-panel) 86%, var(--preview-soft-fill));
}

.preview-frame .media-generation-play {
  top: 14px;
  left: 14px;
  width: 36px;
  height: 36px;
  color: color-mix(in srgb, var(--accent) 82%, var(--text-primary));
  background: color-mix(in srgb, var(--surface-panel) 88%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--preview-shimmer-light) 52%, transparent),
    0 12px 22px color-mix(in srgb, var(--shadow-color) 14%, transparent);
}

.preview-frame .media-generation-video-strip {
  right: 14px;
  bottom: 12px;
  left: 14px;
  gap: 7px;
  height: 16px;
}

.preview-frame .media-generation-video-strip span,
.preview-frame .video-output-scenes span {
  border-radius: 7px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--preview-shimmer-light) 22%, transparent), transparent 50%),
    color-mix(in srgb, var(--accent) 18%, var(--surface-panel));
  animation: media-frame-pulse 2.2s var(--ease-in-out) infinite;
  animation-delay: calc(var(--scene-index, 0) * 70ms);
}

.preview-frame .media-generation-preview[data-media-style="cinema"],
.preview-frame .video-output-preview[data-media-style="cinema"] .video-output-stage {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--text-primary) 16%, transparent) 0 14%, transparent 14% 86%, color-mix(in srgb, var(--text-primary) 16%, transparent) 86% 100%),
    radial-gradient(circle at 50% 46%, color-mix(in srgb, var(--accent) 36%, transparent), transparent 38%),
    color-mix(in srgb, var(--surface-panel) 88%, var(--preview-soft-fill));
}

.preview-frame .media-generation-preview[data-media-style="timeline"] .media-generation-video-strip,
.preview-frame .video-output-preview[data-media-style="timeline"] .video-output-scenes {
  height: 8px;
  padding: 1px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 16%, transparent);
}

.preview-frame .media-generation-preview[data-media-style="timeline"] .media-generation-video-strip span:first-child,
.preview-frame .video-output-preview[data-media-style="timeline"] .video-output-scenes span:first-child {
  background: color-mix(in srgb, var(--accent) 78%, var(--surface-panel));
}

.preview-frame .media-generation-preview[data-media-style="frames"] .media-generation-video-strip,
.preview-frame .video-output-preview[data-media-style="frames"] .video-output-scenes {
  top: 14px;
  bottom: 14px;
  grid-template-columns: repeat(2, 1fr);
  height: auto;
}

.preview-frame .image-output-preview,
.preview-frame .audio-output-preview,
.preview-frame .video-output-preview {
  border-color: color-mix(in srgb, var(--accent) 16%, var(--preview-soft-line));
  background:
    radial-gradient(circle at 12% 8%, color-mix(in srgb, var(--accent) 13%, transparent), transparent 30%),
    color-mix(in srgb, var(--preview-soft-fill) 92%, var(--surface-panel));
}

.preview-frame .image-output-preview {
  align-items: start;
  padding: 14px;
}

.preview-frame .generated-image-skeleton {
  isolation: isolate;
  width: min(430px, 100%);
  min-height: 274px;
  padding: 18px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--preview-soft-line));
  border-radius: 22px;
  background:
    radial-gradient(circle at 26% 20%, color-mix(in srgb, var(--accent) 28%, transparent), transparent 32%),
    radial-gradient(circle at 84% 88%, color-mix(in srgb, var(--accent-hover) 16%, transparent), transparent 36%),
    color-mix(in srgb, var(--surface-panel) 86%, var(--preview-soft-fill));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--preview-shimmer-light) 54%, transparent),
    0 18px 40px color-mix(in srgb, var(--shadow-color) 12%, transparent);
}

.preview-frame .generated-image-grid {
  min-height: 194px;
  grid-template-columns: 1.45fr 0.9fr;
  gap: 12px;
}

.preview-frame .generated-image-skeleton[data-media-style="layers"] .generated-image-layers {
  min-height: 194px;
}

.preview-frame .generated-image-layers span:nth-child(2) {
  transform: translate(22px, 18px);
}

.preview-frame .generated-image-layers span:nth-child(3) {
  transform: translate(44px, 36px);
}

.preview-frame .audio-output-preview {
  align-items: start;
  min-height: 220px;
  padding: 18px;
}

.preview-frame .media-output-card {
  position: relative;
  isolation: isolate;
  gap: 18px;
  align-items: center;
  padding: 18px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--preview-soft-line));
  border-radius: 22px;
  background:
    radial-gradient(circle at 16% 18%, color-mix(in srgb, var(--accent) 18%, transparent), transparent 30%),
    color-mix(in srgb, var(--surface-panel) 88%, var(--preview-soft-fill));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--preview-shimmer-light) 50%, transparent),
    0 16px 34px color-mix(in srgb, var(--shadow-color) 10%, transparent);
}

.preview-frame .media-output-cover {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background:
    radial-gradient(circle at 36% 32%, color-mix(in srgb, var(--preview-shimmer-light) 42%, transparent), transparent 24%),
    color-mix(in srgb, var(--accent) 18%, var(--surface-panel));
}

.preview-frame .media-output-main {
  gap: 13px;
}

.preview-frame .media-output-meta strong {
  font-size: var(--preview-title-size);
}

.preview-frame .waveform-skeleton {
  align-items: end;
  gap: 6px;
  height: 62px;
}

.preview-frame .media-output-controls div {
  background: color-mix(in srgb, var(--text-muted) 15%, transparent);
}

.preview-frame .audio-output-preview[data-media-style="player"] .media-output-card {
  grid-template-columns: 64px minmax(0, 1fr);
}

.preview-frame .audio-output-preview[data-media-style="player"] .media-output-cover {
  width: 64px;
  height: 64px;
  box-shadow:
    inset 0 0 0 7px color-mix(in srgb, var(--surface-panel) 74%, transparent),
    inset 0 0 0 8px color-mix(in srgb, var(--accent) 24%, transparent);
}

.preview-frame .audio-output-preview[data-media-style="transcript"] .media-output-card {
  grid-template-columns: 72px minmax(0, 1fr);
}

.preview-frame .video-output-preview {
  align-items: start;
  min-height: 260px;
  padding: 14px;
}

.preview-frame .video-output-stage {
  isolation: isolate;
  min-height: 250px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--preview-soft-line));
  border-radius: 24px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--text-primary) 10%, transparent) 0 10%, transparent 10% 90%, color-mix(in srgb, var(--text-primary) 10%, transparent) 90% 100%),
    radial-gradient(circle at 66% 25%, color-mix(in srgb, var(--accent) 34%, transparent), transparent 34%),
    radial-gradient(circle at 24% 82%, color-mix(in srgb, var(--accent-hover) 15%, transparent), transparent 40%),
    color-mix(in srgb, var(--surface-panel) 88%, var(--preview-soft-fill));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--preview-shimmer-light) 50%, transparent),
    0 18px 42px color-mix(in srgb, var(--shadow-color) 13%, transparent);
}

.preview-frame .video-output-play {
  width: 68px;
  height: 68px;
  color: color-mix(in srgb, var(--accent) 82%, var(--text-primary));
  background: color-mix(in srgb, var(--surface-panel) 86%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--preview-shimmer-light) 54%, transparent),
    0 18px 36px color-mix(in srgb, var(--shadow-color) 16%, transparent);
}

.preview-frame .video-output-scenes {
  right: 20px;
  bottom: 20px;
  left: 20px;
  gap: 10px;
  height: 24px;
}

.preview-frame .video-output-preview[data-media-style="frames"] .video-output-scenes {
  inset: 20px;
  gap: 12px;
}

.preview-frame[data-appearance="dark"] :is(
  .image-output-preview,
  .audio-output-preview,
  .video-output-preview,
  .media-generation-preview,
  .generated-image-skeleton,
  .media-output-card,
  .video-output-stage
) {
  border-color: transparent;
  background:
    radial-gradient(circle at 16% 16%, rgb(168 176 187 / 0.12), transparent 30%),
    radial-gradient(circle at 82% 86%, rgb(112 121 134 / 0.11), transparent 38%),
    linear-gradient(145deg, color-mix(in srgb, var(--surface-canvas) 94%, white), color-mix(in srgb, var(--accent) 4%, var(--surface-canvas)));
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.05),
    0 18px 42px rgb(0 0 0 / 0.26);
  color: #a8b0bb;
}

.preview-frame[data-appearance="dark"] :is(
  .media-generation-preview[data-media-style="blur"],
  .generated-image-skeleton[data-media-style="blur"],
  .media-generation-preview[data-media-style="palette"],
  .generated-image-skeleton[data-media-style="palette"],
  .media-generation-preview[data-media-style="layers"],
  .generated-image-skeleton[data-media-style="layers"]
) {
  background:
    radial-gradient(circle at 34% 34%, rgb(168 176 187 / 0.13), transparent 24%),
    radial-gradient(circle at 70% 64%, rgb(112 121 134 / 0.13), transparent 28%),
    linear-gradient(145deg, color-mix(in srgb, var(--surface-canvas) 94%, white), color-mix(in srgb, var(--accent) 4%, var(--surface-canvas)));
}

.preview-frame[data-appearance="dark"] :is(
  .media-generation-preview[data-media-kind="video"],
  .media-generation-preview[data-media-style="cinema"],
  .video-output-preview[data-media-style="cinema"] .video-output-stage
) {
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.07) 0 13%, transparent 13% 87%, rgb(255 255 255 / 0.07) 87% 100%),
    radial-gradient(circle at 68% 24%, rgb(168 176 187 / 0.12), transparent 34%),
    linear-gradient(145deg, color-mix(in srgb, var(--surface-canvas) 94%, white), color-mix(in srgb, var(--accent) 4%, var(--surface-canvas)));
}

.preview-frame[data-appearance="dark"] .media-generation-preview::before,
.preview-frame[data-appearance="dark"] .generated-image-skeleton::before,
.preview-frame[data-appearance="dark"] .video-output-stage::before,
.preview-frame[data-appearance="dark"] .media-output-cover::before {
  background: radial-gradient(circle, rgb(168 176 187 / 0.16), transparent 66%);
  opacity: 0.58;
}

.preview-frame[data-appearance="dark"] .media-generation-preview::after,
.preview-frame[data-appearance="dark"] .generated-image-skeleton::after,
.preview-frame[data-appearance="dark"] .video-output-stage::after {
  background: linear-gradient(
    112deg,
    transparent 12%,
    rgb(255 255 255 / 0.04) 32%,
    rgb(255 255 255 / 0.2) 48%,
    rgb(255 255 255 / 0.05) 63%,
    transparent 84%
  );
}

.preview-frame[data-appearance="dark"] :is(
  .media-generation-image-grid span,
  .generated-image-grid span,
  .media-generation-layer-stack i,
  .generated-image-layers span,
  .media-generation-video-strip span,
  .video-output-scenes span
) {
  background:
    linear-gradient(135deg, rgb(255 255 255 / 0.08), transparent 50%),
    rgb(104 113 126 / 0.3);
  box-shadow: 0 12px 24px rgb(0 0 0 / 0.16);
}

.preview-frame[data-appearance="dark"] :is(
  .media-generation-preview[data-media-style="palette"] .media-generation-image-grid span,
  .generated-image-skeleton[data-media-style="palette"] .generated-image-grid span
) {
  background:
    linear-gradient(135deg, rgb(185 192 201 / 0.28), rgb(104 113 126 / 0.2)),
    rgb(36 41 49);
}

.preview-frame[data-appearance="dark"] :is(
  .media-generation-audio-icon,
  .media-output-cover
) {
  background:
    radial-gradient(circle at 38% 34%, rgb(255 255 255 / 0.12), transparent 24%),
    rgb(104 113 126 / 0.32);
}

.preview-frame[data-appearance="dark"] :is(
  .mini-waveform span,
  .waveform-skeleton span
) {
  background: linear-gradient(to top, rgb(122 131 145 / 0.62), rgb(190 197 206 / 0.82));
  box-shadow: 0 0 12px rgb(168 176 187 / 0.12);
}

.preview-frame[data-appearance="dark"] :is(
  .media-generation-preview[data-media-style="player"] .mini-waveform,
  .audio-output-preview[data-media-style="player"] .waveform-skeleton,
  .media-generation-preview[data-media-style="timeline"] .media-generation-video-strip,
  .video-output-preview[data-media-style="timeline"] .video-output-scenes,
  .media-output-controls div
) {
  background: rgb(168 176 187 / 0.12);
}

.preview-frame[data-appearance="dark"] .media-generation-preview[data-media-style="player"] .mini-waveform::before,
.preview-frame[data-appearance="dark"] .audio-output-preview[data-media-style="player"] .waveform-skeleton::before {
  background: linear-gradient(90deg, rgb(185 192 201 / 0.86), rgb(122 131 145 / 0.72));
}

.preview-frame[data-appearance="dark"] :is(
  .media-generation-play,
  .video-output-play
) {
  color: #d5dbe3;
  background: rgb(32 36 42 / 0.92);
  box-shadow: 0 18px 36px rgb(0 0 0 / 0.26);
}

@keyframes media-soft-orbit {
  0%,
  100% {
    transform: translate3d(-4%, 0, 0) scale(0.94);
    opacity: 0.58;
  }
  50% {
    transform: translate3d(8%, 10%, 0) scale(1.08);
    opacity: 0.95;
  }
}

@keyframes media-tile-breathe {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.82;
  }
  50% {
    transform: translateY(-2px);
    opacity: 1;
  }
}

@keyframes media-layer-float {
  0%,
  100% {
    filter: saturate(1);
  }
  50% {
    filter: saturate(1.18);
  }
}

@keyframes media-frame-pulse {
  0%,
  100% {
    opacity: 0.72;
  }
  50% {
    opacity: 1;
  }
}

@keyframes media-caption-pulse {
  0%,
  100% {
    opacity: 0.54;
  }
  50% {
    opacity: 0.86;
  }
}

@keyframes media-skeleton-sweep {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(120%);
  }
}

@keyframes media-wave-bounce {
  0%,
  100% {
    transform: scaleY(0.58);
    opacity: 0.62;
  }
  50% {
    transform: scaleY(1);
    opacity: 1;
  }
}

@keyframes media-progress-load {
  0%,
  100% {
    transform: translateX(0%);
  }
  50% {
    transform: translateX(178%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .pv-media-frame::before,
  .pv-media-audio-card::before,
  .pv-media-video-frame::before,
  .pv-media-frame::after,
  .pv-media-audio-card::after,
  .pv-media-video-frame::after,
  .preview-frame .media-generation-preview::before,
  .preview-frame .media-generation-preview::after,
  .preview-frame .generated-image-skeleton::before,
  .preview-frame .generated-image-skeleton::after,
  .preview-frame .video-output-stage::before,
  .preview-frame .video-output-stage::after,
  .preview-frame .media-output-cover::before,
  .preview-frame .media-generation-image-grid span,
  .preview-frame .generated-image-grid span,
  .preview-frame .media-generation-layer-stack i,
  .preview-frame .generated-image-layers span,
  .preview-frame .media-generation-video-strip span,
  .preview-frame .video-output-scenes span,
  .preview-frame .media-generation-transcript i,
  .preview-frame .audio-transcript-skeleton span,
  .preview-frame .generated-image-caption span,
  .pv-media-audio-card[data-media-style="player"] .pv-media-wave::before,
  .preview-frame .media-generation-preview[data-media-style="player"] .mini-waveform::before,
  .preview-frame .audio-output-preview[data-media-style="player"] .waveform-skeleton::before,
  .preview-frame .mini-waveform span,
  .preview-frame .waveform-skeleton span,
  .preview-frame .media-output-controls div::before {
    animation: none;
  }
}

@keyframes preview-refresh-pulse {
  0% {
    opacity: 0.72;
    transform: translateY(4px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes assistant-stream-in {
  from {
    opacity: 0.35;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes assistant-typewriter-in {
  from {
    clip-path: inset(0 100% 0 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

@keyframes assistant-chunked-in {
  0% {
    opacity: 0.4;
    transform: translateY(4px);
  }
  45% {
    opacity: 0.72;
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@container preview-frame (max-width: 520px) {
  .composer-tools {
    gap: 3px;
  }

  .permission-mode-trigger,
  .budget-mode-trigger {
    gap: 3px;
    padding: 0 6px;
  }

  .permission-mode-trigger > span,
  .budget-mode-trigger > span,
  .provider-model-summary {
    display: none;
  }

  .provider-model-menu .ui-select {
    gap: 3px;
    padding: 0 8px;
  }

  .ui-button.send-button[data-size] {
    gap: 0;
    width: var(--control-md);
    padding: 0;
    font-size: 0;
  }
}

@media (max-width: 980px) {
  .app-shell {
    height: auto;
    min-height: 100vh;
  }

  .topbar,
  .debug-grid {
    grid-template-columns: 1fr;
  }

  .topbar {
    align-items: stretch;
    flex-direction: column;
  }

  .topbar-controls {
    justify-content: start;
    flex-wrap: wrap;
  }

  .workspace-layout {
    display: grid;
  }

  .builder-surface,
  .exported-shell {
    min-height: 900px;
  }
}

.error-boundary {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-start;
  max-width: 480px;
  margin: 48px auto;
  padding: 20px 22px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg, 14px);
  background: var(--surface-panel);
  color: var(--text-primary);
}

.error-boundary-title {
  margin: 0;
  font-weight: 700;
}

.error-boundary-detail {
  margin: 0;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  word-break: break-word;
}

.error-boundary-retry {
  margin-top: 4px;
  padding: 6px 14px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-full);
  background: var(--surface-raised);
  color: var(--text-primary);
  font-weight: 600;
  cursor: pointer;
}

/* ─── New-chat welcome state ────────────────────────────────────────────────
 * When a new chat is started the conversation is cleared (empty timeline) and
 * the preview stack is marked data-welcome. We hide the chat area and center
 * the composer, with an editable greeting rendered above it (project.welcome).
 */
.preview-stack[data-welcome="true"] {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  width: 100%;
  grid-template-rows: auto;
  align-content: center;
}

.preview-stack[data-welcome="true"]::before,
.preview-stack[data-welcome="true"]::before {
  top: 0;
  right: 0;
  width: 78%;
  height: 390px;
  opacity: 1;
  background:
    radial-gradient(1500px 1380px at 104% -48%, rgba(166, 202, 255, 0.6) 0%, rgba(166, 202, 255, 0) 42%),
    radial-gradient(620px 460px at 36% -18%, rgba(182, 255, 239, 0.3) 0%, rgba(182, 255, 239, 0) 46%);
  mask-image: linear-gradient(180deg, #000 0%, #000 54%, rgba(0, 0, 0, 0) 100%);
}

.preview-frame[data-style-preset="illustrated"] .preview-stack[data-welcome="true"]::before {
  display: none;
}

.preview-stack[data-welcome="true"] > .chat-frame {
  display: none;
}

.preview-stack[data-welcome="true"] {
  --composer-measure: min(660px, 100%);
}

/*
 * The welcome state centres the composer vertically; the approval panel is already in flow
 * above it, so the two centre together as one group and only need the gap.
 */
.preview-stack[data-welcome="true"] > .preview-approval-overlay {
  margin: 0 0 var(--space-2);
}

.preview-stack[data-welcome="true"] > .composer-frame {
  position: relative;
  z-index: 1;
  width: var(--composer-measure);
  justify-self: center;
  background: transparent;
}

/* Greeting hero: mascot icon + big bold title on one centered row, above input. */
.composer-greeting {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  margin: 0 0 var(--space-4);
  padding: 0 4px;
}

.composer-greeting-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 56px;
  height: 56px;
  border: 0;
  background: transparent !important;
  box-shadow: none;
  color: var(--accent);
}

.composer-greeting-avatar .orb-face,
.composer-greeting-avatar .robot-face,
.composer-greeting-avatar .active-robot-face,
.composer-greeting-avatar .robot-head-face,
.composer-greeting-avatar .custom-avatar-face {
  width: 100%;
  height: 100%;
  display: block;
}

.composer-greeting-avatar .agent-spark-avatar {
  width: 40px;
  height: 49px;
}

.composer-greeting-avatar .robot-face > circle:first-child {
  fill: transparent;
}

.composer-greeting-text {
  margin: 0;
  font-size: 28px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-primary);
}

/* "Welcome greeting" section inside the Input preset group. */
.welcome-settings {
  display: grid;
  gap: var(--space-2);
}

.welcome-field {
  display: grid;
  gap: 6px;
}

/* ------------------------------------------------------------------ *
 * Media output — clean load → present interaction (canvas)
 * Removes the old skeleton + framed border for image/audio/video and
 * plays a 2–3s spinner that fades into the presented demo asset.
 * ------------------------------------------------------------------ */
.preview-frame .image-output-preview,
.preview-frame .audio-output-preview,
.preview-frame .video-output-preview {
  display: grid;
  place-items: center;
  border: 0;
  padding: 0;
  overflow: visible;
  background: transparent;
  box-shadow: none;
}

.preview-frame .media-reveal {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 220px;
}

/* Sizes to the media so the shimmer develops in place (no empty framed box). */
.preview-frame .media-reveal-frame {
  position: relative;
  display: inline-grid;
  border-radius: var(--preview-media-radius);
}

.preview-frame .image-output-preview .media-reveal-frame {
  width: min(340px, 100%);
  min-height: 340px;
}

.preview-frame .media-reveal-stage {
  display: grid;
  place-items: center;
  gap: 14px;
  opacity: 0;
  transform: scale(0.99);
  filter: blur(10px);
  transition:
    opacity 720ms var(--ease-out),
    transform 720ms var(--ease-out),
    filter 720ms var(--ease-out);
  will-change: opacity, transform, filter;
}

.preview-frame .media-reveal[data-phase="ready"] .media-reveal-stage {
  opacity: 1;
  transform: none;
  filter: none;
}

/* "Generating" shimmer overlay — soft accent glow + light sweep, not a skeleton. */
.preview-frame .media-reveal-loading {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: var(--preview-media-radius);
  background:
    radial-gradient(130% 130% at 16% 12%, color-mix(in srgb, var(--accent) 26%, transparent), transparent 55%),
    radial-gradient(130% 130% at 84% 90%, color-mix(in srgb, var(--accent-hover) 20%, transparent), transparent 58%),
    color-mix(in srgb, var(--surface-panel) 84%, var(--preview-soft-fill));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 12%, transparent);
  animation: media-reveal-breathe 2.6s var(--ease-in-out) infinite;
  transition: opacity 460ms var(--ease-out);
}

.preview-frame .media-reveal[data-phase="ready"] .media-reveal-loading {
  opacity: 0;
  pointer-events: none;
}

.preview-frame .media-reveal-sheen {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    transparent 32%,
    color-mix(in srgb, var(--preview-shimmer-light) 60%, transparent) 48%,
    transparent 64%
  );
  transform: translateX(-120%);
  animation: media-reveal-sweep 1.9s var(--ease-in-out) infinite;
}

.preview-frame .media-reveal-indicator {
  position: relative;
  z-index: 1;
  display: grid;
  justify-items: center;
  gap: 10px;
}

.preview-frame .media-reveal-spinner {
  width: 26px;
  height: 26px;
  border-radius: 999px;
  border: 2.5px solid color-mix(in srgb, var(--accent) 22%, transparent);
  border-top-color: var(--accent);
  animation: media-reveal-spin 720ms linear infinite;
}

.preview-frame .media-reveal-label {
  font-size: var(--preview-meta-size);
  font-weight: 550;
  letter-spacing: 0.01em;
  color: color-mix(in srgb, var(--accent) 62%, var(--text-primary));
}

@keyframes media-reveal-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes media-reveal-breathe {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.82;
  }
}

@keyframes media-reveal-sweep {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(120%);
