.preview-frame[data-style-preset="studio"] :is(.permission-mode-trigger, .budget-mode-trigger, .provider-model-picker .ui-select):hover:not(:disabled) {
  background: var(--surface-inset);
}

.preview-frame[data-style-preset="studio"] :is(.permission-mode-trigger, .budget-mode-trigger, .provider-model-summary) :is(span, em, strong) {
  font-weight: 500;
}

.preview-frame[data-style-preset="studio"] .composer-menu-chevron {
  rotate: 90deg;
}

.preview-frame[data-style-preset="studio"] .ui-button.send-button[data-size] {
  flex: none;
  min-width: var(--st-h-action);
  min-height: var(--st-h-action);
  width: var(--st-h-action);
  height: var(--st-h-action);
  padding: 0;
  aspect-ratio: 1;
  border: var(--studio-edge) solid var(--st-ink);
  border-radius: var(--radius-full);
  box-shadow: var(--st-shadow-press);
}

.preview-frame[data-style-preset="studio"] .ui-button.send-button[data-size]:disabled {
