}

.preview-frame[data-style-preset="studio"] .send-button svg.lucide {
  color: inherit;
  stroke: currentColor;
  fill: currentColor;
}

.preview-frame[data-style-preset="studio"] .send-button[data-running="true"] svg.lucide rect {
  fill: currentColor;
}

.preview-frame[data-style-preset="studio"] .ui-dropdown-menu {
  max-width: calc(100cqi - var(--space-6));
  max-height: var(--radix-dropdown-menu-content-available-height);
  overflow-y: auto;
  border: var(--studio-edge) solid var(--st-ink);
  border-radius: var(--st-r-panel);
