}

.preview-frame[data-style-preset="retro"] .composer-upload {
  --retro-icon-image: url("/retro/composer-add.svg");
}

.preview-frame[data-style-preset="retro"] .composer-upload > * {
  display: none;
}

.preview-frame[data-style-preset="retro"] :is(
  .permission-mode-trigger,
  .budget-mode-trigger,
  .provider-model-picker .ui-select
)::before {
  display: block;
  width: var(--retro-icon);
  height: var(--retro-icon);
  flex: none;
  background-image: var(--retro-icon-image);
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  content: "";
}

.preview-frame[data-style-preset="retro"] .permission-mode-trigger {
  --retro-icon-image: url("/retro/permission.svg");
}

.preview-frame[data-style-preset="retro"] .budget-mode-trigger {
  --retro-icon-image: url("/retro/effort.svg");
}

.preview-frame[data-style-preset="retro"] .provider-model-picker .ui-select {
  --retro-icon-image: url("/retro/model.svg");
}

.preview-frame[data-style-preset="retro"] :is(
  .permission-mode-trigger > svg:not(.composer-menu-chevron),
  .budget-mode-trigger > svg:not(.composer-menu-chevron),
  .provider-model-picker .provider-model-icon
